INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (1, 1, 1, 'mcq', 'Bitwise Operations & Shift Logic', 'What is the result of evaluating `(16 >> 2) | (4 << 1)` in standard integer arithmetic?', NULL, '[{"id": 1, "text": "12"}, {"id": 2, "text": "14"}, {"id": 3, "text": "8"}, {"id": 4, "text": "16"}]'::jsonb, 'Easy', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.074069', '2026-08-20 13:59:34.074069') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (2, 1, 3, 'mcq', 'Binary Tree Traversal Deductions', 'A complete binary tree has 15 nodes. How many leaf nodes does this tree possess?', NULL, '[{"id": 1, "text": "7"}, {"id": 2, "text": "8"}, {"id": 3, "text": "9"}, {"id": 4, "text": "10"}]'::jsonb, 'Medium', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.094749', '2026-08-20 13:59:34.094749') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (3, 1, 2, 'mcq', 'Server Request Latency Calculation', 'A microservice cluster processes 1,200 requests per second across 4 parallel worker instances. Each instance handles requests synchronously at an average duration of 2.5ms. What is the CPU utilization per instance?', NULL, '[{"id": 1, "text": "50%"}, {"id": 2, "text": "75%"}, {"id": 3, "text": "80%"}, {"id": 4, "text": "90%"}]'::jsonb, 'Medium', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.105263', '2026-08-20 13:59:34.105263') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (320, 24, 76, 'coding', 'Q31: Remove Duplicates from a Sorted Array', 'Modify sorted array in-place and print unique elements count followed by the unique elements.\n\nInput Format:\nFirst line integer N.\nSecond line N sorted integers.\n\nOutput Format:\nUnique count on line 1, unique elements on line 2.\n\nExample 1:\nInput:\n5\n1 1 2 2 3\nOutput:\n3\n1 2 3', '#include <stdio.h>

int removeDuplicates(int arr[], int n) {
    if (n == 0) return 0;
    int idx = 0;
    for (int i = 1; i < n; i++) {
        if (arr[i] != arr[idx]) {
            idx++;
            arr[idx] = arr[i];
        }
    }
    return idx + 1;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int arr[1000];
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
    int k = removeDuplicates(arr, n);
    printf("%d\n", k);
    for (int i = 0; i < k; i++) printf("%d%s", arr[i], (i == k - 1) ? "" : " ");
    printf("\n");
    return 0;
}
', NULL, 'Medium', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.840657', '2026-09-14 15:06:17.840657') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (5, 2, 5, 'coding', 'Valid Anagram Checker', '### Problem Statement
Given two strings `s` and `t`, return `true` if `t` is an anagram of `s`, and `false` otherwise.
An anagram is a word or phrase formed by rearranging the letters of a different word or phrase, using all the original letters exactly once.

### Input Format
- Line 1: String `s`
- Line 2: String `t`

### Output Format
- Print `true` or `false` (lowercase).
', 'import sys

def solve():
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        return
    s = lines[0].strip()
    t = lines[1].strip()
    
    # Write your solution here
    if sorted(s) == sorted(t):
        print("true")
    else:
        print("false")

if __name__ == ''__main__'':
    solve()
', '[]'::jsonb, 'Easy', 15.0, 2, 1, 'Active', '2026-08-20 13:59:34.129651', '2026-08-20 13:59:34.129651') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (7, 3, 11, 'mcq', 'REST API Idempotency', 'Which HTTP method is defined as idempotent according to RFC 7231 standards?', NULL, '[{"id": 1, "text": "POST"}, {"id": 2, "text": "PATCH"}, {"id": 3, "text": "PUT"}, {"id": 4, "text": "CONNECT"}]'::jsonb, 'Easy', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.149852', '2026-08-20 13:59:34.149852') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (10, 5, 16, 'mcq', 'R1-Q01: Subject-Verb Agreement', 'Choose the grammatically correct sentence for customer communication:', '', '[{"id": 1, "text": "Neither the order number nor the tracking details is available in the system."}, {"id": 2, "text": "Neither the order number nor the tracking details are available in the system."}, {"id": 3, "text": "Neither the order number nor the tracking details were being available."}, {"id": 4, "text": "Neither the order number or tracking details are available."}]'::jsonb, 'Easy', 1.0, 60, 1, 'Active', '2026-08-20 13:59:34.192752', '2026-08-20 13:59:34.192752') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (11, 5, 16, 'mcq', 'R1-Q02: Past Participle & Tense', 'Select the correct sentence to confirm a processed refund:', '', '[{"id": 1, "text": "Our accounts team has already did the refund yesterday."}, {"id": 2, "text": "Our accounts team has already processed the refund yesterday."}, {"id": 3, "text": "Our accounts team has already processed your refund."}, {"id": 4, "text": "Our accounts team have already process your refund."}]'::jsonb, 'Easy', 1.0, 60, 1, 'Active', '2026-08-20 13:59:34.199658', '2026-08-20 13:59:34.199658') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (12, 5, 16, 'mcq', 'R1-Q03: Preposition Accuracy', 'Identify the correct preposition for shipping timeframe:', '', '[{"id": 1, "text": "Your replacement package will be delivered on 3 to 5 business days."}, {"id": 2, "text": "Your replacement package will be delivered within 3 to 5 business days."}, {"id": 3, "text": "Your replacement package will be delivered inside 3 to 5 business days."}, {"id": 4, "text": "Your replacement package will be delivered at 3 to 5 business days."}]'::jsonb, 'Easy', 1.0, 60, 1, 'Active', '2026-08-20 13:59:34.205607', '2026-08-20 13:59:34.205607') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (13, 5, 16, 'mcq', 'R1-Q04: Pronoun Agreement', 'Select the sentence with proper pronoun agreement:', '', '[{"id": 1, "text": "Every customer must verify their account before we can share order details."}, {"id": 2, "text": "Every customer must verify there account before we can share order details."}, {"id": 3, "text": "Every customer must verify they''re account before we can share order details."}, {"id": 4, "text": "Every customer have to verify their accounts."}]'::jsonb, 'Easy', 1.0, 60, 1, 'Active', '2026-08-20 13:59:34.209834', '2026-08-20 13:59:34.209834') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (14, 5, 16, 'mcq', 'R1-Q05: Punctuation & Clarity', 'Which option uses professional punctuation for customer reassurance?', '', '[{"id": 1, "text": "Don''t worry I will check your account, and update you in a minute!"}, {"id": 2, "text": "Please rest assured; I am currently checking your order details and will update you shortly."}, {"id": 3, "text": "Please rest assured I am checking your order details, and will update you shortly?"}, {"id": 4, "text": "Rest assured, I am checking your details and updating you: shortly."}]'::jsonb, 'Easy', 1.0, 60, 1, 'Active', '2026-08-20 13:59:34.219682', '2026-08-20 13:59:34.219682') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (6, 3, 7, 'mcq', 'Database Indexing Performance', 'Which of the following index structures is standardly utilized in PostgreSQL for handling range queries (e.g. `WHERE age BETWEEN 20 AND 30`) efficiently?', NULL, '[{"id": 1, "text": "Hash Index"}, {"id": 2, "text": "B-Tree Index"}, {"id": 3, "text": "GIN Index"}, {"id": 4, "text": "BRIN Index"}]'::jsonb, 'Hard', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.146756', '2026-09-06 10:38:10.427517') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (8, 3, 9, 'mcq', 'Operating Systems Deadlock Conditions', 'Which of the following is NOT one of Coffman''s four necessary conditions for deadlock?', NULL, '[{"id": 1, "text": "Mutual Exclusion"}, {"id": 2, "text": "Hold and Wait"}, {"id": 3, "text": "Preemption Allowed"}, {"id": 4, "text": "Circular Wait"}]'::jsonb, 'Easy', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.159765', '2026-09-06 10:38:10.427517') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (9, 4, 13, 'debugging', 'Fix Binary Search Boundary Condition', '### Scenario: Broken Binary Search
A junior developer wrote the following binary search routine, but it enters an infinite loop or produces incorrect indices on several edge cases.

### Bug Description
Identify and fix the pointer update and loop condition bugs so the routine returns the exact index of `target`, or `-1` if not found.

### Input Format
- Line 1: Sorted space-separated integers
- Line 2: Target integer
', 'import sys

def binary_search(arr, target):
    left = 0
    right = len(arr) - 1
    
    # FIX THE BUGGY IMPLEMENTATION BELOW:
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def solve():
    lines = sys.stdin.read().splitlines()
    if not lines: return
    arr = list(map(int, lines[0].split()))
    target = int(lines[1].strip())
    print(binary_search(arr, target))

if __name__ == ''__main__'':
    solve()
', '[]'::jsonb, 'Hard', 10.0, 2, 1, 'Active', '2026-08-20 13:59:34.177829', '2026-09-08 14:32:02.351346') ON CONFLICT DO NOTHING;
