INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (48, 7, 23, 'sop_case', 'R3-SOP01: SOP Case 1: Return Window Eligibility (Electronics)', 'SOP Reference: KB-RET-01 (Return Windows)
Policy: Consumer electronics are eligible for return within 30 days of delivery. Returns requested between 31-45 days are eligible for Store Credit only. Returns after 45 days are strictly ineligible.

Case Details:
Customer purchased a DSLR camera delivered 38 days ago. Item is in original packaging.

What is the compliant resolution and required documentation?', '', '[{"id": 1, "text": "Issue full refund to original credit card; Tag: REFUND_ORIGINAL"}, {"id": 2, "text": "Approve return for Store Credit only; Tag: RETURN_STORE_CREDIT; Internal Note: ''Camera delivered 38 days ago (31-45 day window). Approved store credit per KB-RET-01.''"}, {"id": 3, "text": "Reject return completely; Tag: RETURN_REJECTED"}, {"id": 4, "text": "Tell customer to sell it online."}]'::jsonb, 'Easy', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.529628', '2026-09-06 10:38:10.592958') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (357, 25, 77, 'debugging', 'D08: Factorial', 'Problem Statement:
Calculate the factorial of a number.

Debug Hint:
The factorial is always incorrect. Multiplication by zero neutralizes subsequent products.', '#include <stdio.h>

int main() {
    int n = 5;
    int fact = 0;

    for (int i = 1; i <= n; i++)
        fact = fact * i;

    printf("Factorial = %d", fact);

    return 0;
}', '{"debug_hint": "The factorial is always incorrect. Multiplication by zero neutralizes subsequent products.", "problem": "Calculate the factorial of a number."}'::jsonb, 'Easy', 10.0, 300, 1, 'Active', '2026-09-14 16:37:35.602332', '2026-09-14 16:37:35.602332') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (358, 25, 77, 'debugging', 'D09: Reverse a Number', 'Problem Statement:
Reverse the digits of an integer.

Debug Hint:
The program calculates the wrong result. The existing reversed digits must shift left in base 10.', '#include <stdio.h>

int main() {
    int n = 1234;
    int rev = 0;

    while (n > 0) {
        int digit = n % 10;
        rev = rev + digit;
        n = n / 10;
    }

    printf("Reverse = %d", rev);

    return 0;
}', '{"debug_hint": "The program calculates the wrong result. The existing reversed digits must shift left in base 10.", "problem": "Reverse the digits of an integer."}'::jsonb, 'Easy', 10.0, 300, 1, 'Active', '2026-09-14 16:37:35.609067', '2026-09-14 16:37:35.609067') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (54, 7, 28, 'sop_case', 'R3-SOP07: SOP Case 7: Fraud Alert - Stolen Card Claim', 'SOP Reference: KB-SEC-05 (Fraud Protocol)
Policy: If a contact claims their credit card was used fraudulently on our site without authorization, agent MUST: 1) Immediately cancel unshipped orders, 2) Freeze account, 3) Escalate to Trust & Safety team. Never argue or disclose fraudster''s shipping address to the caller.

Case Details:
Caller states: ''Someone made a $400 charge on my Visa card at your store.''

What is the compliant protocol?', '', '[{"id": 1, "text": "Read out the thief''s delivery address to the caller."}, {"id": 2, "text": "Locate transaction by transaction ID / last 4 digits of card, halt shipment, apply fraud freeze, and route ticket to Trust & Safety team. Advise caller to contact card issuer for chargeback."}, {"id": 3, "text": "Tell caller it is their own bank''s problem."}, {"id": 4, "text": "Ignore the claim if order is already packed."}]'::jsonb, 'Medium', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.580861', '2026-08-20 13:59:34.580861') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (55, 7, 23, 'sop_case', 'R3-SOP08: SOP Case 8: Hazardous Material / Battery Return Policy', 'SOP Reference: KB-RET-04 (Hazardous Materials)
Policy: Lithium-ion batteries that are swollen, punctured, or leaking CANNOT be shipped via standard postal returns due to federal air transport safety regulations. Customer must dispose safely locally; agent issues direct replacement/refund upon photo confirmation.

Case Details:
Customer reports laptop battery is swollen and bulging out of the case.

What is the compliant safety action?', '', '[{"id": 1, "text": "Ask customer to put swollen battery in a cardboard box and ship via standard mail."}, {"id": 2, "text": "Instruct customer to safely stop using device, do not mail back due to hazardous materials regulations, request photo for compliance, and process replacement unit."}, {"id": 3, "text": "Tell customer to throw it in regular trash bin."}, {"id": 4, "text": "Refuse refund until physical battery arrives at warehouse."}]'::jsonb, 'Medium', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.583699', '2026-08-20 13:59:34.583699') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (78, 10, 8, 'mcq', 'SQL Aggregation & Having Filter Completion', 'Given the query template below to calculate total sales per customer and filter for customers with total revenue strictly greater than $1,000:

```sql
SELECT customer_id, SUM(amount) AS total_revenue
FROM orders
GROUP BY {{BLANK_1}}
HAVING {{BLANK_2}}
ORDER BY total_revenue DESC;
```

Which pair of clauses correctly fills in `{{BLANK_1}}` and `{{BLANK_2}}`?', NULL, '[{"key": "A", "text": "BLANK_1: customer_id  |  BLANK_2: SUM(amount) > 1000"}, {"key": "B", "text": "BLANK_1: total_revenue  |  BLANK_2: total_revenue > 1000"}, {"key": "C", "text": "BLANK_1: customer_id  |  BLANK_2: WHERE SUM(amount) > 1000"}, {"key": "D", "text": "BLANK_1: orders.id  |  BLANK_2: COUNT(amount) > 1000"}]'::jsonb, 'Medium', 2.0, 300, 1, 'Active', '2026-08-20 13:59:34.805712', '2026-09-08 14:58:17.260028') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (57, 7, 25, 'sop_case', 'R3-SOP10: SOP Case 10: Address Correction After Dispatch', 'SOP Reference: KB-LOG-02 (In-Transit Address Modifications)
Policy: Address modifications cannot be made directly in warehouse system once carrier has received shipment. Agent must submit carrier package redirect request ($10 fee charged by carrier, waived if error was warehouse fault).

Case Details:
Customer entered wrong street number during checkout and package is on delivery truck.

What is the SOP action?', '', '[{"id": 1, "text": "Edit address in internal database and tell customer it will arrive today."}, {"id": 2, "text": "Inform customer package is in carrier possession; initiate carrier package reroute request via carrier API portal and set expectation of 24-hour delay."}, {"id": 3, "text": "Tell customer to run after delivery truck."}, {"id": 4, "text": "Cancel shipment and keep the money."}]'::jsonb, 'Hard', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.601466', '2026-08-20 13:59:34.601466') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (58, 7, 23, 'sop_case', 'R3-SOP11: SOP Case 11: International Duty & Customs Taxes', 'SOP Reference: KB-INT-01 (Customs & Import Duties)
Policy: For DDP (Delivered Duty Paid) shipping, our store pays all customs taxes upfront. If local carrier mistakenly demands payment from customer upon delivery, agent verifies receipt and reimburses customer immediately.

Case Details:
Canadian customer with DDP shipping was charged $28 CAD import tax by DHL courier.

What is the correct resolution?', '', '[{"id": 1, "text": "Tell customer international taxes are always their responsibility."}, {"id": 2, "text": "Confirm DDP shipping was selected, request photo of DHL customs tax receipt, and issue immediate $28 CAD credit adjustment to customer."}, {"id": 3, "text": "Tell customer to refuse delivery and return package."}, {"id": 4, "text": "Advise customer to contact Canadian government."}]'::jsonb, 'Hard', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.608621', '2026-08-20 13:59:34.608621') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (279, 26, 82, 'HARDWARE_SELECTION_PLACEMENT', 'Task 07: Smart Building DALI Lighting & Triac HVAC Controller', '### Problem Statement
Implement a commercial building ceiling controller managing addressable architectural lighting via the DALI (Digital Addressable Lighting Interface) bus, regulating 3-speed HVAC fan coil units via AC Triac phase dimming, and bridging to the BMS over Ethernet.

### Technical Specifications
- **MCU**: Real-time 32-bit ARM Cortex-M4 microcontroller.
- **Lighting Bus**: Opto-isolated DALI transceiver translating 16V Manchester protocol.
- **Fan Control**: Zero-crossing detected AC Triac dimmer module for continuous AC motor modulation.
- **BMS Bridge**: SPI Ethernet controller with hardware TCP/IP stack.
- **Power**: Industrial 230VAC to 5VDC encapsulated converter.', NULL, '{"task_id": "IOT-TASK-07", "domain": "iot-hardware-systems", "round_type": "HARDWARE_SELECTION_PLACEMENT", "motherboard_config": {"board_id": "BOARD-BMS-DALI-V1", "board_name": "Commercial Building Automation PCB", "slots": [{"slot_id": "SLOT_MCU", "label": "MCU Socket", "supported_types": ["MICROCONTROLLER"], "pin_bus": "3.3V, GND, SPI, UART, Timer PWM, GPIO"}, {"slot_id": "SLOT_DALI_BUS", "label": "DALI Fieldbus Header", "supported_types": ["COMMUNICATION"], "pin_bus": "16V_DALI+, 16V_DALI-, TX, RX (Optoisolated)"}, {"slot_id": "SLOT_TRIAC_AC", "label": "Zero-Cross AC Triac Port", "supported_types": ["ACTUATOR_AC"], "pin_bus": "SYNC_INT, GATE_TRIG, AC_L, AC_N"}, {"slot_id": "SLOT_SPI_NET", "label": "SPI Ethernet Module Slot", "supported_types": ["COMMUNICATION"], "pin_bus": "MOSI, MISO, SCK, CS (PB12), INT"}, {"slot_id": "SLOT_PWR_SUPPLY", "label": "Encapsulated AC-DC Port", "supported_types": ["POWER_MODULE"], "pin_bus": "AC_LINE, AC_NEUT, +5V_OUT, GND"}]}, "component_palette": [{"component_id": "COMP_STM32F407", "name": "STM32F407VET6 ARM Cortex-M4", "category": "MICROCONTROLLER", "image_url": "/assets/components/stm32f4.png", "specifications": "168MHz ARM Cortex-M4, advanced timers, 3x SPI"}, {"component_id": "COMP_DALI_OPTO", "name": "Opto-Isolated DALI Bus Transceiver", "category": "COMMUNICATION", "image_url": "/assets/components/dali.png", "specifications": "16V Manchester encoded protocol, 1200 baud"}, {"component_id": "COMP_TRIAC_DIMMER", "name": "Zero-Cross AC Triac Phase Dimmer Module", "category": "ACTUATOR_AC", "image_url": "/assets/components/triac.png", "specifications": "Optocoupled zero-cross detector + BTA16 Triac"}, {"component_id": "COMP_W5500_ETH", "name": "WIZnet W5500 SPI Ethernet Controller", "category": "COMMUNICATION", "image_url": "/assets/components/w5500.png", "specifications": "Hardwired TCP/IP stack, 10/100 Ethernet RJ45"}, {"component_id": "COMP_MEANWELL_ACDC", "name": "Mean Well 230V-to-5V Encapsulated AC-DC", "category": "POWER_MODULE", "image_url": "/assets/components/meanwell.png", "specifications": "4kVAC medical/industrial isolation barrier"}, {"component_id": "COMP_PWM_MOSFET", "name": "Standard PWM Power MOSFET (Distractor)", "category": "ACTUATOR_AC", "image_url": "/assets/components/mosfet.png", "specifications": "DC only switching (Blows on 230V AC load)"}, {"component_id": "COMP_NRF24_RF", "name": "NRF24L01 2.4GHz RF (Distractor)", "category": "COMMUNICATION", "image_url": "/assets/components/nrf24.png", "specifications": "Wireless module (Prohibited in shielded risers)"}, {"component_id": "COMP_1CH_RELAY", "name": "Single Channel Relay (Distractor)", "category": "ACTUATOR_AC", "image_url": "/assets/components/relay.png", "specifications": "On/Off only (Cannot do variable speed fan control)"}]}'::jsonb, 'Medium', 2.0, 180, 1, 'Active', '2026-09-09 08:30:21.487088', '2026-09-09 08:30:21.487088') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (60, 7, 29, 'sop_case', 'R3-SOP13: SOP Case 13: Chargeback Dispute Notification', 'SOP Reference: KB-BIL-06 (Active Bank Disputes)
Policy: When a customer files a formal chargeback with their bank, the account enters legal dispute status. Agents CANNOT process manual refunds or exchanges in chat while dispute is active, as bank holds the funds. Must route to Dispute Management.

Case Details:
Customer states: ''I filed a chargeback with Chase Bank yesterday, but give me my money now.''

What is the required SOP handling?', '', '[{"id": 1, "text": "Issue a full refund on top of the active chargeback."}, {"id": 2, "text": "Explain politely that because a formal bank dispute is active, the funds are held under bank review and manual refunds are locked. Route ticket to Dispute Management Team for bank response filing."}, {"id": 3, "text": "Threaten the customer with legal lawsuit in chat."}, {"id": 4, "text": "Ignore the customer message."}]'::jsonb, 'Hard', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.622328', '2026-08-20 13:59:34.622328') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (61, 7, 25, 'sop_case', 'R3-SOP14: SOP Case 14: Subscription Cancellation and Prorated Refunds', 'SOP Reference: KB-SUB-02 (SaaS/Software Subscription Policy)
Policy: Annual software subscriptions cancelled within first 14 days receive 100% refund. Cancellations between 15-90 days receive prorated refund for unused months. Cancellations after 90 days cancel future auto-renewals only with no refund.

Case Details:
Customer cancels annual subscription on day 45 of 365.

What is the correct refund entitlement?', '', '[{"id": 1, "text": "Zero refund; annual subscriptions are non-refundable."}, {"id": 2, "text": "Calculate prorated refund for the remaining 10 full unused months per KB-SUB-02 and disable future renewal."}, {"id": 3, "text": "100% full refund."}, {"id": 4, "text": "Charge cancellation penalty fee."}]'::jsonb, 'Hard', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.629481', '2026-08-20 13:59:34.629481') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (62, 7, 29, 'sop_case', 'R3-SOP15: SOP Case 15: Escalation Matrix - Priority 1 System Outage', 'SOP Reference: KB-ESC-01 (Severity Classification)
Policy: Severity 1 (Critical) is reserved for system-wide outages affecting checkout, multiple user data corruption, or payment gateway crash. Must alert On-Call Engineering within 5 minutes with incident ticket.

Case Details:
Multiple customers simultaneously report credit card checkout throwing ''502 Gateway Error''.

What is the correct escalation tier and SLA?', '', '[{"id": 1, "text": "Classify as Low priority ticket for next business day review."}, {"id": 2, "text": "Tag as P1 - Critical System Outage, notify On-Call Engineering team immediately, and broadcast status banner."}, {"id": 3, "text": "Tell customers to restart their personal laptops."}, {"id": 4, "text": "Ignore reports until supervisor arrives."}]'::jsonb, 'Hard', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.632768', '2026-08-20 13:59:34.632768') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (63, 8, 27, 'multi_chat_simulation', 'R4-SIM: Production Multi-Chat Support Console', '[{"session_id": "CHAT-A", "customer_name": "Jessica Miller", "market": "USA (Chicago, IL)", "order_id": "#US-94821", "order_amount": "$289.00", "initial_state": "ACTIVE", "priority": "HIGH", "issue_category": "DELIVERY", "sla_first_response_sec": 60, "sla_resolution_min": 12, "timeline": [{"time_sec": 0, "sender": "customer", "message": "Hi, my package was supposed to be delivered yesterday for an anniversary gift. Tracking says ''Delayed in Transit''. Can someone please tell me where it is?"}, {"time_sec": 45, "trigger": "if_no_response", "message": "Hello? Is anyone there? I really need an update."}, {"time_sec": 120, "sender": "customer", "message": "I checked with my neighbors and nobody has seen the FedEx truck. Can you check if it''s lost?"}, {"time_sec": 240, "sender": "customer", "message": "If this can''t arrive by tomorrow, I want to cancel and get a replacement sent to my office address."}], "correct_resolution": {"ticket_category": "Delivery", "priority": "High", "resolution_code": "Replacement Initiated / Lost in Transit", "required_kb_search": "Lost in Transit", "required_internal_note": "Package delayed >48h with FedEx. Verified address. Issued replacement with priority overnight."}}, {"session_id": "CHAT-B", "customer_name": "Alexander Hayes", "market": "Canada (Vancouver, BC)", "order_id": "#CA-40291", "order_amount": "$145.50", "initial_state": "WAITING", "priority": "URGENT", "issue_category": "BILLING", "sla_first_response_sec": 45, "sla_resolution_min": 10, "timeline": [{"time_sec": 30, "sender": "customer", "message": "I was promised a refund of $145.50 last Tuesday by your agent Mark. My credit card statement arrived today and there is NO refund. Why are you holding my money?"}, {"time_sec": 90, "sender": "customer", "message": "I have the chat transcript from Mark saying it would take 3 business days. It has been 6 business days!"}, {"time_sec": 180, "sender": "customer", "message": "Give me the ARN refund reference number so I can give it to my bank."}], "correct_resolution": {"ticket_category": "Billing / Refund", "priority": "Critical", "resolution_code": "Refund Verified / Acquirer Reference Provided", "required_kb_search": "Refund Pending", "required_internal_note": "Checked merchant gateway. Refund was processed on Friday. Provided ARN #749281920 to customer. Reassured 3-5 bank processing days."}}, {"session_id": "CHAT-C", "customer_name": "Daniel Kim", "market": "USA (Austin, TX)", "order_id": "#US-77182", "order_amount": "$89.99", "initial_state": "WAITING", "priority": "NORMAL", "issue_category": "WARRANTY", "sla_first_response_sec": 90, "sla_resolution_min": 15, "timeline": [{"time_sec": 60, "sender": "customer", "message": "Hey there! My wireless earbuds keep disconnecting from Bluetooth every 5 minutes. Bought them 2 months ago."}, {"time_sec": 180, "sender": "customer", "message": "I already tried forgetting device and reconnecting. Still drops connection."}, {"time_sec": 300, "sender": "customer", "message": "I have the original box and receipt from Best Buy online store."}], "correct_resolution": {"ticket_category": "Warranty / Hardware", "priority": "Normal", "resolution_code": "Warranty Replacement Approved", "required_kb_search": "Warranty Eligibility", "required_internal_note": "Bluetooth disconnection unresolved by hardware reset. Unit within 1-year warranty. Generated prepaid RMA label and warranty replacement."}}]', '', '[]'::jsonb, 'Hard', 30.0, 3000, 1, 'Active', '2026-08-20 13:59:34.658368', '2026-08-20 13:59:34.658368') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (280, 26, 79, 'HARDWARE_SELECTION_PLACEMENT', 'Task 08: Industrial IIoT RS-485 Modbus Predictive Vibration Analyzer', '### Problem Statement
Engineer an industrial edge vibration analyzer for high-speed induction motor bearings. The node must sample 3-axis high-frequency piezoelectric acceleration via an external 16-bit differential Delta-Sigma ADC, read stator winding temperature over an RTD PT100 Kelvin bridge, stream Modbus RTU telemetry over a galvanically isolated RS-485 line, and operate off dirty 24VDC factory power.

### Technical Specifications
- **Core**: 32-bit ARM Cortex-M4 with hardware FPU and DSP instructions for on-chip FFT analysis.
- **Fieldbus**: Galvanically isolated differential RS-485 transceiver (ISO3082) with fail-safe biasing.
- **Vibration AFE**: 16-bit Delta-Sigma ADC with programmable gain amplifier (PGA).
- **Transducer**: Piezoelectric charge-mode accelerometer with integrated charge amplifier.
- **Thermal Interface**: Precision SPI RTD temperature signal converter (MAX31865) for 4-wire PT100 probe.
- **Power Supply**: Wide-input industrial step-down switching buck regulator (24VDC to 3.3VDC).', NULL, '{"task_id": "IOT-TASK-08", "domain": "iot-hardware-systems", "round_type": "HARDWARE_SELECTION_PLACEMENT", "motherboard_config": {"board_id": "BOARD-IIOT-MODBUS-V3", "board_name": "Industrial Modbus Vibration Carrier PCB", "slots": [{"slot_id": "SLOT_MCU", "label": "DSP MCU Socket", "supported_types": ["MICROCONTROLLER"], "pin_bus": "3.3V, GND, SPI, I2C, USART_MODBUS, DMA"}, {"slot_id": "SLOT_RS485_BUS", "label": "RS-485 Differential Port", "supported_types": ["COMMUNICATION"], "pin_bus": "A, B, GND_ISO, TX, RX, DE_RE"}, {"slot_id": "SLOT_I2C_ADC", "label": "16-Bit Diff ADC Slot", "supported_types": ["ANALOG_AFE"], "pin_bus": "3.3V, GND, SCL, SDA, ALERT/RDY, AIN0, AIN1"}, {"slot_id": "SLOT_ANALOG_IN", "label": "Piezo Transducer Header", "supported_types": ["PIEZO_SENSOR"], "pin_bus": "EXC+, SIG+, SIG-, SHIELD"}, {"slot_id": "SLOT_SPI_TEMP", "label": "RTD PT100 SPI Header", "supported_types": ["SPI_SENSOR"], "pin_bus": "MOSI, MISO, SCK, CS (PA4), RTD+, RTD-"}, {"slot_id": "SLOT_IND_POWER", "label": "24V Industrial Buck Port", "supported_types": ["POWER_MODULE"], "pin_bus": "24V_IN, 3V3_REG, GND_RAW, GND_REG"}]}, "component_palette": [{"component_id": "COMP_STM32F401", "name": "STM32F401 Nucleo-32 ARM Cortex-M4", "category": "MICROCONTROLLER", "image_url": "/assets/components/stm32f401.png", "specifications": "84MHz Cortex-M4 with FPU, DSP math instructions"}, {"component_id": "COMP_ISO3082", "name": "ISO3082 Galvanically Isolated RS-485 Transceiver", "category": "COMMUNICATION", "image_url": "/assets/components/iso3082.png", "specifications": "2.5kVRMS galvanic isolation, half duplex differential"}, {"component_id": "COMP_ADS1115", "name": "ADS1115 16-Bit Differential Delta-Sigma ADC", "category": "ANALOG_AFE", "image_url": "/assets/components/ads1115.png", "specifications": "16-bit resolution, 860 SPS, internal PGA"}, {"component_id": "COMP_PIEZO_AMP", "name": "Piezoelectric Accelerometer with Charge Amp", "category": "PIEZO_SENSOR", "image_url": "/assets/components/piezo.png", "specifications": "100mV/g sensitivity, 10kHz resonant bandwidth"}, {"component_id": "COMP_MAX31865", "name": "MAX31865 RTD PT100 SPI Amplifier", "category": "SPI_SENSOR", "image_url": "/assets/components/max31865.png", "specifications": "15-bit RTD-to-digital converter, 4-wire Kelvin sensing"}, {"component_id": "COMP_LM2596_BUCK", "name": "LM2596 Isolated 24V-to-3.3V Step-Down Buck", "category": "POWER_MODULE", "image_url": "/assets/components/buck24.png", "specifications": "High efficiency switching regulator for 24V industrial supply"}, {"component_id": "COMP_ESP8266", "name": "ESP8266 Module (Distractor)", "category": "MICROCONTROLLER", "image_url": "/assets/components/esp8266.png", "specifications": "No hardware FPU/DSP for high-speed FFT analysis"}, {"component_id": "COMP_MAX485_RAW", "name": "MAX485 Non-Isolated (Distractor)", "category": "COMMUNICATION", "image_url": "/assets/components/max485.png", "specifications": "Lacks galvanic isolation; burns on ground potential differences"}, {"component_id": "COMP_NTC_10K", "name": "10k NTC Thermistor (Distractor)", "category": "SPI_SENSOR", "image_url": "/assets/components/ntc.png", "specifications": "Non-linear analog sensor (Inaccurate at 150\u00b0C motor temps)"}, {"component_id": "COMP_7805_LIN", "name": "Linear 7805 (Distractor)", "category": "POWER_MODULE", "image_url": "/assets/components/7805.png", "specifications": "Linear drop generates excessive heat and thermal shutdown"}, {"component_id": "COMP_CH340", "name": "CH340 USB-UART (Distractor)", "category": "COMMUNICATION", "image_url": "/assets/components/ch340.png", "specifications": "Single-ended consumer USB chip"}]}'::jsonb, 'Hard', 4.0, 300, 1, 'Active', '2026-09-09 08:30:21.494024', '2026-09-09 08:30:21.494024') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (281, 26, 79, 'HARDWARE_SELECTION_PLACEMENT', 'Task 09: Automotive CAN-Bus OBD-II Telematics & Crash Logger', '### Problem Statement
Assemble a vehicular Telematics Control Unit (TCU) that taps into the high-speed powertrain CAN network (500kbps ISO 11898-2), records sudden deceleration and crash vectors on a +/-200g crash sensor, buffers blackbox telemetry on non-volatile SPI flash, streams cellular coordinates to the cloud, and survives automotive load-dump alternator voltage spikes.

### Technical Specifications
- **SoC**: High-throughput ARM Cortex-M7 embedded controller.
- **Vehicle Bus**: Standalone SPI CAN Controller + High-Speed CAN Transceiver (MCP2515 + TJA1050).
- **Crash Sensor**: High-g 3-axis accelerometer rated up to +/-200g with hardware threshold interrupts.
- **Non-Volatile Storage**: 128Mbit SPI NOR Flash memory with 104MHz clock speed.
- **Cellular / GNSS**: Multi-band LTE Cat-M1/NB-IoT modem with GNSS positioning.
- **Automotive Power**: Transient Voltage Suppressor (TVS) clamping and automotive buck regulator.', NULL, '{"task_id": "IOT-TASK-09", "domain": "iot-hardware-systems", "round_type": "HARDWARE_SELECTION_PLACEMENT", "motherboard_config": {"board_id": "BOARD-AUTO-TCU-V2", "board_name": "Automotive OBD-II Telematics PCB", "slots": [{"slot_id": "SLOT_MCU", "label": "Compute Core Socket", "supported_types": ["MICROCONTROLLER"], "pin_bus": "3.3V, GND, SPI0, SPI1, UART, INT"}, {"slot_id": "SLOT_SPI_CAN", "label": "High-Speed CAN Port (SPI0)", "supported_types": ["COMMUNICATION"], "pin_bus": "CAN_H, CAN_L, MOSI, MISO, SCK, CS (D10), INT"}, {"slot_id": "SLOT_SPI_IMU", "label": "High-g Crash Sensor (SPI1)", "supported_types": ["SPI_SENSOR"], "pin_bus": "MOSI, MISO, SCK, CS (D9), INT1, INT2"}, {"slot_id": "SLOT_SPI_STORAGE", "label": "Blackbox SPI Flash Slot", "supported_types": ["SPI_STORAGE"], "pin_bus": "MOSI, MISO, SCK, CS (D8), WP, HOLD"}, {"slot_id": "SLOT_UART_CELL", "label": "LTE-M & GNSS Modem Port", "supported_types": ["COMMUNICATION"], "pin_bus": "4V_VBAT, GND, TX (D0), RX (D1), PWRKEY"}, {"slot_id": "SLOT_AUTO_POWER", "label": "Automotive TVS Buck Port", "supported_types": ["POWER_MODULE"], "pin_bus": "12V_RAW, ISO7637_TVS, 3V3_OUT, 4V_MODEM, GND"}]}, "component_palette": [{"component_id": "COMP_TEENSY_40", "name": "Teensy 4.0 (600MHz Cortex-M7)", "category": "MICROCONTROLLER", "image_url": "/assets/components/teensy.png", "specifications": "NXP i.MX RT1062, 600MHz, 3x SPI, dual CAN controllers"}, {"component_id": "COMP_MCP2515_CAN", "name": "MCP2515 + TJA1050 Isolated SPI CAN Module", "category": "COMMUNICATION", "image_url": "/assets/components/can.png", "specifications": "ISO 11898-2 high-speed CAN, 500kbps-1Mbps"}, {"component_id": "COMP_ADXL375", "name": "ADXL375 +/-200g High-g Shock/Crash Sensor", "category": "SPI_SENSOR", "image_url": "/assets/components/adxl375.png", "specifications": "High-impact vehicular collision measurement up to 200g"}, {"component_id": "COMP_W25Q128", "name": "W25Q128 128Mbit SPI NOR Flash", "category": "SPI_STORAGE", "image_url": "/assets/components/w25q128.png", "specifications": "104MHz SPI, 100,000 write endurance, blackbox logging"}, {"component_id": "COMP_SIM7080G", "name": "SIM7080G Cat-M1/NB-IoT + GNSS Multi-Band Modem", "category": "COMMUNICATION", "image_url": "/assets/components/sim7080.png", "specifications": "LTE Cat-M1, NB-IoT, BeiDou/GPS GNSS tracking"}, {"component_id": "COMP_AUTO_TVS_BUCK", "name": "Automotive TVS Diode + Buck Regulator (ISO 7637-2)", "category": "POWER_MODULE", "image_url": "/assets/components/autobuck.png", "specifications": "Clamps 40V alternator load dump surges"}, {"component_id": "COMP_MPU6050", "name": "MPU-6050 +/-16g IMU (Distractor)", "category": "SPI_SENSOR", "image_url": "/assets/components/mpu6050.png", "specifications": "Saturates at 16g; cannot capture vehicular crash spikes"}, {"component_id": "COMP_MAX232", "name": "MAX232 RS-232 Transceiver (Distractor)", "category": "COMMUNICATION", "image_url": "/assets/components/max232.png", "specifications": "Single-ended bipolar serial (Incompatible with CAN)"}, {"component_id": "COMP_SD_CARD", "name": "MicroSD Card Slot (Distractor)", "category": "SPI_STORAGE", "image_url": "/assets/components/sd.png", "specifications": "Mechanical contacts dislodge during vehicular crash shock"}, {"component_id": "COMP_ESP8266_RAW", "name": "ESP8266 SoC (Distractor)", "category": "MICROCONTROLLER", "image_url": "/assets/components/esp8266.png", "specifications": "Single SPI without DMA, unable to process CAN stream"}, {"component_id": "COMP_7812_LIN", "name": "Linear 12V 7812 (Distractor)", "category": "POWER_MODULE", "image_url": "/assets/components/7812.png", "specifications": "Destroys circuit on alternator load dump"}]}'::jsonb, 'Hard', 4.0, 300, 1, 'Active', '2026-09-09 08:30:21.494024', '2026-09-09 08:30:21.494024') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (282, 26, 81, 'HARDWARE_SELECTION_PLACEMENT', 'Task 10: Smart Grid AC Mains Harmonics Analyzer & Arc-Suppressed Safety Hub', '### Problem Statement
Develop an electrical substation monitoring gateway capable of calculating true RMS voltage, active/reactive power, total harmonic distortion (THD up to the 31st harmonic), detecting ground leakage current, and executing arc-suppressed solid-state circuit breaking.

### Technical Specifications
- **Processing SoC**: Dual-core 240MHz SoC with vector acceleration for real-time FFT computations.
- **Voltage Transducer**: Precision isolated voltage potential transformer (ZMPT101B) with op-amp phase tuning.
- **Current Transducer**: Non-invasive 100A split-core current transformer (CT).
- **Analog Front-End**: 16-bit I2C Delta-Sigma ADC with low noise differential inputs.
- **Phase Synchronization**: Optical zero-crossing detection circuit (H11AA1).
- **High-Power Actuator**: Optocoupled Solid State Relay (SSR-40DA) with integrated RC snubber.
- **Auxiliary Power**: Galvanically isolated 230VAC to 5VDC medical/industrial power converter.', NULL, '{"task_id": "IOT-TASK-10", "domain": "iot-hardware-systems", "round_type": "HARDWARE_SELECTION_PLACEMENT", "motherboard_config": {"board_id": "BOARD-GRID-SUBSTATION-V1", "board_name": "Smart Grid Power Telemetry PCB", "slots": [{"slot_id": "SLOT_MCU", "label": "Dual-Core Vector MCU Socket", "supported_types": ["MICROCONTROLLER"], "pin_bus": "3.3V, GND, I2C, SPI, GPIO, INT"}, {"slot_id": "SLOT_AC_VOLTAGE", "label": "Voltage Transformer Header", "supported_types": ["VOLTAGE_AFE"], "pin_bus": "AC_L, AC_N, V_SIG (Analog 0-3.3V), GND"}, {"slot_id": "SLOT_AC_CURRENT", "label": "Current Transformer Header", "supported_types": ["CURRENT_AFE"], "pin_bus": "CT_IN+, CT_IN-, I_SIG (Analog 0-3.3V), GND"}, {"slot_id": "SLOT_I2C_ADC", "label": "16-Bit Harmonic ADC Port", "supported_types": ["ANALOG_AFE"], "pin_bus": "3.3V, GND, SCL, SDA, AIN0, AIN1"}, {"slot_id": "SLOT_ZERO_CROSS", "label": "Zero-Cross Optical Sync Port", "supported_types": ["SYNC_OPTO"], "pin_bus": "AC_L, AC_N, ZERO_PULSE (GPIO15), 3.3V"}, {"slot_id": "SLOT_SSR_TRIP", "label": "Solid State Relay Output", "supported_types": ["ACTUATOR_SSR"], "pin_bus": "TRIP_SIG (GPIO13), GND, AC_LOAD_L, AC_LOAD_N"}, {"slot_id": "SLOT_AC_POWER", "label": "Isolated 230V AC-DC Module", "supported_types": ["POWER_MODULE"], "pin_bus": "AC_IN_L, AC_IN_N, 5V_SYS, GND"}]}, "component_palette": [{"component_id": "COMP_ESP32_S3_VECTOR", "name": "ESP32-S3 Dual-Core 240MHz (Vector Instructions)", "category": "MICROCONTROLLER", "image_url": "/assets/components/esp32s3.png", "specifications": "Xtensa dual-core with SIMD vector extensions for 31-harmonic FFT"}, {"component_id": "COMP_ZMPT101B", "name": "ZMPT101B Precision Isolated Voltage Transformer", "category": "VOLTAGE_AFE", "image_url": "/assets/components/zmpt101b.png", "specifications": "230V AC galvanic voltage isolation + precision op-amp phase adjustment"}, {"component_id": "COMP_SCT013_100A", "name": "SCT-013-000 Non-Invasive 100A Current Transformer", "category": "CURRENT_AFE", "image_url": "/assets/components/sct013.png", "specifications": "0-100A AC current measurement, ferrite split core"}, {"component_id": "COMP_ADS1115_ADC", "name": "ADS1115 16-Bit I2C ADC (High Dynamic Range)", "category": "ANALOG_AFE", "image_url": "/assets/components/ads1115.png", "specifications": "16-bit low noise Delta-Sigma ADC for harmonic extraction"}, {"component_id": "COMP_H11AA1_ZC", "name": "Zero-Crossing Optical Detector (H11AA1)", "category": "SYNC_OPTO", "image_url": "/assets/components/h11aa1.png", "specifications": "Bi-directional optocoupler producing 100Hz/120Hz sync pulses"}, {"component_id": "COMP_SSR40DA", "name": "Opto-Isolated Solid State Relay (SSR-40DA)", "category": "ACTUATOR_SSR", "image_url": "/assets/components/ssr40.png", "specifications": "40A 380VAC solid-state switching with integrated RC snubber"}, {"component_id": "COMP_ISOLATED_ACDC", "name": "Isolated 230V-to-5V Industrial Power Module", "category": "POWER_MODULE", "image_url": "/assets/components/hlk.png", "specifications": "4000VAC isolation barrier, ultra-low electromagnetic ripple"}, {"component_id": "COMP_RAW_RESISTOR_DIVIDER", "name": "Direct Resistor Voltage Divider 230V (Distractor)", "category": "VOLTAGE_AFE", "image_url": "/assets/components/resistor.png", "specifications": "Zero galvanic isolation (Lethal shock hazard)"}, {"component_id": "COMP_ACS712", "name": "ACS712 Hall Effect Current Module (Distractor)", "category": "CURRENT_AFE", "image_url": "/assets/components/acs712.png", "specifications": "Invasive board layout, low dielectric voltage rating"}, {"component_id": "COMP_MECH_RELAY_RAW", "name": "Mechanical 5V Relay (Distractor)", "category": "ACTUATOR_SSR", "image_url": "/assets/components/relay.png", "specifications": "Contact arcing and welding hazard on heavy inductive AC loads"}, {"component_id": "COMP_ATMEGA328P", "name": "ATmega328P 8-Bit (Distractor)", "category": "MICROCONTROLLER", "image_url": "/assets/components/atmega.png", "specifications": "Cannot perform 31-harmonic FFT calculations in real time"}, {"component_id": "COMP_CAP_DROPPER", "name": "Capacitive Dropper Power Supply (Distractor)", "category": "POWER_MODULE", "image_url": "/assets/components/capdrop.png", "specifications": "Non-isolated AC supply (Dangerous on industrial equipment)"}]}'::jsonb, 'Hard', 4.0, 300, 1, 'Active', '2026-09-09 08:30:21.504338', '2026-09-09 08:30:21.504338') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (361, 25, 77, 'debugging', 'D12: Calculate Array Sum', 'Problem Statement:
Find the sum of all elements in an array.

Debug Hint:
The loop accesses memory outside the array. Check the total number of elements in the array declaration.', '#include <stdio.h>

int main() {
    int arr[] = {1, 2, 3, 4, 5};
    int sum = 0;

    for (int i = 0; i < 6; i++)
        sum += arr[i];

    printf("Sum = %d", sum);

    return 0;
}', '{"debug_hint": "The loop accesses memory outside the array. Check the total number of elements in the array declaration.", "problem": "Find the sum of all elements in an array."}'::jsonb, 'Easy', 10.0, 300, 1, 'Active', '2026-09-14 16:37:35.618683', '2026-09-14 16:37:35.618683') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (66, 9, 32, 'mcq', 'Q1.3: Noesys Information Security Policy & Data Protection', 'According to Information Security Policy, a candidate data file containing Personally Identifiable Information (PII) like employee SSNs and salaries must be exported for external presentation. What is the compliant procedure?', '', '[{"id": "A", "text": "Email the unencrypted file as an attachment to external personal email."}, {"id": "B", "text": "Anonymize/mask PII fields, encrypt the dataset at rest/transit, and share via authorized secure channels with access controls."}, {"id": "C", "text": "Store the unencrypted file on a public cloud drive."}, {"id": "D", "text": "Print the raw spreadsheet and leave it in the conference room."}]'::jsonb, 'Medium', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.689412', '2026-09-08 14:32:02.351346') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (68, 9, 32, 'mcq', 'Q1.3: Information Security Policy & Data Protection', 'According to Information Security Policy, a candidate data file containing Personally Identifiable Information (PII) like employee SSNs and salaries must be exported for external presentation. What is the compliant procedure?', '', '[{"id": "A", "text": "Email the unencrypted file as an attachment to external personal email."}, {"id": "B", "text": "Anonymize/mask PII fields, encrypt the dataset at rest/transit, and share via authorized secure channels with access controls."}, {"id": "C", "text": "Store the unencrypted file on a public cloud drive."}, {"id": "D", "text": "Print the raw spreadsheet and leave it in the conference room."}]'::jsonb, 'Medium', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.703316', '2026-09-08 14:32:02.351346') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (69, 9, 31, 'mcq', 'Regional Sales Growth Rate Analysis', 'Region A sales grew from $120,000 in Q1 to $156,000 in Q2. Region B sales grew from $80,000 to $108,000 in the same period. Which region achieved a higher percentage growth rate?', NULL, '[{"key": "A", "text": "Region A achieved higher growth (30% vs 35%)"}, {"key": "B", "text": "Region B achieved higher growth (35% vs 30%)"}, {"key": "C", "text": "Both regions achieved equal growth (30%)"}, {"key": "D", "text": "Region A achieved higher growth (36% vs 28%)"}]'::jsonb, 'Medium', 2.0, 180, 1, 'Active', '2026-08-20 13:59:34.709848', '2026-09-08 14:32:02.351346') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (71, 9, 42, 'mcq', 'Product Margin & Revenue Weighted Average', 'Product X yields $50,000 revenue at a 40% gross margin. Product Y yields $150,000 revenue at a 20% gross margin. What is the overall revenue-weighted gross margin percentage of the portfolio?', NULL, '[{"key": "A", "text": "30.0%"}, {"key": "B", "text": "25.0%"}, {"key": "C", "text": "27.5%"}, {"key": "D", "text": "22.5%"}]'::jsonb, 'Hard', 2.0, 240, 1, 'Active', '2026-08-20 13:59:34.725614', '2026-09-08 14:32:02.351346') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (81, 11, 36, 'mcq', 'Q3.2: VBA Macro Loop Debugging', 'The following VBA macro highlights rows where Column C (Sales) is less than 1,000, but it fails at runtime with Error 1004 because `LastRow` is not properly initialized:

```vb
Sub HighlightLowSales()
    Dim i As Long
    For i = 2 To LastRow
        If Cells(i, 3).Value < 1000 Then
            Cells(i, 3).Interior.Color = RGB(255, 0, 0)
        End If
    Next i
End Sub
```

Which statement correctly initializes `LastRow` to find the last populated row in Column C before entering the loop?', NULL, '[{"key": "A", "text": "Dim LastRow As Long: LastRow = Cells(Rows.Count, 3).End(xlUp).Row"}, {"key": "B", "text": "Dim LastRow As Integer: LastRow = Cells(3, Columns.Count).End(xlToLeft).Column"}, {"key": "C", "text": "LastRow = ActiveSheet.UsedRange.Rows.Select"}, {"key": "D", "text": "Dim LastRow: LastRow = Count(Range(\"C:C\"))"}]'::jsonb, 'Medium', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.849414', '2026-09-08 14:58:17.260028') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (84, 11, 47, 'debugging', 'Python Data Aggregation Bug Fixing', 'The following code contains a bug in calculating average order value per customer from a list of tuples `(customer, amount)`. Identify and fix the zero division bug when a customer has no orders.', 'def calc_average(orders):
    totals = {}
    counts = {}
    for cust, amt in orders:
        totals[cust] = totals.get(cust, 0) + amt
        counts[cust] = counts.get(cust, 0) + 1
    
    averages = {}
    for cust in totals:
        # FIX BUG HERE
        averages[cust] = totals[cust] / counts[cust] if counts.get(cust, 0) > 0 else 0.0
    return averages
', '[{"key": "A", "text": "averages[cust] = totals[cust] / counts[cust] if counts.get(cust, 0) > 0 else 0.0"}, {"key": "B", "text": "averages[cust] = totals[cust] / (counts[cust] + 1)"}, {"key": "C", "text": "averages[cust] = totals[cust] * 0"}, {"key": "D", "text": "del totals[cust]"}]'::jsonb, 'Easy', 10.0, 240, 1, 'Active', '2026-08-20 13:59:34.878189', '2026-08-20 13:59:34.878189') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (273, 26, 80, 'HARDWARE_SELECTION_PLACEMENT', 'Task 01: Smart Indoor Thermostat & Ambient Display Node', '### Problem Statement
Design a compact residential indoor air monitoring node. The device must measure ambient room temperature and relative humidity, display real-time sensor metrics on a local low-power display screen, and transmit telemetry over Wi-Fi to a cloud MQTT dashboard.

### Technical Specifications
- **Processing Core**: Wi-Fi enabled microcontroller with 3.3V GPIO.
- **Sensor Interface**: Single-bus digital humidity/temperature sensor.
- **Display Interface**: 0.96-inch monochrome display communicating over standard 2-wire I2C bus.
- **Power**: Standard 5V USB regulated supply.

### Instructions
Select the 3 required hardware components from your inventory and place them into their corresponding motherboard sockets.', NULL, '{"task_id": "IOT-TASK-01", "domain": "iot-hardware-systems", "round_type": "HARDWARE_SELECTION_PLACEMENT", "motherboard_config": {"board_id": "BOARD-INDOOR-V1", "board_name": "Smart Thermostat Dev PCB", "slots": [{"slot_id": "SLOT_MCU", "label": "MCU Socket (3.3V)", "supported_types": ["MICROCONTROLLER"], "pin_bus": "3.3V, GND, GPIO, I2C, SPI"}, {"slot_id": "SLOT_DIGITAL_GPIO", "label": "Digital Sensor Port", "supported_types": ["DIGITAL_SENSOR"], "pin_bus": "3.3V, GND, GPIO4 (Single-Wire)"}, {"slot_id": "SLOT_I2C_DISPLAY", "label": "I2C Display Port", "supported_types": ["DISPLAY"], "pin_bus": "3.3V, GND, SCL (GPIO22), SDA (GPIO21)"}]}, "component_palette": [{"component_id": "COMP_ESP32_WROOM", "name": "ESP32-WROOM-32 Module", "category": "MICROCONTROLLER", "image_url": "/assets/components/esp32.png", "specifications": "Dual Core 240MHz, 2.4GHz Wi-Fi + BLE, 3.3V logic"}, {"component_id": "COMP_DHT22", "name": "DHT22 Digital Temperature & Humidity Sensor", "category": "DIGITAL_SENSOR", "image_url": "/assets/components/dht22.png", "specifications": "Single-bus digital protocol, -40 to 80\u00b0C, 0-100% RH"}, {"component_id": "COMP_OLED_096_I2C", "name": "0.96\" I2C OLED Display (SSD1306)", "category": "DISPLAY", "image_url": "/assets/components/oled.png", "specifications": "128x64 pixels, 4-Pin I2C interface (Addr: 0x3C)"}, {"component_id": "COMP_HCSR04", "name": "HC-SR04 Ultrasonic Distance Sensor", "category": "DIGITAL_SENSOR", "image_url": "/assets/components/sonar.png", "specifications": "Sonar distance measurement, 5V TTL (Distractor)"}, {"component_id": "COMP_MAX485", "name": "MAX485 Industrial Transceiver", "category": "COMMUNICATION", "image_url": "/assets/components/rs485.png", "specifications": "RS-485 differential bus transceiver (Distractor)"}]}'::jsonb, 'Easy', 1.0, 90, 1, 'Active', '2026-09-09 08:30:21.441675', '2026-09-09 14:46:43.502290') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (362, 25, 77, 'debugging', 'D13: Print Array in Reverse', 'Problem Statement:
Print the elements of an array in reverse order.

Debug Hint:
Find the invalid array index. A 5-element array does not have an element at index 5.', '#include <stdio.h>

int main() {
    int arr[] = {10, 20, 30, 40, 50};

    for (int i = 5; i >= 0; i--)
        printf("%d ", arr[i]);

    return 0;
}', '{"debug_hint": "Find the invalid array index. A 5-element array does not have an element at index 5.", "problem": "Print the elements of an array in reverse order."}'::jsonb, 'Easy', 10.0, 300, 1, 'Active', '2026-09-14 16:37:35.618683', '2026-09-14 16:37:35.618683') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (80, 11, 35, 'mcq', 'Q3.1: Modern Lookup Formulas (XLOOKUP vs VLOOKUP)', 'Which statement correctly describes why XLOOKUP is preferred over VLOOKUP in financial modeling?', '', '[{"id": "A", "text": "XLOOKUP defaults to exact match, allows leftward lookups without column index numbers, and handles array outputs natively."}, {"id": "B", "text": "VLOOKUP can look left whereas XLOOKUP cannot."}, {"id": "C", "text": "XLOOKUP requires sorted data whereas VLOOKUP does not."}, {"id": "D", "text": "There is no difference in functionality."}]'::jsonb, 'Medium', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.843007', '2026-09-08 14:32:02.361920') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (82, 11, 37, 'mcq', 'Q3.3: Tableau Chart Selection for KPI Dashboards', 'You need to visualize monthly sales performance against quarterly targets across 5 product categories. Which chart layout is most effective for executive decision-making?', '', '[{"id": "A", "text": "A 3D Pie Chart with 15 colored slices."}, {"id": "B", "text": "Bullet Graphs or Combo Bar Charts with Target Reference Lines for each category."}, {"id": "C", "text": "A raw unformatted cross-tab table with 500 rows."}, {"id": "D", "text": "A scatter plot of customer age vs zip code."}]'::jsonb, 'Medium', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.860615', '2026-09-08 14:32:02.361920') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (85, 11, 48, 'mcq', 'Q3.1: Pandas DataFrame Groupby & Aggregation Concepts', 'Given a Pandas DataFrame `df` containing `[''Region'', ''Revenue'']`, what is the returned data structure when executing `df.groupby(''Region'')[''Revenue''].agg([''mean'', ''sum''])`?', NULL, '[{"key": "A", "text": "A Series containing only the sum of revenue."}, {"key": "B", "text": "A DataFrame indexed by Region with columns ''mean'' and ''sum'' representing revenue metrics."}, {"key": "C", "text": "A Python list of tuples."}, {"key": "D", "text": "An error because agg() requires a custom lambda function."}]'::jsonb, 'Easy', 2.0, 180, 1, 'Active', '2026-08-20 13:59:34.884104', '2026-09-08 14:32:02.361920') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (88, 11, 48, 'mcq', 'Q3.4: Pandas Missing Data Imputation Strategies', 'A DataFrame `df` has missing numeric values in column `''score''`. Which Pandas code fills missing values with the column mean inplace?', NULL, '[{"key": "A", "text": "df[''score''].fillna(df[''score''].mean(), inplace=True)"}, {"key": "B", "text": "df[''score''].dropna(mean=True)"}, {"key": "C", "text": "df.replace(''score'', df[''score''].mean())"}, {"key": "D", "text": "df[''score''].apply(lambda x: x == None)"}]'::jsonb, 'Medium', 2.0, 180, 1, 'Active', '2026-08-20 13:59:34.909535', '2026-09-08 14:32:02.361920') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (89, 11, 47, 'mcq', 'Q3.5: Python List Comprehensions for Data Filtering', 'Which list comprehension correctly filters a list of sales figures `sales = [120, 450, 80, 600, 310]` to keep values greater than or equal to 300?', NULL, '[{"key": "A", "text": "[s for s in sales if s >= 300]"}, {"key": "B", "text": "[for s in sales if s >= 300 select s]"}, {"key": "C", "text": "sales.filter(s => s >= 300)"}, {"key": "D", "text": "[s if s >= 300 for s in sales]"}]'::jsonb, 'Easy', 2.0, 180, 1, 'Active', '2026-08-20 13:59:34.919543', '2026-09-08 14:32:02.361920') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (92, 11, 47, 'debugging', 'Q3.8: Python Data Aggregation Zero-Division Bug Fixing', 'The following code contains a bug in calculating average order value per customer from a list of tuples `(customer, amount)`. Identify and fix the zero division bug when a customer has no orders.', 'def calc_average(orders):
    totals = {}
    counts = {}
    for cust, amt in orders:
        totals[cust] = totals.get(cust, 0) + amt
        counts[cust] = counts.get(cust, 0) + 1
    
    averages = {}
    for cust in totals:
        # FIX BUG HERE
        averages[cust] = totals[cust] / counts[cust] if counts.get(cust, 0) > 0 else 0.0
    return averages
', '[{"key": "A", "text": "averages[cust] = totals[cust] / counts[cust] if counts.get(cust, 0) > 0 else 0.0"}, {"key": "B", "text": "averages[cust] = totals[cust] / (counts[cust] + 1)"}, {"key": "C", "text": "averages[cust] = totals[cust] * 0"}, {"key": "D", "text": "del totals[cust]"}]'::jsonb, 'Easy', 10.0, 240, 1, 'Active', '2026-08-20 13:59:34.942905', '2026-08-20 13:59:34.942905') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (237, 3, 9, 'mcq', 'Compare-And-Swap (CAS) & Lock-Free Atomic Primitives', 'How do lock-free data structures (such as `AtomicInteger` in Java or `std::atomic` in C++) achieve thread-safe updates without using OS mutex locks?', NULL, '[{"id": 1, "text": "Using hardware-supported atomic Compare-And-Swap (CAS) CPU instructions in an optimistic retry loop"}, {"id": 2, "text": "By pausing the OS thread scheduler during the update"}, {"id": 3, "text": "By duplicating memory addresses per CPU core"}, {"id": 4, "text": "By converting concurrent reads into serial disk writes"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (238, 3, 9, 'mcq', 'Thread Context Switching Overhead Components', 'When an OS pre-empts Thread A and switches execution to Thread B, which of the following is a direct source of performance overhead?', NULL, '[{"id": 1, "text": "Saving/restoring CPU registers, program counter, and CPU cache/TLB invalidation"}, {"id": 2, "text": "Recompiling the thread binary code into bytecode"}, {"id": 3, "text": "Re-allocating the thread heap memory space"}, {"id": 4, "text": "Zeroing out physical RAM blocks"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (274, 26, 82, 'HARDWARE_SELECTION_PLACEMENT', 'Task 02: Automated Water Tank Level & Pump Trigger', '### Problem Statement
Build an automated liquid management system for an industrial overhead water reservoir. The unit must non-intrusively measure water surface level via acoustic time-of-flight pulses and switch on an AC submersible pump when liquid level drops below threshold.

### Technical Specifications
- **Controller**: 8-bit ATmega embedded processing unit.
- **Level Sensor**: Non-contact ultrasonic transceiver operating with standard Trigger/Echo timing pulses.
- **Actuator**: Optocoupler-isolated 5V single-channel relay rated for 250VAC motor control.', NULL, '{"task_id": "IOT-TASK-02", "domain": "iot-hardware-systems", "round_type": "HARDWARE_SELECTION_PLACEMENT", "motherboard_config": {"board_id": "BOARD-TANK-V1", "board_name": "Liquid Management Carrier Board", "slots": [{"slot_id": "SLOT_MCU", "label": "MCU Socket (5V)", "supported_types": ["MICROCONTROLLER"], "pin_bus": "5V, GND, Digital I/O, Analog In"}, {"slot_id": "SLOT_SONAR_PORT", "label": "Sonar Transceiver Port", "supported_types": ["DIGITAL_SENSOR"], "pin_bus": "5V, GND, TRIG (D9), ECHO (D10)"}, {"slot_id": "SLOT_RELAY_OUTPUT", "label": "Pump Relay Header", "supported_types": ["ACTUATOR"], "pin_bus": "5V, GND, IN (D4)"}]}, "component_palette": [{"component_id": "COMP_ARDUINO_NANO", "name": "Arduino Nano (ATmega328P)", "category": "MICROCONTROLLER", "image_url": "/assets/components/nano.png", "specifications": "16MHz AVR 8-bit MCU, 5V logic"}, {"component_id": "COMP_HCSR04", "name": "HC-SR04 Ultrasonic Sensor", "category": "DIGITAL_SENSOR", "image_url": "/assets/components/sonar.png", "specifications": "2cm to 400cm range, 5V sonar pulses"}, {"component_id": "COMP_5V_RELAY", "name": "5V 1-Channel Optoisolated Relay Module", "category": "ACTUATOR", "image_url": "/assets/components/relay.png", "specifications": "10A 250VAC switching capacity"}, {"component_id": "COMP_PIR_MOTION", "name": "HC-SR501 PIR Motion Sensor", "category": "DIGITAL_SENSOR", "image_url": "/assets/components/pir.png", "specifications": "Passive IR body heat detector (Distractor)"}, {"component_id": "COMP_SPI_DISPLAY", "name": "1.8\" TFT SPI Display (ST7735)", "category": "DISPLAY", "image_url": "/assets/components/tft.png", "specifications": "Color SPI screen (Distractor)"}]}'::jsonb, 'Easy', 1.0, 90, 1, 'Active', '2026-09-09 08:30:21.456777', '2026-09-09 14:46:43.549608') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (275, 26, 78, 'HARDWARE_SELECTION_PLACEMENT', 'Task 03: Basic Greenhouse Drip Irrigation Unit', '### Problem Statement
Assemble a micro-irrigation controller for a smart greenhouse. The system samples soil volumetric moisture via an analog probe and controls a 12V DC solenoid irrigation valve through an optoisolated driver.

### Technical Specifications
- **Compute**: Wi-Fi SoC with onboard 10-bit ADC channel.
- **Moisture Sensor**: Corrosion-resistant capacitive soil sensor with analog output.
- **Solenoid Actuation**: 5V relay module with optocoupler isolation.', NULL, '{"task_id": "IOT-TASK-03", "domain": "iot-hardware-systems", "round_type": "HARDWARE_SELECTION_PLACEMENT", "motherboard_config": {"board_id": "BOARD-AGRI-BASIC-V1", "board_name": "Greenhouse Drip Carrier PCB", "slots": [{"slot_id": "SLOT_MCU", "label": "MCU Socket", "supported_types": ["MICROCONTROLLER"], "pin_bus": "3.3V/5V, GND, ADC0, GPIO"}, {"slot_id": "SLOT_ANALOG_A0", "label": "Analog Moisture Port (ADC0)", "supported_types": ["ANALOG_SENSOR"], "pin_bus": "3.3V, GND, ADC0 (0-3.3V)"}, {"slot_id": "SLOT_VALVE_RELAY", "label": "Valve Relay Output", "supported_types": ["ACTUATOR"], "pin_bus": "5V, GND, GPIO14"}]}, "component_palette": [{"component_id": "COMP_ESP8266_NODEMCU", "name": "NodeMCU ESP8266 Module", "category": "MICROCONTROLLER", "image_url": "/assets/components/esp8266.png", "specifications": "80MHz Wi-Fi SoC with single ADC0 pin"}, {"component_id": "COMP_CAP_SOIL_V12", "name": "Capacitive Soil Moisture Sensor v1.2", "category": "ANALOG_SENSOR", "image_url": "/assets/components/soil_sensor.png", "specifications": "1.2V-3.0V analog output, corrosion proof"}, {"component_id": "COMP_OPTO_RELAY", "name": "Optocoupled 5V Relay Module", "category": "ACTUATOR", "image_url": "/assets/components/relay.png", "specifications": "Optically isolated 10A trigger"}, {"component_id": "COMP_MQ2_GAS", "name": "MQ-2 Flammable Gas Sensor", "category": "ANALOG_SENSOR", "image_url": "/assets/components/mq2.png", "specifications": "LPG/Smoke sensor with heater (Distractor)"}, {"component_id": "COMP_RC522_RFID", "name": "RC522 13.56MHz RFID Reader", "category": "COMMUNICATION", "image_url": "/assets/components/rfid.png", "specifications": "SPI NFC badge reader (Distractor)"}]}'::jsonb, 'Easy', 1.0, 90, 1, 'Active', '2026-09-09 08:30:21.462511', '2026-09-09 14:46:43.561461') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (283, 26, 79, 'HARDWARE_SELECTION_PLACEMENT', 'Task 04: Solar-Powered LoRaWAN Air Quality Node', '### Problem Statement
Engineer an autonomous municipal air quality telemetry station for smart light poles. The station must monitor fine environmental conditions (temperature, humidity, pressure, gas resistance) over I2C, transmit over long-range sub-GHz LoRaWAN (868MHz), and harvest power through an MPPT solar charger.

### Technical Specifications
- **Master Controller**: High-performance dual-core 3.3V SoC with hardware I2C and SPI peripherals.
- **Gas & Environmental**: 4-in-1 MOX gas, barometric pressure, humidity, and temperature sensor on I2C bus.
- **RF Modem**: Semtech SX1276/SX1262 LoRa transceiver communicating over high-speed SPI bus.
- **Power Management**: Maximum Power Point Tracking (MPPT) lithium solar shield.', NULL, '{"task_id": "IOT-TASK-04", "domain": "iot-hardware-systems", "round_type": "HARDWARE_SELECTION_PLACEMENT", "motherboard_config": {"board_id": "BOARD-SOLAR-LORA-V2", "board_name": "Off-Grid Environmental Telemetry PCB", "slots": [{"slot_id": "SLOT_MCU", "label": "MCU Socket (3.3V)", "supported_types": ["MICROCONTROLLER"], "pin_bus": "3.3V, GND, I2C, SPI"}, {"slot_id": "SLOT_I2C_SENSOR", "label": "I2C Environmental Bus", "supported_types": ["I2C_SENSOR"], "pin_bus": "3.3V, GND, SCL (GPIO22), SDA (GPIO21)"}, {"slot_id": "SLOT_SPI_RF", "label": "SPI Sub-GHz RF Header", "supported_types": ["COMMUNICATION"], "pin_bus": "3.3V, GND, MOSI, MISO, SCK, CS (GPIO5)"}, {"slot_id": "SLOT_MPPT_PWR", "label": "Solar Energy Port", "supported_types": ["POWER"], "pin_bus": "SOLAR_IN, BAT_IN, 3V3_REG, GND"}]}, "component_palette": [{"component_id": "COMP_ESP32_S3", "name": "ESP32-S3 Dual-Core SoC", "category": "MICROCONTROLLER", "image_url": "/assets/components/esp32s3.png", "specifications": "Xtensa LX7 240MHz, 3.3V logic, dual-core"}, {"component_id": "COMP_BME680", "name": "Bosch BME680 Environmental VOC Sensor", "category": "I2C_SENSOR", "image_url": "/assets/components/bme680.png", "specifications": "Gas, Temp, Humidity, Pressure on I2C (0x77)"}, {"component_id": "COMP_SX1262_LORA", "name": "Semtech SX1262 LoRaWAN SPI Module (868MHz)", "category": "COMMUNICATION", "image_url": "/assets/components/lora.png", "specifications": "+22dBm output, sub-GHz LoRaWAN protocol"}, {"component_id": "COMP_CN3791_MPPT", "name": "CN3791 MPPT Solar Lithium Charger Shield", "category": "POWER", "image_url": "/assets/components/mppt.png", "specifications": "Solar panel MPPT tracking, lithium battery charging"}, {"component_id": "COMP_HC05_BT", "name": "HC-05 Bluetooth Module", "category": "COMMUNICATION", "image_url": "/assets/components/hc05.png", "specifications": "Short-range 2.4GHz Bluetooth (Distractor)"}, {"component_id": "COMP_USB_WALL", "name": "5V 2A Linear Wall Adapter", "category": "POWER", "image_url": "/assets/components/adapter.png", "specifications": "Mains supply brick (Distractor - off-grid invalid)"}]}'::jsonb, 'Medium', 2.0, 180, 1, 'Active', '2026-09-09 14:46:43.572915', '2026-09-09 14:46:43.572915') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (99, 13, 53, 'project_discussion', 'Project-Derived Data Cleaning & Transformation Validation', 'In the context of your declared project, explain how you handled missing values, duplicate records, or data type inconsistencies. Why did you select those specific cleaning techniques for your dataset?', NULL, '[]'::jsonb, 'Medium', 15.0, 360, 1, 'Active', '2026-08-20 13:59:35.009819', '2026-08-20 13:59:35.009819') ON CONFLICT DO NOTHING;
