INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (91, 11, 48, 'coding', 'Q3.7: Calculate Monthly Sales Growth Rate in Pandas', 'Write a Python Pandas function `calculate_growth_rate(sales_series)` that accepts a Pandas Series of monthly sales values and returns a Series representing percentage change between consecutive months rounded to 2 decimal places.', 'import pandas as pd

def calculate_growth_rate(sales_series: pd.Series):
    # Return percentage change rounded to 2 decimal places
    return sales_series.pct_change().round(2)
', '[{"key": "A", "text": "return sales_series.pct_change().round(2)"}, {"key": "B", "text": "return sales_series.diff() / 100"}, {"key": "C", "text": "return sales_series.cumsum()"}, {"key": "D", "text": "return sales_series.shift(1)"}]'::jsonb, 'Hard', 10.0, 360, 1, 'Active', '2026-08-20 13:59:34.935880', '2026-09-08 14:32:02.361920') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (94, 12, 38, 'mcq', 'Q4.1: Pandas DataFrame Groupby & Aggregation Concepts', 'In Pandas, what does `df.groupby(''Region'')[''Revenue''].agg([''mean'', ''sum''])` return?', '', '[{"id": "A", "text": "A Series containing only the sum of revenue."}, {"id": "B", "text": "A DataFrame indexed by Region with columns ''mean'' and ''sum'' representing revenue metrics."}, {"id": "C", "text": "A Python list of tuples."}, {"id": "D", "text": "An error because agg() requires a custom lambda."}]'::jsonb, 'Medium', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.971736', '2026-09-08 14:32:02.361920') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (174, 22, 71, 'mcq', 'Arithmetic Progression Series', 'Identify the next number in the sequence: 3, 6, 12, 24, 48, ___', NULL, '["64", "72", "96", "84"]'::jsonb, 'Easy', 1.0, 45, 1, 'Active', '2026-08-23 03:40:44.062865', '2026-09-08 14:32:02.386295') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (239, 3, 9, 'mcq', 'Translation Lookaside Buffer (TLB) Miss Resolution', 'In a modern CPU with Virtual Memory, what happens immediately when a Translation Lookaside Buffer (TLB) miss occurs during a memory read?', NULL, '[{"id": 1, "text": "The hardware Page Table Walker traverses multi-level page tables in RAM to resolve the virtual-to-physical address mapping"}, {"id": 2, "text": "The OS generates a Fatal Page Fault and terminates the process"}, {"id": 3, "text": "The CPU swaps the active process to secondary storage swap space"}, {"id": 4, "text": "The memory controller restarts the CPU core"}]'::jsonb, 'Hard', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (240, 3, 9, 'mcq', 'Thread Starvation vs Deadlock Distinction', 'What is the key technical difference between Thread Starvation and Deadlock in concurrent systems?', NULL, '[{"id": 1, "text": "In starvation, some threads continue making progress while others wait indefinitely; in deadlock, no involved thread can make progress"}, {"id": 2, "text": "Starvation only occurs on single-core CPUs; deadlock only occurs on multi-core CPUs"}, {"id": 3, "text": "Deadlock can be resolved by increasing thread priority; starvation cannot"}, {"id": 4, "text": "Starvation is an OS hardware fault; deadlock is a network protocol error"}]'::jsonb, 'Easy', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (284, 26, 82, 'HARDWARE_SELECTION_PLACEMENT', 'Task 05: Smart Building Motion-Triggered Fan & Light Controller', '### Problem Statement
Build a smart room energy-saving controller. The system senses human occupancy via a passive infrared (PIR) sensor, measures room temperature with a digital sensor, and activates room lighting and an AC ventilation fan via optoisolated relays.

### Technical Specifications
- **Controller**: Wi-Fi enabled 32-bit microcontroller.
- **Occupancy Sensor**: Digital PIR motion detector with digital high/low output.
- **Temperature Sensor**: Digital single-bus temperature/humidity probe.
- **Output Stage**: Optocoupler-isolated 2-channel AC relay module for lighting and fan loads.', NULL, '{"task_id": "IOT-TASK-05", "domain": "iot-hardware-systems", "round_type": "HARDWARE_SELECTION_PLACEMENT", "motherboard_config": {"board_id": "BOARD-ROOM-CTRL-V1", "board_name": "Smart Room Automation PCB", "slots": [{"slot_id": "SLOT_MCU", "label": "MCU Socket", "supported_types": ["MICROCONTROLLER"], "pin_bus": "3.3V, GND, GPIO, I2C"}, {"slot_id": "SLOT_PIR_PORT", "label": "PIR Motion Sensor Port", "supported_types": ["DIGITAL_SENSOR"], "pin_bus": "5V, GND, OUT (GPIO13)"}, {"slot_id": "SLOT_TEMP_PORT", "label": "Temperature Sensor Port", "supported_types": ["DIGITAL_SENSOR"], "pin_bus": "3.3V, GND, DATA (GPIO14)"}, {"slot_id": "SLOT_RELAY_2CH", "label": "Dual Relay Output Header", "supported_types": ["ACTUATOR"], "pin_bus": "5V, GND, IN1 (GPIO18), IN2 (GPIO19)"}]}, "component_palette": [{"component_id": "COMP_ESP32_WROOM", "name": "ESP32-WROOM-32 Module", "category": "MICROCONTROLLER", "image_url": "/assets/components/esp32.png", "specifications": "Dual-Core 240MHz Wi-Fi/BLE MCU"}, {"component_id": "COMP_HCSR501_PIR", "name": "HC-SR501 PIR Motion Detector", "category": "DIGITAL_SENSOR", "image_url": "/assets/components/pir.png", "specifications": "Passive infrared body heat detector, 7m range"}, {"component_id": "COMP_DHT22_TEMP", "name": "DHT22 Digital Temperature Sensor", "category": "DIGITAL_SENSOR", "image_url": "/assets/components/dht22.png", "specifications": "Calibrated digital temp & humidity probe"}, {"component_id": "COMP_2CH_RELAY", "name": "2-Channel Optoisolated Relay Module", "category": "ACTUATOR", "image_url": "/assets/components/relay.png", "specifications": "2x 10A 250VAC independently switched relays"}, {"component_id": "COMP_MAX485", "name": "MAX485 Transceiver (Distractor)", "category": "COMMUNICATION", "image_url": "/assets/components/rs485.png", "specifications": "Industrial RS-485 bus (Distractor)"}, {"component_id": "COMP_SOIL_PROBE", "name": "Soil Moisture Probe (Distractor)", "category": "ANALOG_SENSOR", "image_url": "/assets/components/soil.png", "specifications": "Agricultural probe (Distractor)"}]}'::jsonb, 'Medium', 2.0, 180, 1, 'Active', '2026-09-09 14:46:43.591688', '2026-09-09 14:46:43.591688') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (285, 26, 80, 'HARDWARE_SELECTION_PLACEMENT', 'Task 06: Wearable Health Pulse & Activity Tracker', '### Problem Statement
Build a wearable health telematics wristband for patient vital monitoring. The device continuously reads blood oxygen saturation (SpO2) and pulse rate via an optical PPG sensor, detects motion/steps via a 3-axis accelerometer, and runs off a rechargeable LiPo battery.

### Technical Specifications
- **Core**: Ultra-low power Bluetooth 5.2 ARM Cortex-M4F SoC.
- **Biometric Sensor**: Multi-LED optical pulse oximeter on I2C bus.
- **Motion Sensor**: 3-axis digital accelerometer on I2C bus.
- **Battery Management**: Miniature 3.7V single-cell LiPo charge controller.', NULL, '{"task_id": "IOT-TASK-06", "domain": "iot-hardware-systems", "round_type": "HARDWARE_SELECTION_PLACEMENT", "motherboard_config": {"board_id": "BOARD-IOMT-WEAR-V1", "board_name": "Clinical Wearable Carrier PCB", "slots": [{"slot_id": "SLOT_MCU", "label": "MCU Socket (BLE)", "supported_types": ["MICROCONTROLLER"], "pin_bus": "3.3V, GND, I2C, GPIO"}, {"slot_id": "SLOT_I2C_PPG", "label": "PPG Sensor Port", "supported_types": ["I2C_SENSOR"], "pin_bus": "3.3V, GND, SCL, SDA, INT"}, {"slot_id": "SLOT_I2C_IMU", "label": "Motion IMU Port", "supported_types": ["I2C_SENSOR"], "pin_bus": "3.3V, GND, SCL, SDA, INT"}, {"slot_id": "SLOT_LIPO_BMS", "label": "LiPo BMS Charger Port", "supported_types": ["POWER"], "pin_bus": "USB_5V, BAT_IN, VDD_SYS, GND"}]}, "component_palette": [{"component_id": "COMP_NRF52840", "name": "Nordic nRF52840 BLE 5.2 SoC", "category": "MICROCONTROLLER", "image_url": "/assets/components/nrf52.png", "specifications": "64MHz Cortex-M4F, Bluetooth 5.2, ultra-low power"}, {"component_id": "COMP_MAX30102", "name": "MAX30102 Optical SpO2 & Heart Rate", "category": "I2C_SENSOR", "image_url": "/assets/components/max30102.png", "specifications": "Red & IR LEDs, photodetector, 18-bit ADC, I2C"}, {"component_id": "COMP_ADXL345", "name": "ADXL345 3-Axis Digital Accelerometer", "category": "I2C_SENSOR", "image_url": "/assets/components/adxl345.png", "specifications": "+/-16g 13-bit digital accelerometer, I2C/SPI"}, {"component_id": "COMP_MCP73831", "name": "MCP73831 Miniature LiPo Charge Controller", "category": "POWER", "image_url": "/assets/components/mcp73831.png", "specifications": "500mA CC/CV single-cell lithium battery charger"}, {"component_id": "COMP_PIEZO_BUZZER", "name": "12V Piezo Siren (Distractor)", "category": "ACTUATOR", "image_url": "/assets/components/buzzer.png", "specifications": "Bulky high-voltage acoustic siren (Distractor)"}, {"component_id": "COMP_MAX485", "name": "MAX485 Module (Distractor)", "category": "COMMUNICATION", "image_url": "/assets/components/max485.png", "specifications": "Wired industrial transceiver (Distractor)"}]}'::jsonb, 'Medium', 2.0, 180, 1, 'Active', '2026-09-09 14:46:43.602762', '2026-09-09 14:46:43.602762') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (383, 25, 77, 'debugging', 'D34: Delete First Node', 'Problem Statement:
Delete the first node from a linked list.

Debug Hint:
A freed pointer is being accessed. Store head->next in a temporary pointer before calling free(head).', '#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node *next;
};

struct Node* deleteFirst(struct Node *head) {
    if (head == NULL)
        return NULL;

    free(head);

    head = head->next;

    return head;
}', '{"debug_hint": "A freed pointer is being accessed. Store head->next in a temporary pointer before calling free(head).", "problem": "Delete the first node from a linked list."}'::jsonb, 'Medium', 10.0, 300, 1, 'Active', '2026-09-14 16:37:35.690739', '2026-09-14 16:37:35.690739') ON CONFLICT DO NOTHING;
