INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (188, 23, 74, 'mcq', 'Pointer Arithmetic Stride', 'On a standard 64-bit architecture where sizeof(int) == 4 bytes, if ptr points to memory address 0x1000, what address will (ptr + 2) evaluate to?', NULL, '["0x1002", "0x1004", "0x1008", "0x1010"]'::jsonb, 'Medium', 2.0, 60, 1, 'Active', '2026-08-23 03:40:44.118953', '2026-09-08 14:32:02.386295') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (189, 23, 74, 'mcq', 'Array Identifier Decay', 'Given ''int arr[5] = {1, 2, 3, 4, 5};'', which of the following expressions is equivalent to ''*(arr + 3)''?', NULL, '["arr[3]", "&arr[3]", "arr + 3", "*arr + 3"]'::jsonb, 'Medium', 2.0, 60, 1, 'Active', '2026-08-23 03:40:44.118953', '2026-09-08 14:32:02.386295') ON CONFLICT DO NOTHING;
