INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (194, 23, 73, 'mcq', 'Static Variable Lifetime', 'What is printed when ''counter()'' is called twice in main?

