INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (195, 23, 73, 'mcq', 'String Literal Memory Size', 'What is the value returned by ''sizeof("HELLO")'' in C?', NULL, '["5", "6", "4", "8"]'::jsonb, 'Easy', 1.0, 45, 1, 'Active', '2026-08-23 03:40:44.145753', '2026-09-08 14:32:02.386295') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (196, 23, 75, 'mcq', 'Structure vs Union Memory Layout', 'What is the primary difference in memory allocation between a ''struct'' and a ''union'' in C?', NULL, '["A union allocates memory only for its largest member, sharing space among all members", "A struct can only contain primitive data types whereas a union can contain pointers", "A union allocates the sum of all members plus padding", "There is no difference in memory allocation"]'::jsonb, 'Hard', 3.0, 90, 1, 'Active', '2026-08-23 03:40:44.153005', '2026-09-08 14:32:02.386295') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (197, 23, 76, 'mcq', 'malloc Return Value & Type', 'What generic pointer type is returned by the standard library function ''malloc(size_t size)'' in C?', NULL, '["char*", "void*", "int*", "NULL*"]'::jsonb, 'Easy', 1.0, 45, 1, 'Active', '2026-08-23 03:40:44.156061', '2026-09-08 14:32:02.386295') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (286, 26, 79, 'HARDWARE_SELECTION_PLACEMENT', 'Task 07: Cold Chain Asset GPS & Temperature Tracker', '### Problem Statement
Assemble a cold-chain logistics telemetry unit for refrigerated vaccine transport. The device tracks geographical GPS coordinates, logs continuous temperature readings with a waterproof probe, and records offline audit data to a local SPI MicroSD card.

### Technical Specifications
- **Controller**: 32-bit Wi-Fi/BLE microcontroller with hardware UART and SPI.
- **Location Modem**: GNSS/GPS positioning receiver streaming NMEA sentences over UART.
- **Temperature Probe**: Waterproof 1-wire digital temperature probe.
- **Offline Storage**: MicroSD card breakout adapter on high-speed SPI bus.', NULL, '{"task_id": "IOT-TASK-07", "domain": "iot-hardware-systems", "round_type": "HARDWARE_SELECTION_PLACEMENT", "motherboard_config": {"board_id": "BOARD-COLDCHAIN-V1", "board_name": "Cold Chain Telematics PCB", "slots": [{"slot_id": "SLOT_MCU", "label": "MCU Socket", "supported_types": ["MICROCONTROLLER"], "pin_bus": "3.3V, GND, UART, SPI, GPIO"}, {"slot_id": "SLOT_UART_GPS", "label": "UART GPS Header", "supported_types": ["COMMUNICATION"], "pin_bus": "3.3V, GND, RX (GPIO16), TX (GPIO17)"}, {"slot_id": "SLOT_TEMP_1WIRE", "label": "1-Wire Temperature Header", "supported_types": ["DIGITAL_SENSOR"], "pin_bus": "3.3V, GND, 1WIRE_DQ (GPIO4)"}, {"slot_id": "SLOT_SPI_SD", "label": "MicroSD SPI Datalogger Slot", "supported_types": ["SPI_STORAGE"], "pin_bus": "3.3V, GND, MOSI, MISO, SCK, CS (GPIO5)"}]}, "component_palette": [{"component_id": "COMP_ESP32_WROOM", "name": "ESP32-WROOM-32D Module", "category": "MICROCONTROLLER", "image_url": "/assets/components/esp32.png", "specifications": "Dual-Core 240MHz SoC with hardware UART/SPI"}, {"component_id": "COMP_NEO6M_GPS", "name": "u-blox NEO-6M GPS Receiver Module", "category": "COMMUNICATION", "image_url": "/assets/components/gps.png", "specifications": "50-channel GPS engine, 9600 baud NMEA output"}, {"component_id": "COMP_DS18B20_PROBE", "name": "DS18B20 Waterproof 1-Wire Probe", "category": "DIGITAL_SENSOR", "image_url": "/assets/components/ds18b20.png", "specifications": "-55\u00b0C to +125\u00b0C precision 12-bit digital temp probe"}, {"component_id": "COMP_MICROSD_SPI", "name": "MicroSD Card SPI Breakout Module", "category": "SPI_STORAGE", "image_url": "/assets/components/sd.png", "specifications": "FAT32 SPI filesystem datalogging"}, {"component_id": "COMP_HCSR04", "name": "HC-SR04 Sonar (Distractor)", "category": "DIGITAL_SENSOR", "image_url": "/assets/components/sonar.png", "specifications": "Ultrasonic distance sensor (Distractor)"}, {"component_id": "COMP_5V_RELAY", "name": "Relay Module (Distractor)", "category": "ACTUATOR", "image_url": "/assets/components/relay.png", "specifications": "Mechanical relay (Distractor)"}]}'::jsonb, 'Medium', 2.0, 180, 1, 'Active', '2026-09-09 14:46:43.615733', '2026-09-09 14:46:43.615733') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (287, 26, 79, 'HARDWARE_SELECTION_PLACEMENT', 'Task 08: Industrial RS-485 Modbus Motor Vibration Monitor', '### Problem Statement
Engineer an industrial edge machine-health monitor for factory motors. The unit samples 3-axis vibration via a digital accelerometer, transmits Modbus RTU telemetry over an RS-485 differential bus, and operates safely off an industrial 24VDC factory power rail.

### Technical Specifications
- **Controller**: 32-bit ARM Cortex-M microcontroller with hardware UART.
- **Industrial Bus**: RS-485 half-duplex differential transceiver module (MAX485/ISO3082).
- **Vibration Sensor**: 3-axis digital accelerometer on I2C bus.
- **Power Regulation**: High-efficiency wide-input 24V-to-5V step-down switching buck regulator.', NULL, '{"task_id": "IOT-TASK-08", "domain": "iot-hardware-systems", "round_type": "HARDWARE_SELECTION_PLACEMENT", "motherboard_config": {"board_id": "BOARD-IIOT-MODBUS-V3", "board_name": "Industrial Modbus Vibration Carrier PCB", "slots": [{"slot_id": "SLOT_MCU", "label": "DSP MCU Socket", "supported_types": ["MICROCONTROLLER"], "pin_bus": "3.3V, GND, I2C, UART"}, {"slot_id": "SLOT_RS485_BUS", "label": "RS-485 Differential Port", "supported_types": ["COMMUNICATION"], "pin_bus": "A, B, GND, TX, RX"}, {"slot_id": "SLOT_VIB_SENSOR", "label": "I2C Vibration Sensor Slot", "supported_types": ["I2C_SENSOR"], "pin_bus": "3.3V, GND, SCL, SDA"}, {"slot_id": "SLOT_IND_POWER", "label": "24V Industrial Buck Port", "supported_types": ["POWER"], "pin_bus": "24V_IN, 5V_REG, GND"}]}, "component_palette": [{"component_id": "COMP_STM32F401", "name": "STM32F401 Nucleo-32 ARM Cortex-M4", "category": "MICROCONTROLLER", "image_url": "/assets/components/stm32f401.png", "specifications": "84MHz Cortex-M4 with hardware FPU"}, {"component_id": "COMP_ISO3082", "name": "MAX485/ISO3082 RS-485 Transceiver", "category": "COMMUNICATION", "image_url": "/assets/components/iso3082.png", "specifications": "Differential RS-485 transceiver, half duplex"}, {"component_id": "COMP_ADXL345", "name": "ADXL345 3-Axis Digital Accelerometer", "category": "I2C_SENSOR", "image_url": "/assets/components/adxl345.png", "specifications": "High-bandwidth 3-axis vibration sensing up to +/-16g"}, {"component_id": "COMP_LM2596_BUCK", "name": "LM2596 24V-to-5V Step-Down Buck Regulator", "category": "POWER", "image_url": "/assets/components/buck24.png", "specifications": "High efficiency switching regulator for 24V industrial rails"}, {"component_id": "COMP_7805_LIN", "name": "Linear 7805 Regulator (Distractor)", "category": "POWER", "image_url": "/assets/components/7805.png", "specifications": "Linear drop generates excessive heat and thermal shutdown on 24V"}, {"component_id": "COMP_HC05_BT", "name": "HC-05 Bluetooth (Distractor)", "category": "COMMUNICATION", "image_url": "/assets/components/hc05.png", "specifications": "Consumer short-range wireless (Not RS-485)"}, {"component_id": "COMP_DHT11", "name": "DHT11 Sensor (Distractor)", "category": "I2C_SENSOR", "image_url": "/assets/components/dht11.png", "specifications": "Low-accuracy humidity sensor (Cannot sense vibration)"}]}'::jsonb, 'Hard', 3.0, 240, 1, 'Active', '2026-09-09 14:46:43.627807', '2026-09-09 14:46:43.627807') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (288, 26, 81, 'HARDWARE_SELECTION_PLACEMENT', 'Task 09: Remote Agritech LoRaWAN Weather & Solenoid Station', '### Problem Statement
Design an autonomous agricultural station deployed in remote farm fields. The node must monitor environmental weather (temperature, humidity, air pressure), evaluate soil moisture, transmit field metrics over long-range LoRaWAN (868MHz), trigger a 12V irrigation solenoid valve, and recharge off a solar MPPT battery management system.

### Technical Specifications
- **Processor**: Dual-core 32-bit Wi-Fi/BLE microcontroller.
- **Long Range RF**: SPI LoRaWAN transceiver (SX1276/SX1262).
- **Weather Sensor**: I2C multi-parameter environmental sensor.
- **Moisture Sensor**: Analog capacitive soil moisture probe.
- **Valve Actuator**: Optoisolated relay module controlling irrigation flow.
- **Solar Harvest**: MPPT lithium solar charging controller.', NULL, '{"task_id": "IOT-TASK-09", "domain": "iot-hardware-systems", "round_type": "HARDWARE_SELECTION_PLACEMENT", "motherboard_config": {"board_id": "BOARD-AGRI-SOLAR-V3", "board_name": "Agritech LoRa Solar Station PCB", "slots": [{"slot_id": "SLOT_MCU", "label": "Compute Core Socket", "supported_types": ["MICROCONTROLLER"], "pin_bus": "3.3V, GND, SPI, I2C, ADC, GPIO"}, {"slot_id": "SLOT_LORA_RF", "label": "LoRa Sub-GHz Header", "supported_types": ["COMMUNICATION"], "pin_bus": "3.3V, GND, MOSI, MISO, SCK, CS (GPIO5)"}, {"slot_id": "SLOT_WEATHER", "label": "I2C Weather Port", "supported_types": ["I2C_SENSOR"], "pin_bus": "3.3V, GND, SCL, SDA"}, {"slot_id": "SLOT_SOIL_ANALOG", "label": "Analog Soil Probe Port", "supported_types": ["ANALOG_SENSOR"], "pin_bus": "3.3V, GND, ADC0"}, {"slot_id": "SLOT_SOLENOID_RELAY", "label": "Irrigation Valve Relay Header", "supported_types": ["ACTUATOR"], "pin_bus": "5V, GND, IN (GPIO14)"}, {"slot_id": "SLOT_SOLAR_MPPT", "label": "Solar MPPT Charger Port", "supported_types": ["POWER"], "pin_bus": "SOLAR+, BAT+, 5V_SYS, GND"}]}, "component_palette": [{"component_id": "COMP_ESP32_WROOM", "name": "ESP32-WROOM-32D Module", "category": "MICROCONTROLLER", "image_url": "/assets/components/esp32.png", "specifications": "Dual-Core 240MHz SoC with ADC and SPI"}, {"component_id": "COMP_SX1276_LORA", "name": "Semtech SX1276 LoRa RF Module", "category": "COMMUNICATION", "image_url": "/assets/components/lora.png", "specifications": "868MHz long-range wireless telemetry"}, {"component_id": "COMP_BME680", "name": "Bosch BME680 Environmental Sensor", "category": "I2C_SENSOR", "image_url": "/assets/components/bme680.png", "specifications": "Temperature, Humidity, Pressure on I2C"}, {"component_id": "COMP_CAP_SOIL", "name": "Capacitive Soil Moisture Probe", "category": "ANALOG_SENSOR", "image_url": "/assets/components/soil.png", "specifications": "Corrosion-proof analog voltage probe"}, {"component_id": "COMP_5V_RELAY", "name": "5V Optoisolated Relay Module", "category": "ACTUATOR", "image_url": "/assets/components/relay.png", "specifications": "10A 250VAC solenoid valve switching"}, {"component_id": "COMP_CN3791_MPPT", "name": "CN3791 MPPT Solar Charger Shield", "category": "POWER", "image_url": "/assets/components/mppt.png", "specifications": "Maximum power point solar lithium charging"}, {"component_id": "COMP_HC05_BT", "name": "HC-05 Bluetooth (Distractor)", "category": "COMMUNICATION", "image_url": "/assets/components/hc05.png", "specifications": "Short-range Bluetooth (Distractor)"}, {"component_id": "COMP_7805_LIN", "name": "Linear 7805 (Distractor)", "category": "POWER", "image_url": "/assets/components/7805.png", "specifications": "Linear drop wastes battery energy (Distractor)"}]}'::jsonb, 'Hard', 3.0, 240, 1, 'Active', '2026-09-09 14:46:43.641220', '2026-09-09 14:46:43.641220') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (289, 26, 81, 'HARDWARE_SELECTION_PLACEMENT', 'Task 10: Smart Home AC Energy Monitor & Safe Load Switch Hub', '### Problem Statement
Develop a residential smart energy dashboard gateway. The system measures AC mains power consumption non-invasively via a current transformer clamp, displays real-time energy usage on a local OLED screen, and performs arc-free AC load switching using a Solid State Relay (SSR).

### Technical Specifications
- **Processing Core**: Wi-Fi enabled microcontroller with 12-bit ADC and I2C.
- **AC Current Sensor**: Non-invasive split-core Current Transformer (CT) clamp.
- **Local Display**: 0.96-inch monochrome I2C OLED display.
- **AC Switching Actuator**: Optocoupled Solid State Relay (SSR) for silent, arc-free AC switching.', NULL, '{"task_id": "IOT-TASK-10", "domain": "iot-hardware-systems", "round_type": "HARDWARE_SELECTION_PLACEMENT", "motherboard_config": {"board_id": "BOARD-ENERGY-SSR-V1", "board_name": "Smart Energy & AC Switching PCB", "slots": [{"slot_id": "SLOT_MCU", "label": "Wi-Fi MCU Core Socket", "supported_types": ["MICROCONTROLLER"], "pin_bus": "3.3V, GND, I2C, ADC0, GPIO"}, {"slot_id": "SLOT_CT_SENSOR", "label": "Current Transformer Port", "supported_types": ["CURRENT_SENSOR"], "pin_bus": "CT+, CT-, ADC0, GND"}, {"slot_id": "SLOT_I2C_OLED", "label": "I2C Display Header", "supported_types": ["DISPLAY"], "pin_bus": "3.3V, GND, SCL, SDA"}, {"slot_id": "SLOT_SSR_OUTPUT", "label": "Solid State Relay Output", "supported_types": ["ACTUATOR"], "pin_bus": "5V_TRIG (GPIO15), GND, AC_L, AC_N"}]}, "component_palette": [{"component_id": "COMP_ESP32_WROOM", "name": "ESP32-WROOM-32 Module", "category": "MICROCONTROLLER", "image_url": "/assets/components/esp32.png", "specifications": "Dual-Core 240MHz with 12-bit ADC and Wi-Fi/MQTT"}, {"component_id": "COMP_SCT013_CT", "name": "SCT-013-000 Non-Invasive 100A AC Current Clamp", "category": "CURRENT_SENSOR", "image_url": "/assets/components/sct013.png", "specifications": "Split-core current transformer clamp, 0-100A safe isolation"}, {"component_id": "COMP_OLED_096", "name": "0.96\" I2C OLED Display (SSD1306)", "category": "DISPLAY", "image_url": "/assets/components/oled.png", "specifications": "128x64 I2C screen for real-time kWh and wattage display"}, {"component_id": "COMP_SSR_RELAY", "name": "Solid State Relay (SSR-25DA) Module", "category": "ACTUATOR", "image_url": "/assets/components/ssr.png", "specifications": "25A 240VAC solid state optical switching, zero arcing"}, {"component_id": "COMP_RAW_SHUNT", "name": "Direct 230V Shunt Resistor (Distractor)", "category": "CURRENT_SENSOR", "image_url": "/assets/components/shunt.png", "specifications": "Non-isolated shunt (Lethal shock hazard)"}, {"component_id": "COMP_DC_MOSFET", "name": "DC-Only Power MOSFET (Distractor)", "category": "ACTUATOR", "image_url": "/assets/components/mosfet.png", "specifications": "DC only (Destroys circuit on AC mains)"}, {"component_id": "COMP_HCSR04", "name": "HC-SR04 Sonar (Distractor)", "category": "DIGITAL_SENSOR", "image_url": "/assets/components/sonar.png", "specifications": "Ultrasonic sensor (Distractor)"}]}'::jsonb, 'Hard', 3.0, 240, 1, 'Active', '2026-09-09 14:46:43.657250', '2026-09-09 14:46:43.657250') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (205, 25, 77, 'debugging', 'Fix String Copy Buffer & Missing Null Terminator', 'The following C program attempts to copy an input string to an allocated buffer, but contains an off-by-one boundary error and missing null termination causing undefined behavior. Fix the bug so that the string copies safely and matches the expected output.

Input Example:
systems

Output Example:
systems', '#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// BUGGY CODE: Fix memory allocation & null termination
int main() {
    char input[100];
    if (scanf("%s", input) != 1) return 0;
    
    int len = strlen(input);
    // FIX: Allocate len + 1 for null terminator
    char *copy = (char*)malloc((len + 1) * sizeof(char));
    
    for (int i = 0; i < len; i++) {
        copy[i] = input[i];
    }
    copy[len] = ''\0''; // FIX: Ensure null-termination
    
    printf("%s", copy);
    free(copy);
    return 0;
}
', NULL, 'Hard', 10.0, 180, 1, 'Archived', '2026-08-23 03:40:44.188392', '2026-09-14 16:37:35.569442') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (202, 24, 76, 'coding', 'In-Place String Reversal using Two Pointers', 'Implement a C program that reads a string from standard input and prints the reversed string to standard output using a two-pointer approach.

Input Example:
hello

Output Example:
olleh', '#include <stdio.h>
#include <string.h>

void reverseString(char *str) {
    int left = 0;
    int right = strlen(str) - 1;
    while (left < right) {
        char temp = str[left];
        str[left] = str[right];
        str[right] = temp;
        left++;
        right--;
    }
}

int main() {
    char str[1000];
    if (scanf("%s", str) == 1) {
        reverseString(str);
        printf("%s", str);
    }
    return 0;
}
', NULL, 'Medium', 10.0, 180, 1, 'Archived', '2026-08-23 03:40:44.177933', '2026-09-14 15:06:17.544098') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (203, 24, 76, 'coding', 'Dynamic Array Min-Max Finder', 'Write a C program that reads an integer N followed by N integers. Allocate memory dynamically using malloc(), find the minimum and maximum elements in the array, and print them formatted as ''Min: X, Max: Y''.

Input Example:
5
10 25 5 40 15

Output Example:
Min: 5, Max: 40', '#include <stdio.h>
#include <stdlib.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) return 0;
    
    int *arr = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }
    
    int min = arr[0];
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] < min) min = arr[i];
        if (arr[i] > max) max = arr[i];
    }
    
    printf("Min: %d, Max: %d", min, max);
    free(arr);
    return 0;
}
', NULL, 'Hard', 10.0, 180, 1, 'Archived', '2026-08-23 03:40:44.178456', '2026-09-14 15:06:17.544098') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (255, 3, 11, 'mcq', 'Idempotent HTTP Methods in RESTful API Architecture', 'According to RFC 9110 (HTTP Semantics), which of the following HTTP methods are strictly defined as **Idempotent**?', NULL, '[{"id": 1, "text": "GET, PUT, DELETE, HEAD, and OPTIONS"}, {"id": 2, "text": "POST, PATCH, and CONNECT"}, {"id": 3, "text": "Only GET and POST"}, {"id": 4, "text": "POST and PUT only"}]'::jsonb, 'Easy', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (256, 3, 12, 'mcq', 'Git Fast-Forward Merge vs 3-Way Merge Commit', 'When executing `git merge feature-branch` into `main`, under what exact condition will Git perform a **Fast-Forward (FF)** merge instead of creating a 3-way merge commit?', NULL, '[{"id": 1, "text": "When the HEAD of `main` is an ancestor of `feature-branch` and no new commits have occurred on `main` since branching"}, {"id": 2, "text": "When both branches have exactly the same number of commits"}, {"id": 3, "text": "When all commits on feature-branch are signed with GPG keys"}, {"id": 4, "text": "When merge conflicts are resolved automatically by Git"}]'::jsonb, 'Easy', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (257, 3, 15, 'mcq', 'Cache-Aside (Lazy-Loading) vs Write-Through Caching Pattern', 'In high-throughput microservice caching architectures, what is the defining characteristic of the **Cache-Aside** pattern?', NULL, '[{"id": 1, "text": "The application code first checks cache; on cache miss, it reads from database, updates the cache, and returns data to client"}, {"id": 2, "text": "The database writes to the cache synchronously upon every table INSERT/UPDATE"}, {"id": 3, "text": "Cache entries are persisted to disk and never expire"}, {"id": 4, "text": "The cache intercepts network sockets directly at the OS kernel level"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (204, 24, 76, 'coding', 'Character Frequency Counter', 'Write a C program that reads a string and a target character. Count and print the total occurrences of the target character in the string.

Input Example:
programming
m

Output Example:
2', '#include <stdio.h>
#include <string.h>

int countOccurrences(const char *str, char target) {
    int count = 0;
    while (*str) {
        if (*str == target) count++;
        str++;
    }
    return count;
}

int main() {
    char str[1000];
    char target;
    if (scanf("%s %c", str, &target) == 2) {
        printf("%d", countOccurrences(str, target));
    }
    return 0;
}
', NULL, 'Easy', 10.0, 180, 1, 'Archived', '2026-08-23 03:40:44.185651', '2026-09-14 15:06:17.544098') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (290, 24, 76, 'coding', 'Q01: Find the Largest of Three Numbers', 'Write a C program to find the largest among three integers without using any built-in max functions.\n\nInput Format:\nThree space-separated integers a, b, c.\n\nOutput Format:\nPrint the largest integer.\n\nExample 1:\nInput: 10 25 15\nOutput: 25\n\nExample 2:\nInput: -5 -2 -9\nOutput: -2', '#include <stdio.h>

int findLargest(int a, int b, int c) {
    int max = a;
    if (b > max) max = b;
    if (c > max) max = c;
    return max;
}

int main() {
    int a, b, c;
    if (scanf("%d %d %d", &a, &b, &c) == 3) {
        printf("%d\n", findLargest(a, b, c));
    }
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.571614', '2026-09-14 15:06:17.571614') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (261, 9, 31, 'mcq', 'Customer Retention Cohort & Churn Rate Analysis', 'An enterprise SaaS business acquires a January cohort of 1,000 customers. At Month 1, 800 customers remain active. At Month 2, 720 customers remain active. At Month 3, 648 customers remain active. What is the constant compound monthly churn rate of this cohort from Month 1 to Month 3?', NULL, '[{"id": 1, "text": "8.0%"}, {"id": 2, "text": "10.0%"}, {"id": 3, "text": "12.5%"}, {"id": 4, "text": "15.0%"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (291, 24, 76, 'coding', 'Q02: Check Even or Odd without Modulo', 'Given an integer, determine whether it is even or odd without using the modulo (%) operator.\n\nInput Format:\nA single integer n.\n\nOutput Format:\nPrint ''Even'' or ''Odd''.\n\nExample 1:\nInput: 8\nOutput: Even\n\nExample 2:\nInput: 7\nOutput: Odd', '#include <stdio.h>

const char* checkEvenOrOdd(int n) {
    if ((n & 1) == 0) {
        return "Even";
    } else {
        return "Odd";
    }
}

int main() {
    int n;
    if (scanf("%d", &n) == 1) {
        printf("%s\n", checkEvenOrOdd(n));
    }
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.602579', '2026-09-14 15:06:17.602579') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (258, 4, 13, 'debugging', 'Fix Infinite Recursion in Graph Cycle Detection (DFS)', 'The following Python function is designed to detect if a directed graph has a cycle using Depth-First Search (DFS). However, it contains a bug where it causes a `RecursionError: maximum recursion depth exceeded` on cyclical graphs because node state tracking is missing. Fix the function so that it correctly returns `True` if a cycle exists and `False` otherwise.', 'import sys
from collections import defaultdict

def has_cycle(num_nodes, edges):
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
    
    # BUG: Node state tracking is incomplete
    def dfs(node):
        for neighbor in adj[node]:
            if dfs(neighbor):
                return True
        return False

    for i in range(num_nodes):
        if dfs(i):
            return True
    return False

def main():
    lines = sys.stdin.read().strip().splitlines()
    if not lines:
        return
    n, m = map(int, lines[0].split())
    edges = []
    for line in lines[1:m+1]:
        u, v = map(int, line.split())
        edges.append((u, v))
    print("true" if has_cycle(n, edges) else "false")

if __name__ == ''__main__'':
    main()
', '[]'::jsonb, 'Medium', 10.0, 180, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-08 14:32:02.420523') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (262, 10, 33, 'sql', 'Year-over-Year (YoY) Quarterly Growth Rate via LAG() Window Function', 'Given a table `quarterly_sales (year INT, quarter INT, revenue NUMERIC)`, write a standard SQL query to calculate each quarter''s Year-over-Year (YoY) percentage revenue growth compared to the exact same quarter of the previous year. Columns returned should be: `year`, `quarter`, `revenue`, and `yoy_growth_pct`.', NULL, '[]'::jsonb, 'Medium', 10.0, 120, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-08 14:32:02.420523') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (209, 1, 3, 'mcq', 'XOR Swap & Identity Theorem', 'Given two integers `x = 45` and `y = 20`, the three operations `x = x ^ y; y = x ^ y; x = x ^ y;` are executed sequentially. What are the final values of `x` and `y`?', NULL, '[{"id": 1, "text": "x = 45, y = 20"}, {"id": 2, "text": "x = 20, y = 45"}, {"id": 3, "text": "x = 65, y = 25"}, {"id": 4, "text": "x = 0, y = 0"}]'::jsonb, 'Easy', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (210, 1, 4, 'mcq', 'Time Complexity of Nested Dependent Loops', 'Consider the following code snippet:
```python
for i in range(1, n + 1):
    j = 1
    while j < n:
        j = j * 2
```
What is the asymptotic worst-case time complexity of this algorithm in Big-O notation?', NULL, '[{"id": 1, "text": "O(n)"}, {"id": 2, "text": "O(n log n)"}, {"id": 3, "text": "O(n^2)"}, {"id": 4, "text": "O(log n)"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (292, 24, 76, 'coding', 'Q03: Reverse an Integer', 'Given an integer, produce its reverse. Handle negative numbers and numbers ending in zero correctly.\n\nInput Format:\nA single integer n.\n\nOutput Format:\nPrint the reversed integer.\n\nExample 1:\nInput: 12345\nOutput: 54321\n\nExample 2:\nInput: 1200\nOutput: 21', '#include <stdio.h>

long long reverseInteger(int n) {
    long long rev = 0;
    int sign = (n < 0) ? -1 : 1;
    long long num = (n < 0) ? -(long long)n : n;
    
    while (num > 0) {
        rev = rev * 10 + (num % 10);
        num /= 10;
    }
    return rev * sign;
}

int main() {
    int n;
    if (scanf("%d", &n) == 1) {
        printf("%lld\n", reverseInteger(n));
    }
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.612865', '2026-09-14 15:06:17.612865') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (212, 1, 1, 'mcq', 'Critical Path & Task Dependency Graph', 'A CI/CD deployment pipeline consists of 4 tasks: A (Linting, 3 min), B (Unit Tests, 5 min), C (Security Scan, 4 min), and D (Deployment, 2 min). Task D strictly requires both B and C to complete. Tasks A, B, and C can run concurrently from start (time 0). What is the minimum duration from start to finish?', NULL, '[{"id": 1, "text": "7 minutes"}, {"id": 2, "text": "9 minutes"}, {"id": 3, "text": "11 minutes"}, {"id": 4, "text": "14 minutes"}]'::jsonb, 'Easy', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (213, 1, 3, 'mcq', 'Recursive Call Stack Frame Evaluation', 'Consider the recurrence function `def f(n): return 1 if n <= 1 else f(n - 1) + f(n - 2)`. When evaluating `f(4)` without memoization, what is the total number of function calls (including the initial call) executed?', NULL, '[{"id": 1, "text": "7"}, {"id": 2, "text": "8"}, {"id": 3, "text": "9"}, {"id": 4, "text": "15"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (293, 24, 76, 'coding', 'Q04: Check Palindrome Number', 'Determine whether a given number reads the same forward and backward. Negative numbers are not palindromes.\n\nInput Format:\nA single integer n.\n\nOutput Format:\nPrint ''Palindrome'' or ''Not Palindrome''.\n\nExample 1:\nInput: 121\nOutput: Palindrome\n\nExample 2:\nInput: 123\nOutput: Not Palindrome', '#include <stdio.h>

int isPalindrome(int n) {
    if (n < 0) return 0;
    long long original = n;
    long long reversed = 0;
    long long temp = n;
    while (temp > 0) {
        reversed = reversed * 10 + (temp % 10);
        temp /= 10;
    }
    return (original == reversed);
}

int main() {
    int n;
    if (scanf("%d", &n) == 1) {
        if (isPalindrome(n)) printf("Palindrome\n");
        else printf("Not Palindrome\n");
    }
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.623195', '2026-09-14 15:06:17.623195') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (294, 24, 76, 'coding', 'Q05: Count Digits of an Integer', 'Given an integer n, count how many digits it contains. Handle 0 and negative numbers properly.\n\nInput Format:\nA single integer n.\n\nOutput Format:\nPrint the total digit count.\n\nExample 1:\nInput: 98765\nOutput: 5\n\nExample 2:\nInput: 0\nOutput: 1', '#include <stdio.h>

int countDigits(long long n) {
    if (n == 0) return 1;
    if (n < 0) n = -n;
    int count = 0;
    while (n > 0) {
        count++;
        n /= 10;
    }
    return count;
}

int main() {
    long long n;
    if (scanf("%lld", &n) == 1) {
        printf("%d\n", countDigits(n));
    }
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.631745', '2026-09-14 15:06:17.631745') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (216, 1, 1, 'mcq', 'Boolean Circuit Equivalence & Logic Optimization', 'Which of the following Boolean expressions is logically equivalent to `!(is_admin || !has_token)` according to De Morgan''s laws?', NULL, '[{"id": 1, "text": "!is_admin && has_token"}, {"id": 2, "text": "!is_admin || has_token"}, {"id": 3, "text": "is_admin && !has_token"}, {"id": 4, "text": "!is_admin && !has_token"}]'::jsonb, 'Easy', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (217, 1, 4, 'mcq', 'Min-Heap Insertion & Parent Node Calculation', 'In a 1-indexed binary min-heap array `[3, 8, 5, 12, 14, 9, 7]`, a new key `4` is inserted at the end of the array (index 8). After executing the standard bubble-up (heapify-up) procedure, at which index will the key `4` reside?', NULL, '[{"id": 1, "text": "Index 1"}, {"id": 2, "text": "Index 2"}, {"id": 3, "text": "Index 4"}, {"id": 4, "text": "Index 8"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (218, 1, 9, 'mcq', 'CPU Scheduling Average Turnaround Time (SJF)', 'Three processes arrive at time 0 with burst times: P1 = 6ms, P2 = 2ms, P3 = 4ms. Using non-preemptive Shortest Job First (SJF) scheduling, what is the average Turnaround Time (TAT) of the processes?', NULL, '[{"id": 1, "text": "5.33 ms"}, {"id": 2, "text": "6.67 ms"}, {"id": 3, "text": "8.00 ms"}, {"id": 4, "text": "9.33 ms"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (219, 1, 10, 'mcq', 'CIDR IPv4 Subnet Usable Host Capacity', 'A network engineer assigns an IPv4 subnet of `192.168.10.64/27` to a web server cluster. How many usable host IP addresses are available within this subnet for allocation to server network interfaces?', NULL, '[{"id": 1, "text": "28"}, {"id": 2, "text": "30"}, {"id": 3, "text": "32"}, {"id": 4, "text": "62"}]'::jsonb, 'Easy', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (221, 1, 3, 'mcq', 'Two-Pointer Traversal Optimization', 'To find whether any two elements in a sorted array of `N` numbers sum to target `K`, which algorithmic pattern achieves $O(N)$ time complexity with $O(1)$ auxiliary space?', NULL, '[{"id": 1, "text": "Two pointers initialized at start and end of array moving inward"}, {"id": 2, "text": "Nested binary search over all elements"}, {"id": 3, "text": "Building an auxiliary hash set"}, {"id": 4, "text": "Prefix sum scanning"}]'::jsonb, 'Easy', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (222, 1, 1, 'mcq', 'Deductive Syllogism in Software Testing', 'Given the following premises:
1. All high-severity bugs block production releases.
2. Some memory leak issues are high-severity bugs.
Which of the following conclusions logically follows with certainty?', NULL, '[{"id": 1, "text": "All memory leak issues block production releases."}, {"id": 2, "text": "Some memory leak issues block production releases."}, {"id": 3, "text": "No low-severity bugs block production releases."}, {"id": 4, "text": "All production releases contain memory leaks."}]'::jsonb, 'Easy', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (223, 1, 4, 'mcq', 'Hash Table Primary Clustering in Linear Probing', 'What is the primary drawback of using Linear Probing `(h(k, i) = (h''(k) + i) % m)` compared to Quadratic Probing or Double Hashing for collision resolution in an open-addressed hash table?', NULL, '[{"id": 1, "text": "Primary clustering where occupied slots form long contiguous chains"}, {"id": 2, "text": "Inability to store negative integer keys"}, {"id": 3, "text": "Excessive dynamic memory allocation overhead"}, {"id": 4, "text": "Requirement of quadratic hash functions"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (224, 1, 2, 'mcq', 'Cache Hit Ratio & Effective Memory Access Time (EMAT)', 'A processor has an L1 cache access time of 2 ns and main memory access time of 50 ns. If the L1 cache hit ratio is `90%` (0.90), what is the Effective Memory Access Time (EMAT)?', NULL, '[{"id": 1, "text": "4.8 ns"}, {"id": 2, "text": "6.8 ns"}, {"id": 3, "text": "7.0 ns"}, {"id": 4, "text": "9.2 ns"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (295, 24, 76, 'coding', 'Q06: Sum of Digits of an Integer', 'Calculate the sum of all digits of a given positive integer.\n\nInput Format:\nA single integer n.\n\nOutput Format:\nPrint the sum of its digits.\n\nExample 1:\nInput: 1234\nOutput: 10\n\nExample 2:\nInput: 999\nOutput: 27', '#include <stdio.h>

int sumOfDigits(int n) {
    if (n < 0) n = -n;
    int sum = 0;
    while (n > 0) {
        sum += (n % 10);
        n /= 10;
    }
    return sum;
}

int main() {
    int n;
    if (scanf("%d", &n) == 1) {
        printf("%d\n", sumOfDigits(n));
    }
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.634526', '2026-09-14 15:06:17.634526') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (226, 1, 9, 'mcq', 'LRU Page Replacement Fault Count', 'Consider a system with 3 initially empty physical page frames. The sequence of page references is: `[1, 2, 3, 2, 4, 1, 3]`. Using the Least Recently Used (LRU) page replacement algorithm, how many total page faults occur?', NULL, '[{"id": 1, "text": "4"}, {"id": 2, "text": "5"}, {"id": 3, "text": "6"}, {"id": 4, "text": "7"}]'::jsonb, 'Hard', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (227, 1, 10, 'mcq', 'TCP Window Size & Bandwidth-Delay Product (BDP)', 'A high-speed cross-continental fiber link has a capacity of 10 Gbps and a round-trip time (RTT) of 80 milliseconds. What is the Bandwidth-Delay Product (BDP) required for a single TCP connection to fully saturate the pipe?', NULL, '[{"id": 1, "text": "10 Megabytes"}, {"id": 2, "text": "80 Megabytes"}, {"id": 3, "text": "100 Megabytes"}, {"id": 4, "text": "800 Megabytes"}]'::jsonb, 'Hard', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (228, 1, 1, 'mcq', 'Truth Table Verification for Resource Authorization', 'An API gateway evaluates access with the rule: `Allow = (is_owner || is_admin) && !is_suspended`. Under which of the following combinations is access GRANTED?', NULL, '[{"id": 1, "text": "is_owner = False, is_admin = True, is_suspended = False"}, {"id": 2, "text": "is_owner = True, is_admin = False, is_suspended = True"}, {"id": 3, "text": "is_owner = False, is_admin = False, is_suspended = False"}, {"id": 4, "text": "is_owner = True, is_admin = True, is_suspended = True"}]'::jsonb, 'Easy', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (229, 1, 4, 'mcq', 'Balanced Binary Search Tree Minimum Height', 'What is the minimum possible height of a balanced Binary Search Tree containing `N = 1000` distinct nodes (defining height of a single-node tree as 0)?', NULL, '[{"id": 1, "text": "8"}, {"id": 2, "text": "9"}, {"id": 3, "text": "10"}, {"id": 4, "text": "11"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (264, 10, 35, 'mcq', 'Dynamic Two-Way Matrix Lookup in Excel', 'In an Excel financial model with products listed in rows (A2:A100) and months listed in columns (B1:M1), which formula dynamically retrieves the exact sales value for product in cell P2 and month in cell Q2 without hardcoding ranges?', NULL, '[{"id": 1, "text": "=INDEX(B2:M100, MATCH(P2, A2:A100, 0), MATCH(Q2, B1:M1, 0))"}, {"id": 2, "text": "=VLOOKUP(P2, A2:M100, Q2, FALSE)"}, {"id": 3, "text": "=HLOOKUP(Q2, A1:M100, MATCH(P2, A2:A100, 0), TRUE)"}, {"id": 4, "text": "=XLOOKUP(P2, A2:A100, Q2:Q100)"}]'::jsonb, 'Easy', 2.0, 120, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (265, 12, 37, 'mcq', 'Tableau Level of Detail (LOD) FIXED vs INCLUDE Expressions', 'In Tableau Desktop, what is the primary behavioral difference between `{FIXED [Region] : SUM([Sales])}` and `{INCLUDE [Region] : SUM([Sales])}`?', NULL, '[{"id": 1, "text": "`FIXED` computes the aggregate strictly at the Region dimension level regardless of the view''s granularity, whereas `INCLUDE` adds Region to whatever dimensions are already present in the view"}, {"id": 2, "text": "`FIXED` cannot be used in calculated fields; `INCLUDE` can only be used on measures"}, {"id": 3, "text": "`FIXED` is calculated after Dimension filters; `INCLUDE` is calculated before Context filters"}, {"id": 4, "text": "`INCLUDE` filters out all NULL regions automatically"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (266, 12, 50, 'mcq', 'Visual Perception & Chart Selection for Net Sentiment Scores', 'A Business Intelligence analyst needs to display customer satisfaction survey responses across 10 service categories containing both positive (+40% to +100%) and negative (-40% to -10%) net promoter ratings. Which chart type provides the highest cognitive clarity for visual comparison across the zero baseline?', NULL, '[{"id": 1, "text": "Diverging Horizontal Bar Chart anchored at the zero axis"}, {"id": 2, "text": "Pie chart with 10 colored slices"}, {"id": 3, "text": "Stacked Area chart"}, {"id": 4, "text": "Radar chart with filled polygons"}]'::jsonb, 'Easy', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (267, 12, 49, 'mcq', 'Tableau Order of Operations: Context Filters vs Dimension Filters', 'In Tableau''s Order of Operations, why would an analyst promote a normal Dimension Filter (e.g. `Year = 2026`) to a **Context Filter** (gray pill)?', NULL, '[{"id": 1, "text": "To force the filter to execute BEFORE Top-N filters and FIXED Level of Detail (LOD) calculations"}, {"id": 2, "text": "To hide the filter control from dashboard viewers"}, {"id": 3, "text": "To convert the field from discrete to continuous"}, {"id": 4, "text": "To bypass user security filters"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (268, 12, 37, 'mcq', 'Tableau Performance Optimization: Extract Aggregation Strategy', 'A Tableau workbook connected to a 50-million row database table experiences slow rendering on an executive summary dashboard that only displays monthly regional sales. What is the most effective extract optimization technique?', NULL, '[{"id": 1, "text": "Aggregate data to visible dimensions (Month, Region) and hide all unused columns during extract creation"}, {"id": 2, "text": "Convert all numeric measures to string data types"}, {"id": 3, "text": "Switch from Hyper extract format to live CSV file link"}, {"id": 4, "text": "Add 20 floating text objects to cache rendering"}]'::jsonb, 'Easy', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (269, 13, 41, 'text_response', 'Handling Data Skew & Salting Join Keys in Large-Scale Analytics Pipelines', 'In your data analytics projects, suppose you encounter a severe data skew issue where 90% of order transactions belong to a single default `customer_id = 0` (Guest Checkout), causing distributed joins to bottle-neck on a single reducer/worker node. Explain how you would detect this skew and implement key salting or two-stage aggregation to resolve the bottleneck.', NULL, '[]'::jsonb, 'Hard', 5.0, 120, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (263, 10, 33, 'sql', 'Identify Consecutive Active Login Streaks via Gaps-and-Islands CTE', 'Given a table `user_logins (user_id INT, login_date DATE)`, write a SQL query to identify users who logged in for at least 3 consecutive calendar days. Output unique `user_id` values.', NULL, '[]'::jsonb, 'Hard', 10.0, 120, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-08 14:32:02.420523') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (231, 3, 7, 'mcq', 'B+ Tree Indexing vs Hash Index Characteristics', 'Why are B+ Tree indices preferred over Hash indices as the primary default index structure in relational database storage engines (such as InnoDB)?', NULL, '[{"id": 1, "text": "B+ Trees support efficient range scans (BETWEEN, <, >) and ordered traversals"}, {"id": 2, "text": "B+ Trees offer O(1) exact point lookups compared to O(N) for Hash indices"}, {"id": 3, "text": "Hash indices require contiguous physical disk blocks"}, {"id": 4, "text": "B+ Trees eliminate disk I/O entirely"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (235, 3, 7, 'mcq', 'Database Sharding vs Horizontal Partitioning', 'What is the key architectural difference between database Horizontal Partitioning and Database Sharding?', NULL, '[{"id": 1, "text": "Sharding distributes partitions across multiple distinct physical database server instances, whereas horizontal partitioning typically resides on a single instance"}, {"id": 2, "text": "Partitioning splits tables column-wise, whereas sharding splits tables row-wise"}, {"id": 3, "text": "Sharding is only possible in NoSQL databases"}, {"id": 4, "text": "Horizontal partitioning requires distributed 2-Phase Commit"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (236, 3, 9, 'mcq', 'Mutex vs Counting Semaphore Synchronization', 'What is the primary operational distinction between a Binary Mutex and a Counting Semaphore initialized to count 1?', NULL, '[{"id": 1, "text": "A Mutex enforces ownership: only the specific thread that acquired/locked the Mutex can unlock it"}, {"id": 2, "text": "A Counting Semaphore can only be used between separate processes, not threads"}, {"id": 3, "text": "A Mutex allows up to 2 concurrent threads"}, {"id": 4, "text": "A Semaphore disables CPU interrupts upon lock"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (241, 3, 10, 'mcq', 'TLS 1.3 Handshake Round Trips vs TLS 1.2', 'How many round-trip times (RTTs) are required to complete a full initial cryptographic handshake in TLS 1.3 compared to TLS 1.2?', NULL, '[{"id": 1, "text": "TLS 1.3 requires 1-RTT (or 0-RTT on resumption); TLS 1.2 requires 2-RTTs"}, {"id": 2, "text": "TLS 1.3 requires 3-RTTs; TLS 1.2 requires 1-RTT"}, {"id": 3, "text": "Both protocols require exactly 2-RTTs"}, {"id": 4, "text": "TLS 1.3 eliminates the underlying TCP handshake"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (242, 3, 10, 'mcq', 'TCP 3-Way Handshake Connection Establishment', 'What is the exact sequence of TCP packet flags exchanged between client and server to establish a reliable stream connection?', NULL, '[{"id": 1, "text": "Client sends SYN -> Server responds SYN-ACK -> Client sends ACK"}, {"id": 2, "text": "Client sends ACK -> Server responds SYN -> Client sends ACK"}, {"id": 3, "text": "Client sends SYN -> Server responds ACK -> Client sends FIN"}, {"id": 4, "text": "Client sends PING -> Server responds PONG -> Client sends DATA"}]'::jsonb, 'Easy', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (199, 23, 74, 'mcq', 'Pointer to Const vs Const Pointer', 'In the declaration ''const int *ptr;'', which of the following operations is forbidden by the C compiler?', NULL, '["*ptr = 25;", "ptr = &another_var;", "ptr++;", "int val = *ptr;"]'::jsonb, 'Hard', 3.0, 90, 1, 'Active', '2026-08-23 03:40:44.158085', '2026-09-08 14:32:02.386295') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (200, 23, 73, 'mcq', 'Bitwise In-place XOR Swap', 'What happens after executing:
a ^= b;
b ^= a;
a ^= b;
(Assuming a and b are distinct integer variables)?', NULL, '["The values of a and b are swapped without temporary memory", "Both a and b become 0", "Both a and b become -1", "a retains its value, b becomes 0"]'::jsonb, 'Medium', 2.0, 60, 1, 'Active', '2026-08-23 03:40:44.170174', '2026-09-08 14:32:02.386295') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (201, 23, 74, 'mcq', 'Function Pointer Declaration', 'Which declaration correctly defines a function pointer named ''funcPtr'' that takes two ints as parameters and returns an int?', NULL, '["int (*funcPtr)(int, int);", "int *funcPtr(int, int);", "int (funcPtr*)(int, int);", "(*int funcPtr)(int, int);"]'::jsonb, 'Hard', 3.0, 90, 1, 'Active', '2026-08-23 03:40:44.170174', '2026-09-08 14:32:02.386295') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (296, 24, 76, 'coding', 'Q07: Find Factorial', 'Calculate the factorial of an integer N (0 <= N <= 20). Return the exact value as a 64-bit integer.\n\nInput Format:\nA single integer N.\n\nOutput Format:\nPrint N!\n\nExample 1:\nInput: 5\nOutput: 120\n\nExample 2:\nInput: 0\nOutput: 1', '#include <stdio.h>

unsigned long long factorial(int n) {
    if (n <= 1) return 1;
    unsigned long long res = 1;
    for (int i = 2; i <= n; i++) {
        res *= i;
    }
    return res;
}

int main() {
    int n;
    if (scanf("%d", &n) == 1) {
        printf("%llu\n", factorial(n));
    }
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.649181', '2026-09-14 15:06:17.649181') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (297, 24, 76, 'coding', 'Q08: Generate Fibonacci Series', 'Print the first N Fibonacci numbers separated by space, starting with 0 and 1.\n\nInput Format:\nA single integer N (N >= 1).\n\nOutput Format:\nFirst N Fibonacci numbers separated by space.\n\nExample 1:\nInput: 5\nOutput: 0 1 1 2 3\n\nExample 2:\nInput: 1\nOutput: 0', '#include <stdio.h>

void printFibonacci(int n) {
    long long a = 0, b = 1;
    for (int i = 0; i < n; i++) {
        if (i == 0) {
            printf("%lld", a);
        } else if (i == 1) {
            printf(" %lld", b);
        } else {
            long long c = a + b;
            printf(" %lld", c);
            a = b;
            b = c;
        }
    }
    printf("\n");
}

int main() {
    int n;
    if (scanf("%d", &n) == 1 && n > 0) {
        printFibonacci(n);
    }
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.654859', '2026-09-14 15:06:17.654859') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (298, 24, 76, 'coding', 'Q09: Check Prime Number', 'Determine whether a given integer N is prime.\n\nInput Format:\nA single integer N.\n\nOutput Format:\nPrint ''Prime'' or ''Not Prime''.\n\nExample 1:\nInput: 13\nOutput: Prime\n\nExample 2:\nInput: 1\nOutput: Not Prime', '#include <stdio.h>
#include <stdbool.h>

bool isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; (long long)i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

int main() {
    int n;
    if (scanf("%d", &n) == 1) {
        if (isPrime(n)) printf("Prime\n");
        else printf("Not Prime\n");
    }
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.665339', '2026-09-14 15:06:17.665339') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (246, 3, 6, 'mcq', 'Liskov Substitution Principle (LSP) Violation Scenario', 'Which of the following object-oriented designs is a classic violation of the Liskov Substitution Principle (LSP)?', NULL, '[{"id": 1, "text": "A `Square` subclass inherits from `Rectangle`, overriding `setWidth()` to simultaneously alter `height` and breaking caller assumptions of independent dimensions"}, {"id": 2, "text": "A `Car` class implements a `Vehicle` interface and provides a `drive()` method"}, {"id": 3, "text": "A `UserRepository` class implements a `Repository` interface using Dependency Injection"}, {"id": 4, "text": "A `Circle` class encapsulates a private `radius` field with public getters"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (247, 3, 6, 'mcq', 'Factory Method vs Abstract Factory Design Pattern', 'When should an architect select the **Abstract Factory** design pattern over a simple **Factory Method**?', NULL, '[{"id": 1, "text": "When a system needs to create families of related or dependent product objects (e.g. MacButton + MacCheckbox vs WinButton + WinCheckbox) without specifying concrete classes"}, {"id": 2, "text": "When only a single object needs to be instantiated globally across the entire application lifetime"}, {"id": 3, "text": "When adding dynamic behavior to an existing object at runtime without subclassing"}, {"id": 4, "text": "When converting the interface of a legacy class into an interface expected by clients"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (248, 3, 6, 'mcq', 'Observer Pattern & Event-Driven Decoupling', 'What is the primary architectural advantage of using the **Observer Pattern** (Publish-Subscribe) for inter-component communication in GUI or event-driven applications?', NULL, '[{"id": 1, "text": "Loose coupling: Subject maintains a list of dependents without knowing their concrete implementations, notifying them via a common interface"}, {"id": 2, "text": "Elimination of dynamic memory allocations during event dispatch"}, {"id": 3, "text": "Guaranteeing strictly synchronous sequential execution across CPU threads"}, {"id": 4, "text": "Automatic persistence of events to a SQL database"}]'::jsonb, 'Easy', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (249, 3, 6, 'mcq', 'Dependency Injection & Inversion of Control (IoC)', 'Why is Dependency Injection (DI) considered a best practice in enterprise software engineering?', NULL, '[{"id": 1, "text": "It decouples class implementation from object construction, allowing dependencies to be swapped for mock implementations during unit testing"}, {"id": 2, "text": "It compiles application code into native assembly binaries automatically"}, {"id": 3, "text": "It replaces relational database queries with memory pointers"}, {"id": 4, "text": "It forces all class methods to execute in parallel"}]'::jsonb, 'Easy', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (384, 25, 77, 'debugging', 'D35: Find Length of Linked List', 'Problem Statement:
Count the number of nodes.

Debug Hint:
The function does not count every node. head is advanced twice per iteration.', '#include <stdio.h>

struct Node {
    int data;
    struct Node *next;
};

int length(struct Node *head) {
    int count = 0;

    while (head != NULL) {
        count++;
        head = head->next;
        head = head->next;
    }

    return count;
}', '{"debug_hint": "The function does not count every node. head is advanced twice per iteration.", "problem": "Count the number of nodes."}'::jsonb, 'Medium', 10.0, 300, 1, 'Active', '2026-09-14 16:37:35.690739', '2026-09-14 16:37:35.690739') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (251, 3, 11, 'mcq', 'JSON Web Token (JWT) Security: Signature vs Encryption', 'A developer stores a raw plaintext database password inside a standard HMAC-SHA256 signed JSON Web Token (JWT) payload. Why is this a critical security vulnerability?', NULL, '[{"id": 1, "text": "A standard JWT signature only provides cryptographic integrity and authenticity; the payload is only Base64URL-encoded and can be read by anyone"}, {"id": 2, "text": "HMAC-SHA256 automatically reverses plaintext into public key pairs"}, {"id": 3, "text": "JWT tokens cannot be transmitted over HTTPS"}, {"id": 4, "text": "The signature expires after 5 seconds"}]'::jsonb, 'Easy', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (252, 3, 7, 'mcq', 'SQL Injection Prevention Mechanism', 'Why does using **Parameterized Queries (Prepared Statements)** completely eliminate SQL Injection vulnerabilities?', NULL, '[{"id": 1, "text": "The database driver compiles the SQL statement structure beforehand and treats user input strictly as literal data parameters, never executable SQL code"}, {"id": 2, "text": "It strips all quotation marks and apostrophes from user inputs"}, {"id": 3, "text": "It converts all SQL statements to NoSQL documents"}, {"id": 4, "text": "It runs queries inside a dedicated web application firewall (WAF)"}]'::jsonb, 'Easy', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (253, 3, 11, 'mcq', 'Cross-Site Request Forgery (CSRF) & SameSite Cookie Attribute', 'How does setting `SameSite=Strict` on authentication session cookies defend web applications against Cross-Site Request Forgery (CSRF) attacks?', NULL, '[{"id": 1, "text": "The browser will refuse to send the cookie on any cross-site request originating from a third-party domain"}, {"id": 2, "text": "It encrypts the cookie using the client''s SSL private certificate"}, {"id": 3, "text": "It prevents JavaScript from accessing the cookie via document.cookie"}, {"id": 4, "text": "It limits the cookie expiration to the active tab session"}]'::jsonb, 'Medium', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (270, 13, 40, 'text_response', 'Automated Data Drift Detection & Schema Evolution in Production ETL', 'Describe how you implemented or would design an automated data validation and drift detection layer in your analytics pipeline. Address: (1) Handling schema drift (new unexpected columns or changed data types from source APIs), (2) Detecting statistical distribution drift (e.g. sudden drop in non-null rates or mean transaction value), and (3) Automated alerting and quarantine dead-letter queues.', NULL, '[]'::jsonb, 'Hard', 5.0, 120, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (299, 24, 76, 'coding', 'Q10: Print Prime Numbers in a Range', 'Given two integers L and R (L <= R), print all prime numbers between them separated by space. If none exist, print -1.\n\nInput Format:\nTwo space-separated integers L and R.\n\nOutput Format:\nSpace-separated primes, or -1.\n\nExample 1:\nInput: 10 20\nOutput: 11 13 17 19\n\nExample 2:\nInput: 14 16\nOutput: -1', '#include <stdio.h>
#include <stdbool.h>

bool isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; (long long)i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

int main() {
    int l, r;
    if (scanf("%d %d", &l, &r) == 2) {
        int count = 0;
        for (int i = l; i <= r; i++) {
            if (isPrime(i)) {
                if (count > 0) printf(" ");
                printf("%d", i);
                count++;
            }
        }
        if (count == 0) printf("-1");
        printf("\n");
    }
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.669884', '2026-09-14 15:06:17.669884') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (211, 1, 2, 'mcq', 'Microservice Throughput & Work-Rate', 'Server Alpha processes a queue of 6,000 asynchronous jobs in 3 hours. Server Beta processes the same queue of 6,000 jobs in 2 hours. If both servers process the queue concurrently without lock contention, how many minutes will they take to process 6,000 jobs?', NULL, '[{"id": 1, "text": "60 minutes"}, {"id": 2, "text": "72 minutes"}, {"id": 3, "text": "80 minutes"}, {"id": 4, "text": "90 minutes"}]'::jsonb, 'Hard', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 10:38:10.365071') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (214, 1, 4, 'mcq', 'Queue using Two Stacks Amortized Cost', 'A Queue data structure is implemented using two standard LIFO stacks (`inbox` and `outbox`). For a sequence of `N` `enqueue` operations followed by `N` `dequeue` operations on an initially empty queue, what is the amortized time complexity per individual operation?', NULL, '[{"id": 1, "text": "O(1)"}, {"id": 2, "text": "O(N)"}, {"id": 3, "text": "O(log N)"}, {"id": 4, "text": "O(N log N)"}]'::jsonb, 'Hard', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 10:38:10.365071') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (215, 1, 2, 'mcq', 'Fault Tolerance Cluster Availability Probability', 'A high-availability database cluster has 3 independent replica nodes. Each node has an independent failure probability of `p = 0.10` over a 24-hour period. The cluster remains online as long as AT LEAST ONE node is operational. What is the probability that the cluster remains online?', NULL, '[{"id": 1, "text": "0.900"}, {"id": 2, "text": "0.970"}, {"id": 3, "text": "0.990"}, {"id": 4, "text": "0.999"}]'::jsonb, 'Hard', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 10:38:10.365071') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (220, 1, 2, 'mcq', 'Database Replication Lag & Bandwidth Calculation', 'A database write-ahead log (WAL) of size 1.8 Gigabytes (GB) needs to be replicated over a dedicated 100 Megabits per second (Mbps) network link. Assuming 100% link utilization and no protocol overhead (1 GB = 1,000 MB; 1 Byte = 8 bits), how many seconds will the replication take?', NULL, '[{"id": 1, "text": "14.4 seconds"}, {"id": 2, "text": "18.0 seconds"}, {"id": 3, "text": "144.0 seconds"}, {"id": 4, "text": "180.0 seconds"}]'::jsonb, 'Hard', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 10:38:10.365071') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (225, 1, 3, 'mcq', 'Bitmask Generation of Power Set Subsets', 'For a set `S = {''A'', ''B'', ''C'', ''D''}` with 4 elements, bitmasks from `0` to `15` (`0b0000` to `0b1111`) are used to represent all subsets. Which subset is represented by the integer bitmask `11` (binary `1011` where LSB index 0 corresponds to ''A'')?', NULL, '[{"id": 1, "text": "{''A'', ''B'', ''D''}"}, {"id": 2, "text": "{''A'', ''C'', ''D''}"}, {"id": 3, "text": "{''B'', ''C'', ''D''}"}, {"id": 4, "text": "{''A'', ''B'', ''C''}"}]'::jsonb, 'Hard', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 10:38:10.365071') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (230, 1, 2, 'mcq', 'Data Compression Ratio & Space Savings', 'An uncompressed text file contains 10,000 characters encoded in standard 8-bit ASCII (80,000 bits total). After applying Huffman variable-length prefix coding, the average character length is reduced to 3.2 bits. What percentage of space savings is achieved?', NULL, '[{"id": 1, "text": "40%"}, {"id": 2, "text": "50%"}, {"id": 3, "text": "60%"}, {"id": 4, "text": "65%"}]'::jsonb, 'Hard', 2.0, 90, 1, 'Active', '2026-09-06 03:08:34.388025', '2026-09-06 10:38:10.365071') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (4, 2, 4, 'coding', 'Two Sum Target Indices', '### Problem Statement
Given an array of integers `nums` and an integer `target`, return the 0-based indices of the two numbers such that they add up to `target`.

You may assume that each input will have exactly one solution, and you may not use the same element twice.

### Input Format
- Line 1: Space-separated integers representing `nums`
- Line 2: Single integer representing `target`

### Output Format
- Space-separated indices in ascending order (e.g. `0 1`)

### Constraints
- $2 \le 	ext{nums.length} \le 10^5$
- $-10^9 \le 	ext{nums}[i] \le 10^9$
- Time Limit: 2.0 seconds
', 'import sys

def solve():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    nums = list(map(int, lines[0].split()))
    target = int(lines[1].strip())
    
    # Write your solution here
    seen = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            print(f"{seen[complement]} {i}")
            return
        seen[num] = i

if __name__ == ''__main__'':
    solve()
', '[]'::jsonb, 'Hard', 20.0, 3, 1, 'Active', '2026-08-20 13:59:34.124738', '2026-09-06 10:38:10.417169') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (232, 3, 7, 'mcq', 'Write-Ahead Logging (WAL) & Durability', 'In relational DBMS transaction engines, how does the Write-Ahead Logging (WAL) protocol guarantee ACID Durability without immediately flushing dirty table pages to disk on commit?', NULL, '[{"id": 1, "text": "Changes are sequentially appended to an immutable append-only log on disk before commit acknowledges"}, {"id": 2, "text": "Dirty pages are compressed and stored directly into CPU registers"}, {"id": 3, "text": "Transactions bypass cache and write directly to non-volatile RAM"}, {"id": 4, "text": "Table pages are locked permanently until database restart"}]'::jsonb, 'Hard', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 10:38:10.427517') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (233, 3, 7, 'mcq', 'Database Isolation Levels: Read Committed vs Repeatable Read', 'Under the SQL standard `READ COMMITTED` isolation level, which concurrency anomaly can still occur that is strictly prevented under `REPEATABLE READ`?', NULL, '[{"id": 1, "text": "Dirty Read"}, {"id": 2, "text": "Non-Repeatable (Fuzzy) Read"}, {"id": 3, "text": "Dirty Write"}, {"id": 4, "text": "Lost Update during row lock"}]'::jsonb, 'Hard', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 10:38:10.427517') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (234, 3, 7, 'mcq', 'Database Connection Pool Starvation Root Cause', 'An API service under peak load experiences `PoolTimeoutError: Connection not available`. System metrics show database CPU is at 8% and memory is stable. What is the most likely software architecture defect?', NULL, '[{"id": 1, "text": "Database connections are opened in HTTP handlers but not released in a finally/context manager block during errors"}, {"id": 2, "text": "The database storage disk is running out of inodes"}, {"id": 3, "text": "The query cache has exceeded 100% capacity"}, {"id": 4, "text": "PostgreSQL is executing automatic VACUUM on unindexed tables"}]'::jsonb, 'Hard', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 10:38:10.427517') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (243, 3, 11, 'mcq', 'CORS Preflight OPTIONS Request Trigger Conditions', 'Under the Cross-Origin Resource Sharing (CORS) standard, which of the following triggers a browser to send an automatic preflight `OPTIONS` request before the actual HTTP request?', NULL, '[{"id": 1, "text": "A PUT or DELETE request, or a request with custom headers like `Authorization: Bearer <token>`"}, {"id": 2, "text": "Any standard GET request without custom headers"}, {"id": 3, "text": "A POST request with `Content-Type: application/x-www-form-urlencoded`"}, {"id": 4, "text": "An image loaded via standard `<img src=''...''>` HTML tag"}]'::jsonb, 'Hard', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 10:38:10.427517') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (244, 3, 10, 'mcq', 'DNS Recursive vs Iterative Query Resolution', 'When a client machine queries a local Recursive DNS Resolver for `api.example.com`, what role does the recursive resolver perform on behalf of the client?', NULL, '[{"id": 1, "text": "It queries the Root DNS server, TLD (.com) server, and Authoritative DNS server iteratively until the final IP is obtained, then caches and returns it to the client"}, {"id": 2, "text": "It immediately forwards the request to the client browser to resolve directly"}, {"id": 3, "text": "It performs an SSL/TLS decryption on the domain name"}, {"id": 4, "text": "It redirects the client HTTP socket to port 53"}]'::jsonb, 'Hard', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 10:38:10.427517') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (245, 3, 10, 'mcq', 'HTTP/2 vs HTTP/3 Protocol Transport Architecture', 'What is the primary underlying transport protocol innovation of HTTP/3 that completely eliminates TCP Head-of-Line (HOL) blocking at the transport layer?', NULL, '[{"id": 1, "text": "QUIC protocol built on top of UDP with stream-level packet loss recovery"}, {"id": 2, "text": "Multiple parallel TCP sockets opened per domain"}, {"id": 3, "text": "SCTP protocol over raw Ethernet frames"}, {"id": 4, "text": "WebSocket compression frames"}]'::jsonb, 'Hard', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 10:38:10.427517') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (250, 3, 15, 'mcq', 'Microservices Circuit Breaker Pattern State Transitions', 'In a distributed microservice architecture, how does the **Circuit Breaker** pattern prevent cascading service failures when a downstream dependency is failing?', NULL, '[{"id": 1, "text": "Transitions from CLOSED to OPEN after error threshold is breached, immediately failing fast without calling downstream, then enters HALF-OPEN to probe recovery"}, {"id": 2, "text": "Spawns 10x more worker threads to retry failed calls continuously"}, {"id": 3, "text": "Caches all failed requests directly on client browsers forever"}, {"id": 4, "text": "Reroutes all database queries to unencrypted HTTP endpoints"}]'::jsonb, 'Hard', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 10:38:10.427517') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (254, 3, 11, 'mcq', 'Rate Limiting: Token Bucket vs Leaky Bucket Algorithms', 'What is the key behavioral difference between the **Token Bucket** and **Leaky Bucket** rate-limiting algorithms when handling bursts of incoming traffic?', NULL, '[{"id": 1, "text": "Token Bucket allows bursts of requests up to bucket capacity while maintaining a constant fill rate; Leaky Bucket outputs requests at a strictly smooth, constant rate"}, {"id": 2, "text": "Leaky Bucket allows infinite bursts; Token Bucket drops all burst traffic"}, {"id": 3, "text": "Token Bucket can only be used on TCP level; Leaky Bucket works on HTTP level"}, {"id": 4, "text": "Leaky Bucket requires distributed Redis memory; Token Bucket requires local CPU registers"}]'::jsonb, 'Hard', 2.0, 90, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 10:38:10.427517') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (300, 24, 76, 'coding', 'Q11: Find Maximum and Minimum in an Array', 'Given an array of N integers, find both the maximum and minimum values in a single traversal.\n\nInput Format:\nFirst line contains integer N.\nSecond line contains N space-separated integers.\n\nOutput Format:\nPrint ''Min: X, Max: Y''.\n\nExample 1:\nInput:\n5\n10 25 5 40 15\nOutput:\nMin: 5, Max: 40', '#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) return 0;
    int arr[1000];
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
    
    int min = arr[0], max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] < min) min = arr[i];
        if (arr[i] > max) max = arr[i];
    }
    printf("Min: %d, Max: %d\n", min, max);
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.681270', '2026-09-14 15:06:17.681270') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (301, 24, 76, 'coding', 'Q12: Calculate Array Average', 'Given an integer array of size N, calculate its sum and floating-point average formatted to 2 decimal places.\n\nInput Format:\nFirst line contains integer N.\nSecond line contains N integers.\n\nOutput Format:\nPrint ''Sum: S, Avg: A.AA''.\n\nExample 1:\nInput:\n4\n10 20 30 40\nOutput:\nSum: 100, Avg: 25.00', '#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) return 0;
    long long sum = 0;
    for (int i = 0; i < n; i++) {
        int val;
        scanf("%d", &val);
        sum += val;
    }
    double avg = (double)sum / n;
    printf("Sum: %lld, Avg: %.2f\n", sum, avg);
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.685051', '2026-09-14 15:06:17.685051') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (23, 5, 16, 'mcq', 'R1-Q14: Adjective vs Adverb', 'Select the correct sentence:', '', '[{"id": 1, "text": "Our technical support team works quick to resolve server outages."}, {"id": 2, "text": "Our technical support team works quickly to resolve server outages."}, {"id": 3, "text": "Our technical support team works more quicker to resolve outages."}, {"id": 4, "text": "Our team resolves outages very fastly."}]'::jsonb, 'Easy', 1.0, 60, 1, 'Active', '2026-08-20 13:59:34.281113', '2026-09-06 10:38:10.510010') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (33, 5, 28, 'mcq', 'R1-Q24: Tone Correction 4', 'Original Customer Support Message:
"give me your credit card password and otp so i can fix billing."

What is the critical failure in this message and how should it be corrected?', '', '[{"id": 1, "text": "Minor error; it should ask for CVV instead."}, {"id": 2, "text": "Critical compliance violation; agents must never request passwords or OTPs. The agent should guide the customer to update payment securely via their account dashboard."}, {"id": 3, "text": "It is acceptable if the customer agrees in chat."}, {"id": 4, "text": "The agent should request credit card photos instead."}]'::jsonb, 'Hard', 1.5, 60, 1, 'Active', '2026-08-20 13:59:34.399715', '2026-09-06 10:38:10.510010') ON CONFLICT DO NOTHING;
