INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (272, 8, 21, 'multi_chat_simulation', 'Simulation Scenario 3: Damaged In-Transit High-Value Electronics Return & Express Replacement', 'Customer Interaction Simulation: A customer unboxes a high-end 4K editing monitor purchased for a project deadline, discovering the display panel is cracked and packaging is water-damaged. Customer demands immediate same-day courier replacement before returning the broken unit.', NULL, '[]'::jsonb, 'Easy', 10.0, 120, 1, 'Active', '2026-09-06 03:19:07.924513', '2026-09-06 10:38:10.623741') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (303, 24, 76, 'coding', 'Q14: Count Even and Odd Elements in Array', 'Given an integer array of size N, count how many elements are even and how many are odd.\n\nInput Format:\nFirst line integer N.\nSecond line N space-separated integers.\n\nOutput Format:\nPrint ''Even: E, Odd: O''.\n\nExample 1:\nInput:\n5\n1 2 3 4 5\nOutput:\nEven: 2, Odd: 3', '#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) return 0;
    int even = 0, odd = 0;
    for (int i = 0; i < n; i++) {
        int val;
        scanf("%d", &val);
        if (val % 2 == 0) even++;
        else odd++;
    }
    printf("Even: %d, Odd: %d\n", even, odd);
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.705640', '2026-09-14 15:06:17.705640') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (304, 24, 76, 'coding', 'Q15: Find the Second-Largest Element', 'Find the second-largest distinct element in an array without sorting the array. If no distinct second-largest exists, print -1.\n\nInput Format:\nFirst line integer N.\nSecond line N integers.\n\nOutput Format:\nPrint second-largest value or -1.\n\nExample 1:\nInput:\n5\n12 35 1 10 34\nOutput:\n34\n\nExample 2:\nInput:\n3\n10 10 10\nOutput:\n-1', '#include <stdio.h>
#include <limits.h>

int findSecondLargest(int arr[], int n) {
    if (n < 2) return -1;
    int first = INT_MIN, second = INT_MIN;
    for (int i = 0; i < n; i++) {
        if (arr[i] > first) {
            second = first;
            first = arr[i];
        } else if (arr[i] > second && arr[i] != first) {
            second = arr[i];
        }
    }
    return (second == INT_MIN) ? -1 : second;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) return 0;
    int arr[1000];
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
    printf("%d\n", findSecondLargest(arr, n));
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.713026', '2026-09-14 15:06:17.713026') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (305, 24, 76, 'coding', 'Q16: Remove Duplicates from an Array', 'Given an array of N integers, remove duplicate values preserving the order of their first occurrence.\n\nInput Format:\nFirst line integer N.\nSecond line N integers.\n\nOutput Format:\nPrint unique elements separated by space.\n\nExample 1:\nInput:\n6\n1 2 2 3 4 4\nOutput:\n1 2 3 4', '#include <stdio.h>
#include <stdbool.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) return 0;
    int arr[1000];
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
    
    int unique[1000];
    int u_count = 0;
    for (int i = 0; i < n; i++) {
        bool exists = false;
        for (int j = 0; j < u_count; j++) {
            if (unique[j] == arr[i]) {
                exists = true;
                break;
            }
        }
        if (!exists) {
            unique[u_count++] = arr[i];
        }
    }
    for (int i = 0; i < u_count; i++) {
        printf("%d%s", unique[i], (i == u_count - 1) ? "" : " ");
    }
    printf("\n");
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.716040', '2026-09-14 15:06:17.716040') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (64, 9, 30, 'mcq', 'Q1.1: Revenue Trend Analysis', 'A retail company reported $120,000 in Q1 revenue, which grew by 25% in Q2, and then dropped by 10% in Q3. What is the net revenue for Q3?', '', '[{"id": "A", "text": "$135,000"}, {"id": "B", "text": "$140,000"}, {"id": "C", "text": "$145,000"}, {"id": "D", "text": "$150,000"}]'::jsonb, 'Easy', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.677752', '2026-09-08 14:32:02.351346') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (65, 9, 31, 'mcq', 'Q1.2: Data Quality & Missing Value Strategy', 'When analyzing a customer dataset of 100,000 records, you discover that 15% of ''Customer Age'' entries are null. Which approach is statistically sound for descriptive profiling before building a model?', '', '[{"id": "A", "text": "Immediately delete all 15,000 rows containing nulls."}, {"id": "B", "text": "Analyze missingness pattern (MCAR/MAR), impute using median/mode by customer segment, or analyze complete cases separately."}, {"id": "C", "text": "Replace all nulls with 0."}, {"id": "D", "text": "Replace all nulls with 100."}]'::jsonb, 'Easy', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.679757', '2026-09-08 14:32:02.351346') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (93, 11, 47, 'mcq', 'Q3.5b: Find Maximum Value Algorithmic Code Completion', 'Review the following Python algorithm designed to iterate through a list and return its maximum value:

```python
def find_max(numbers):
    max_value = numbers[0]
    for number in numbers:
        {{BLANK_1}}
    return max_value
```

Which code snippet correctly fills `{{BLANK_1}}` in the loop body to ensure `max_value` is updated accurately?', NULL, '[{"key": "A", "text": "if number > max_value:\n    max_value = number"}, {"key": "B", "text": "if number < max_value:\n    max_value = number"}, {"key": "C", "text": "max_value = max(numbers)"}, {"key": "D", "text": "if max_value == number:\n    continue"}]'::jsonb, 'Medium', 2.0, 240, 1, 'Active', '2026-08-20 13:59:34.949847', '2026-09-08 14:58:17.260028') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (96, 12, 49, 'mcq', 'Tableau Executive Sales Dashboard Creation', 'Explain the procedural step sequence in Tableau Desktop to build an executive sales dashboard displaying: 1. Total Sales KPI Card | 2. Regional Sales Bar Chart | 3. Monthly Sales Trend Line | 4. Global Region Filter.', NULL, '[{"key": "A", "text": "Step 1: Create 3 individual worksheets (KPI, Bar Chart, Line Chart) -> Step 2: Combine on Dashboard -> Step 3: Apply Region Filter to All Worksheets."}, {"key": "B", "text": "Step 1: Put all charts on 1 worksheet -> Step 2: Export directly to PDF -> Step 3: Publish to Server."}, {"key": "C", "text": "Step 1: Connect to database -> Step 2: Group measures into dimensions -> Step 3: Delete unassigned sheets."}, {"key": "D", "text": "Step 1: Create calculated field SUM(Sales) -> Step 2: Drag to Color Marks card -> Step 3: Disable dashboard actions."}]'::jsonb, 'Hard', 2.0, 300, 1, 'Active', '2026-08-20 13:59:34.987359', '2026-09-08 14:58:17.270411') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (306, 24, 76, 'coding', 'Q17: Linear Search', 'Given an array of N integers and a target value, find and print the 0-based index of its first occurrence, or -1 if not found.\n\nInput Format:\nFirst line integer N.\nSecond line N integers.\nThird line target integer.\n\nOutput Format:\nIndex of target or -1.\n\nExample 1:\nInput:\n5\n10 20 30 40 50\n30\nOutput:\n2', '#include <stdio.h>

int linearSearch(int arr[], int n, int target) {
    for (int i = 0; i < n; i++) {
        if (arr[i] == target) return i;
    }
    return -1;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) return 0;
    int arr[1000];
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
    int target;
    if (scanf("%d", &target) == 1) {
        printf("%d\n", linearSearch(arr, n, target));
    }
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.728786', '2026-09-14 15:06:17.728786') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (307, 24, 76, 'coding', 'Q18: Count Frequency of an Element', 'Given an array of N integers and a target value, count how many times the target occurs.\n\nInput Format:\nFirst line integer N.\nSecond line N integers.\nThird line target integer.\n\nOutput Format:\nTotal count.\n\nExample 1:\nInput:\n6\n1 2 3 2 2 5\n2\nOutput:\n3', '#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) return 0;
    int arr[1000];
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
    int target;
    if (scanf("%d", &target) == 1) {
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (arr[i] == target) count++;
        }
        printf("%d\n", count);
    }
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.736788', '2026-09-14 15:06:17.736788') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (308, 24, 76, 'coding', 'Q19: Reverse a String without strrev()', 'Reverse a string in-place without using library strrev().\n\nInput Format:\nA single continuous string.\n\nOutput Format:\nReversed string.\n\nExample 1:\nInput: hello\nOutput: olleh', '#include <stdio.h>
#include <string.h>

void reverseString(char *str) {
    int left = 0;
    int right = strlen(str) - 1;
    while (left < right) {
        char temp = str[left];
        str[left] = str[right];
        str[right] = temp;
        left++;
        right--;
    }
}

int main() {
    char str[1000];
    if (scanf("%s", str) == 1) {
        reverseString(str);
        printf("%s\n", str);
    }
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.747148', '2026-09-14 15:06:17.747148') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (309, 24, 76, 'coding', 'Q20: Check whether a String is a Palindrome', 'Determine whether a given string is a palindrome.\n\nInput Format:\nA single string.\n\nOutput Format:\nPrint ''Palindrome'' or ''Not Palindrome''.\n\nExample 1:\nInput: madam\nOutput: Palindrome', '#include <stdio.h>
#include <string.h>
#include <stdbool.h>

bool isPalindrome(const char *str) {
    int left = 0;
    int right = strlen(str) - 1;
    while (left < right) {
        if (str[left] != str[right]) return false;
        left++;
        right--;
    }
    return true;
}

int main() {
    char str[1000];
    if (scanf("%s", str) == 1) {
        if (isPalindrome(str)) printf("Palindrome\n");
        else printf("Not Palindrome\n");
    }
    return 0;
}
', NULL, 'Easy', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.753359', '2026-09-14 15:06:17.753359') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (310, 24, 76, 'coding', 'Q21: Find the Missing Number', 'Given an array containing N distinct numbers taken from 1 to N+1, find the one missing number.\n\nInput Format:\nFirst line integer N (count of present numbers).\nSecond line N space-separated integers.\n\nOutput Format:\nPrint missing number.\n\nExample 1:\nInput:\n4\n1 2 3 5\nOutput:\n4', '#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    long long total = ((long long)(n + 1) * (n + 2)) / 2;
    long long sum = 0;
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        sum += x;
    }
    printf("%lld\n", total - sum);
    return 0;
}
', NULL, 'Medium', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.760392', '2026-09-14 15:06:17.760392') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (311, 24, 76, 'coding', 'Q22: Find Duplicate Element in Array', 'Given an array of N+1 integers where each integer is between 1 and N, find the duplicated number.\n\nInput Format:\nFirst line integer N+1.\nSecond line N+1 integers.\n\nOutput Format:\nPrint duplicated integer.\n\nExample 1:\nInput:\n5\n1 3 4 2 2\nOutput:\n2', '#include <stdio.h>

int findDuplicate(int arr[], int n) {
    int slow = arr[0], fast = arr[0];
    do {
        slow = arr[slow];
        fast = arr[arr[fast]];
    } while (slow != fast);
    
    fast = arr[0];
    while (slow != fast) {
        slow = arr[slow];
        fast = arr[fast];
    }
    return slow;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int arr[1000];
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
    printf("%d\n", findDuplicate(arr, n));
    return 0;
}
