INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (312, 24, 76, 'coding', 'Q23: Move All Zeros to the End', 'Given an array of integers, move all 0''s to the end while maintaining the relative order of the non-zero elements in-place.\n\nInput Format:\nFirst line integer N.\nSecond line N integers.\n\nOutput Format:\nElements separated by space.\n\nExample 1:\nInput:\n5\n0 1 0 3 12\nOutput:\n1 3 12 0 0', '#include <stdio.h>

void moveZeros(int arr[], int n) {
    int insertPos = 0;
    for (int i = 0; i < n; i++) {
        if (arr[i] != 0) {
            arr[insertPos++] = arr[i];
        }
    }
    while (insertPos < n) {
        arr[insertPos++] = 0;
    }
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int arr[1000];
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
    moveZeros(arr, n);
    for (int i = 0; i < n; i++) {
        printf("%d%s", arr[i], (i == n - 1) ? "" : " ");
    }
    printf("\n");
    return 0;
}
', NULL, 'Medium', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.778505', '2026-09-14 15:06:17.778505') ON CONFLICT DO NOTHING;
