INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (72, 9, 42, 'mcq', 'Analytical Root Cause & Hypothesis Formulation', 'A digital commerce platform experiences a sudden 25% drop in weekly checkout conversion rate despite steady traffic volume. Detail your structured step-by-step analytical approach to isolate the root cause (e.g., funnel metrics, breakdown dimensions, technical vs marketing anomalies, and data verification steps).', NULL, '[{"key": "A", "text": "Segment conversion funnels across device OS, browsers, payment gateways, and regions to isolate step-specific drop-offs before verifying telemetry logs."}, {"key": "B", "text": "Immediately broadcast a site-wide 20% promotional discount coupon banner to artificially boost checkout volumes back to previous levels."}, {"key": "C", "text": "Purge all analytics tracking cookie sessions from the web server to reset user session duration averages."}, {"key": "D", "text": "Classify the conversion decrease as ordinary seasonal variance and wait for next month''s aggregate reporting before taking action."}]'::jsonb, 'Hard', 2.0, 300, 1, 'Active', '2026-08-20 13:59:34.736613', '2026-09-08 14:32:02.351346') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (73, 10, 33, 'mcq', 'Q2.1: Top Performing Sales Representatives by Region', 'Write an SQL query to retrieve the top sales rep (`rep_name`), region, and total revenue for each region where total revenue exceeds $50,000. Order by total revenue descending.', 'SELECT rep_name, region, SUM(amount) AS total_revenue
FROM sales
