INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (86, 11, 48, 'mcq', 'Q3.2: Pandas Merge vs Join Methodologies', 'You need to combine two Pandas DataFrames `df_orders` and `df_customers` on a common column `customer_id` keeping all orders regardless of customer match. Which Pandas method call correctly performs this operation?', NULL, '[{"key": "A", "text": "pd.merge(df_orders, df_customers, on=''customer_id'', how=''left'')"}, {"key": "B", "text": "pd.concat([df_orders, df_customers], axis=1)"}, {"key": "C", "text": "df_orders.join(df_customers, on=''customer_id'', how=''right'')"}, {"key": "D", "text": "pd.merge(df_orders, df_customers, how=''outer'')"}]'::jsonb, 'Medium', 2.0, 180, 1, 'Active', '2026-08-20 13:59:34.894644', '2026-09-08 14:32:02.361920') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (313, 24, 76, 'coding', 'Q24: Two Numbers Sum Equal to Target', 'Given an array of integers and a target sum, find two numbers whose sum equals target and print them in ascending order.\n\nInput Format:\nFirst line integer N.\nSecond line N integers.\nThird line target integer.\n\nOutput Format:\nPrint ''A B''.\n\nExample 1:\nInput:\n4\n2 7 11 15\n9\nOutput:\n2 7', '#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int arr[1000];
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
    int target;
    scanf("%d", &target);
    
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (arr[i] + arr[j] == target) {
                if (arr[i] <= arr[j]) printf("%d %d\n", arr[i], arr[j]);
                else printf("%d %d\n", arr[j], arr[i]);
                return 0;
            }
        }
    }
    return 0;
}
', NULL, 'Medium', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.786267', '2026-09-14 15:06:17.786267') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (314, 24, 76, 'coding', 'Q25: Intersection of Two Arrays', 'Given two arrays, find the unique elements that appear in both arrays.\n\nInput Format:\nFirst line N (size of array 1).\nSecond line N integers.\nThird line M (size of array 2).\nFourth line M integers.\n\nOutput Format:\nIntersection elements separated by space in order of occurrence in array 1.\n\nExample 1:\nInput:\n4\n1 2 2 1\n2\n2 2\nOutput:\n2', '#include <stdio.h>
#include <stdbool.h>

int main() {
    int n, m;
    if (scanf("%d", &n) != 1) return 0;
    int a[500];
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    if (scanf("%d", &m) != 1) return 0;
    int b[500];
    for (int i = 0; i < m; i++) scanf("%d", &b[i]);
    
    int printed[500];
    int p_count = 0;
    
    for (int i = 0; i < n; i++) {
        bool in_b = false;
        for (int j = 0; j < m; j++) {
            if (b[j] == a[i]) { in_b = true; break; }
        }
        if (in_b) {
            bool already_printed = false;
            for (int k = 0; k < p_count; k++) {
                if (printed[k] == a[i]) { already_printed = true; break; }
            }
            if (!already_printed) {
                if (p_count > 0) printf(" ");
                printf("%d", a[i]);
                printed[p_count++] = a[i];
            }
        }
    }
    printf("\n");
    return 0;
}
', NULL, 'Medium', 10.0, 120, 1, 'Active', '2026-09-14 15:06:17.792230', '2026-09-14 15:06:17.792230') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (87, 11, 47, 'mcq', 'Q3.3: Vectorized NumPy Operations vs Python Loops', 'Why is NumPy vectorization significantly faster than iterating through Python lists with explicit `for` loops when computing array element-wise operations?', NULL, '[{"key": "A", "text": "NumPy converts Python code into JavaScript prior to execution."}, {"key": "B", "text": "NumPy arrays use contiguous memory blocks and compiled C-level SIMD operations, avoiding Python dynamic type checking per element."}, {"key": "C", "text": "Python `for` loops consume twice as much disk space."}, {"key": "D", "text": "NumPy automatically disables multi-threading during execution."}]'::jsonb, 'Hard', 2.0, 180, 1, 'Active', '2026-08-20 13:59:34.904907', '2026-09-08 14:32:02.361920') ON CONFLICT DO NOTHING;
