', '[{"key": "A", "text": "return df[df[''salary''] > threshold][''name''].tolist()"}, {"key": "B", "text": "return df.filter(lambda x: x[''salary''] > threshold)"}, {"key": "C", "text": "return df.query(''salary == threshold'')[''name'']"}, {"key": "D", "text": "return df[''salary''].max()"}]'::jsonb, 'Hard', 10.0, 360, 1, 'Active', '2026-08-20 13:59:34.926298', '2026-09-08 14:32:02.361920') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (95, 11, 38, 'mcq', 'Q4.2: Pandas Practical Coding — Clean and Group Customer Sales', 'Write a Python function `process_sales(df)` that filters out records with null `Customer_ID`, fills missing `Sales_Amount` with the column median, and returns total sales grouped by `Category` sorted descending.', 'import pandas as pd

def process_sales(df: pd.DataFrame) -> pd.DataFrame:
    # Filter null Customer_ID
    df_clean = df[df[''Customer_ID''].notnull()].copy()
    # Impute missing Sales_Amount with median
    median_sales = df_clean[''Sales_Amount''].median()
    df_clean[''Sales_Amount''] = df_clean[''Sales_Amount''].fillna(median_sales)
    # Groupby Category and sum
    result = df_clean.groupby(''Category'')[''Sales_Amount''].sum().reset_index()
    return result.sort_values(by=''Sales_Amount'', ascending=False)', '[]'::jsonb, 'Medium', 2.0, 60, 1, 'Active', '2026-08-20 13:59:34.979400', '2026-09-08 14:32:02.378330') ON CONFLICT DO NOTHING;
