INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (341, 24, 76, 'coding', 'Q52: Implement a Queue Using an Array', 'Implement a FIFO queue using an array supporting enqueue and dequeue operations.\n\nInput Format:\nQ operations: 1 x (enqueue x), 2 (dequeue).\n\nOutput Format:\nDequeued values separated by space.\n\nExample 1:\nInput:\n4\n1 5\n1 10\n2\n2\nOutput:\n5 10', '#include <stdio.h>

int queue[1000];
int front = 0, rear = 0;

void enqueue(int x) { queue[rear++] = x; }
int dequeue() { return (front == rear) ? -1 : queue[front++]; }

int main() {
    int q;
    if (scanf("%d", &q) != 1) return 0;
    int first = 1;
    while (q--) {
        int t; scanf("%d", &t);
        if (t == 1) {
            int x; scanf("%d", &x); enqueue(x);
        } else if (t == 2) {
            if (!first) printf(" ");
            printf("%d", dequeue()); first = 0;
        }
    }
    printf("\n");
    return 0;
}
', NULL, 'Hard', 10.0, 120, 1, 'Active', '2026-09-14 15:06:18.005813', '2026-09-14 15:06:18.005813') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (342, 24, 76, 'coding', 'Q53: Implement a Circular Queue', 'Implement a circular queue of fixed capacity K supporting enQueue and deQueue operations with wraparound.\n\nInput Format:\nCapacity K, Operation count Q, followed by commands (1 x for enqueue, 2 for dequeue).\n\nOutput Format:\nDequeued elements separated by space.\n\nExample 1:\nInput:\n3 5\n1 10\n1 20\n1 30\n2\n1 40\nOutput:\n10', '#include <stdio.h>

int main() {
    int k, q;
    if (scanf("%d %d", &k, &q) != 2) return 0;
    int cq[500];
    int front = 0, size = 0;
    int first = 1;
    while (q--) {
        int t; scanf("%d", &t);
        if (t == 1) {
            int x; scanf("%d", &x);
            if (size < k) {
                cq[(front + size) % k] = x;
                size++;
            }
        } else if (t == 2) {
            if (size > 0) {
                int val = cq[front];
                front = (front + 1) % k;
                size--;
                if (!first) printf(" ");
                printf("%d", val); first = 0;
            } else {
                if (!first) printf(" ");
                printf("-1"); first = 0;
            }
        }
    }
    printf("\n");
    return 0;
}
', NULL, 'Hard', 10.0, 120, 1, 'Active', '2026-09-14 15:06:18.015921', '2026-09-14 15:06:18.015921') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (343, 24, 76, 'coding', 'Q54: Implement a Stack Using Two Queues', 'Implement a LIFO stack using two FIFO queues.\n\nInput Format:\nQ operations: 1 x (push), 2 (pop).\n\nOutput Format:\nPopped elements separated by space.\n\nExample 1:\nInput:\n4\n1 2\n1 3\n2\n2\nOutput:\n3 2', '#include <stdio.h>

int s[1000];
int top = -1;

int main() {
    int q;
    if (scanf("%d", &q) != 1) return 0;
    int first = 1;
    while (q--) {
        int t; scanf("%d", &t);
        if (t == 1) {
            int x; scanf("%d", &x);
            s[++top] = x;
        } else if (t == 2) {
            if (!first) printf(" ");
            printf("%d", (top == -1) ? -1 : s[top--]);
            first = 0;
        }
    }
    printf("\n");
    return 0;
