', NULL, 'Hard', 10.0, 120, 1, 'Active', '2026-09-14 15:06:18.015921', '2026-09-14 15:06:18.015921') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (344, 24, 76, 'coding', 'Q55: Evaluate a Postfix Expression', 'Evaluate an arithmetic postfix expression containing integers and operators (+, -, *, /).\n\nInput Format:\nSpace-separated postfix tokens on a single line.\n\nOutput Format:\nResulting integer.\n\nExample 1:\nInput: 2 3 1 * + 9 -\nOutput: -4', '#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

int stack[1000];
int top = -1;

int main() {
    char token[50];
    while (scanf("%s", token) == 1) {
        if (strlen(token) == 1 && (token[0] == ''+'' || token[0] == ''-'' || token[0] == ''*'' || token[0] == ''/'')) {
            int b = stack[top--];
            int a = stack[top--];
            if (token[0] == ''+'') stack[++top] = a + b;
            else if (token[0] == ''-'') stack[++top] = a - b;
            else if (token[0] == ''*'') stack[++top] = a * b;
            else if (token[0] == ''/'') stack[++top] = a / b;
        } else {
            stack[++top] = atoi(token);
        }
    }
    if (top >= 0) printf("%d\n", stack[top]);
    return 0;
}
', NULL, 'Hard', 10.0, 120, 1, 'Active', '2026-09-14 15:06:18.029652', '2026-09-14 15:06:18.029652') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (345, 24, 76, 'coding', 'Q56: Implement Binary Search Tree Operations', 'Implement BST insertion, search, and in-order traversal.\n\nInput Format:\nN operations: 1 x (insert x), 2 x (search x -> print ''Found''/''Not Found''). Followed by in-order traversal.\n\nOutput Format:\nSearch results then in-order traversal.\n\nExample 1:\nInput:\n4\n1 5\n1 3\n1 7\n2 3\nOutput:\nFound\n3 5 7', '#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct Node {
    int data;
    struct Node *left, *right;
} Node;

Node* insert(Node* root, int val) {
    if (!root) {
        Node* n = (Node*)malloc(sizeof(Node));
        n->data = val; n->left = n->right = NULL;
        return n;
    }
    if (val < root->data) root->left = insert(root->left, val);
    else root->right = insert(root->right, val);
    return root;
}

bool search(Node* root, int val) {
    if (!root) return false;
    if (root->data == val) return true;
    if (val < root->data) return search(root->left, val);
    return search(root->right, val);
}

int first_inorder = 1;
void inorder(Node* root) {
    if (!root) return;
    inorder(root->left);
    if (!first_inorder) printf(" ");
    printf("%d", root->data);
    first_inorder = 0;
    inorder(root->right);
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    Node* root = NULL;
    while (n--) {
        int t, v; scanf("%d %d", &t, &v);
        if (t == 1) root = insert(root, v);
        else if (t == 2) {
            if (search(root, v)) printf("Found\n");
            else printf("Not Found\n");
        }
    }
    inorder(root);
    printf("\n");
    return 0;
}
', NULL, 'Hard', 10.0, 120, 1, 'Active', '2026-09-14 15:06:18.036374', '2026-09-14 15:06:18.036374') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (346, 24, 76, 'coding', 'Q57: Find Height of a Binary Tree', 'Given a binary tree represented in level-order (with -1 representing NULL), calculate its maximum height using recursion.\n\nInput Format:\nN followed by N level-order values.\n\nOutput Format:\nHeight (empty tree height = 0).\n\nExample 1:\nInput:\n3\n1 2 3\nOutput:\n2', '#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node *left, *right;
} Node;

int max(int a, int b) { return a > b ? a : b; }

int height(Node* root) {
    if (!root) return 0;
    return 1 + max(height(root->left), height(root->right));
}

int main() {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) { printf("0\n"); return 0; }
    int val;
    scanf("%d", &val);
    if (val == -1) { printf("0\n"); return 0; }
    
    Node* nodes[1000];
    for (int i = 0; i < n; i++) {
        if (i > 0) scanf("%d", &val);
        if (val != -1) {
            nodes[i] = (Node*)malloc(sizeof(Node));
            nodes[i]->data = val; nodes[i]->left = nodes[i]->right = NULL;
        } else {
            nodes[i] = NULL;
        }
    }
    int j = 1;
    for (int i = 0; i < n && j < n; i++) {
        if (nodes[i]) {
            if (j < n) nodes[i]->left = nodes[j++];
            if (j < n) nodes[i]->right = nodes[j++];
        }
    }
    printf("%d\n", height(nodes[0]));
    return 0;
}
', NULL, 'Hard', 10.0, 120, 1, 'Active', '2026-09-14 15:06:18.046782', '2026-09-14 15:06:18.046782') ON CONFLICT DO NOTHING;
