INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (347, 24, 76, 'coding', 'Q58: Binary Tree Traversals (Inorder, Preorder, Postorder)', 'Given a binary tree in level order (with -1 for NULL), print its Inorder, Preorder, and Postorder traversals on three lines.\n\nInput Format:\nN followed by N integers.\n\nOutput Format:\nInorder\nPreorder\nPostorder\n\nExample 1:\nInput:\n3\n1 2 3\nOutput:\n2 1 3\n1 2 3\n2 3 1', '#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node *left, *right;
} Node;

int fi = 1;
void inorder(Node* r) {
    if (!r) return;
    inorder(r->left);
    if (!fi) printf(" ");
    printf("%d", r->data); fi = 0;
    inorder(r->right);
}

int fp = 1;
void preorder(Node* r) {
    if (!r) return;
    if (!fp) printf(" ");
    printf("%d", r->data); fp = 0;
    preorder(r->left);
    preorder(r->right);
}

int fpost = 1;
void postorder(Node* r) {
    if (!r) return;
    postorder(r->left);
    postorder(r->right);
    if (!fpost) printf(" ");
    printf("%d", r->data); fpost = 0;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) return 0;
    Node* nodes[500];
    for (int i = 0; i < n; i++) {
        int v; scanf("%d", &v);
        if (v != -1) {
            nodes[i] = (Node*)malloc(sizeof(Node));
            nodes[i]->data = v; nodes[i]->left = nodes[i]->right = NULL;
        } else nodes[i] = NULL;
    }
    int j = 1;
    for (int i = 0; i < n && j < n; i++) {
        if (nodes[i]) {
            if (j < n) nodes[i]->left = nodes[j++];
            if (j < n) nodes[i]->right = nodes[j++];
        }
    }
    inorder(nodes[0]); printf("\n");
    preorder(nodes[0]); printf("\n");
    postorder(nodes[0]); printf("\n");
    return 0;
}
', NULL, 'Hard', 10.0, 120, 1, 'Active', '2026-09-14 15:06:18.055654', '2026-09-14 15:06:18.055654') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (348, 24, 76, 'coding', 'Q59: Find Lowest Common Ancestor (LCA) in a Binary Tree', 'Given two node values in a binary tree, find their Lowest Common Ancestor (LCA).\n\nInput Format:\nN (count of nodes), val1, val2.\nNext line: N node values in level order (-1 for NULL).\n\nOutput Format:\nValue of LCA node.\n\nExample 1:\nInput:\n5 3 7\n10 5 15 3 7\nOutput:\n5', '#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node *left, *right;
} Node;

Node* lca(Node* root, int n1, int n2) {
    if (!root) return NULL;
    if (root->data == n1 || root->data == n2) return root;
    Node* left = lca(root->left, n1, n2);
    Node* right = lca(root->right, n1, n2);
    if (left && right) return root;
    return left ? left : right;
}

int main() {
    int n, v1, v2;
    if (scanf("%d %d %d", &n, &v1, &v2) != 3) return 0;
    Node* nodes[500];
    for (int i = 0; i < n; i++) {
        int v; scanf("%d", &v);
        if (v != -1) {
            nodes[i] = (Node*)malloc(sizeof(Node));
            nodes[i]->data = v; nodes[i]->left = nodes[i]->right = NULL;
        } else nodes[i] = NULL;
    }
    int j = 1;
    for (int i = 0; i < n && j < n; i++) {
        if (nodes[i]) {
            if (j < n) nodes[i]->left = nodes[j++];
            if (j < n) nodes[i]->right = nodes[j++];
        }
    }
    Node* ans = lca(nodes[0], v1, v2);
    if (ans) printf("%d\n", ans->data);
    else printf("-1\n");
    return 0;
}
', NULL, 'Hard', 10.0, 120, 1, 'Active', '2026-09-14 15:06:18.064397', '2026-09-14 15:06:18.064397') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (349, 24, 76, 'coding', 'Q60: Implement an LRU Cache', 'Design an LRU Cache supporting get(key) and put(key, value) operations in O(1) average time.\n\nInput Format:\nCapacity C, Operation count Q, followed by commands (1 k v for put, 2 k for get).\n\nOutput Format:\nOutputs of get operations separated by space.\n\nExample 1:\nInput:\n2 5\n1 1 10\n1 2 20\n2 1\n1 3 30\n2 2\nOutput:\n10 -1', '#include <stdio.h>
#include <stdlib.h>

typedef struct DNode {
    int key, val;
    struct DNode *prev, *next;
} DNode;

int cap, size = 0;
DNode *head = NULL, *tail = NULL;
DNode* map[10001] = {NULL};

void moveToHead(DNode* n) {
    if (n == head) return;
    if (n->prev) n->prev->next = n->next;
    if (n->next) n->next->prev = n->prev;
    if (n == tail) tail = n->prev;
    n->next = head;
    n->prev = NULL;
    if (head) head->prev = n;
    head = n;
    if (!tail) tail = head;
}

void put(int k, int v) {
    if (map[k]) {
        map[k]->val = v;
        moveToHead(map[k]);
        return;
    }
    if (size == cap) {
        map[tail->key] = NULL;
        DNode* rem = tail;
        tail = tail->prev;
        if (tail) tail->next = NULL;
        else head = NULL;
        free(rem);
        size--;
    }
    DNode* n = (DNode*)malloc(sizeof(DNode));
    n->key = k; n->val = v; n->prev = NULL; n->next = head;
    if (head) head->prev = n;
    head = n;
    if (!tail) tail = head;
    map[k] = n;
    size++;
}

int get(int k) {
    if (!map[k]) return -1;
    moveToHead(map[k]);
    return map[k]->val;
}

int main() {
    int q;
    if (scanf("%d %d", &cap, &q) != 2) return 0;
    int first = 1;
    while (q--) {
        int t; scanf("%d", &t);
        if (t == 1) {
            int k, v; scanf("%d %d", &k, &v);
            put(k, v);
        } else if (t == 2) {
            int k; scanf("%d", &k);
            if (!first) printf(" ");
            printf("%d", get(k));
            first = 0;
        }
    }
    printf("\n");
    return 0;
}
', NULL, 'Hard', 10.0, 120, 1, 'Active', '2026-09-14 15:06:18.073424', '2026-09-14 15:06:18.073424') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (206, 25, 77, 'debugging', 'Fix Binary Search Infinite Loop Indexing', 'The following C binary search implementation hangs in an infinite loop due to improper boundary updates. Fix the search logic so that it prints the 0-based index of the target integer, or -1 if not found.

Input Example:
5
10 20 30 40 50
30

Output Example:
2', '#include <stdio.h>

int binarySearch(int arr[], int n, int target) {
    int low = 0;
    int high = n - 1;
    
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == target) {
            return mid;
        } else if (arr[mid] < target) {
            low = mid + 1; // FIX: increment low
        } else {
            high = mid - 1; // FIX: decrement high
        }
    }
    return -1;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int arr[100];
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
    int target;
    if (scanf("%d", &target) != 1) return 0;
    
    printf("%d", binarySearch(arr, n, target));
    return 0;
}
', NULL, 'Easy', 10.0, 180, 1, 'Archived', '2026-08-23 03:40:44.188392', '2026-09-14 16:37:35.569442') ON CONFLICT DO NOTHING;
