INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (375, 25, 77, 'debugging', 'D26: Binary Search', 'Problem Statement:
Search for a target in a sorted array using binary search.

Debug Hint:
The middle-index calculation is incorrect. Division has higher precedence than addition: use (low + high) / 2.', '#include <stdio.h>

int main() {
    int arr[] = {10, 20, 30, 40, 50};
    int low = 0, high = 4;
    int target = 40;

    while (low <= high) {
        int mid = low + high / 2;

        if (arr[mid] == target) {
            printf("Found");
            return 0;
        }
        else if (arr[mid] < target)
            low = mid + 1;
        else
            high = mid - 1;
    }

    printf("Not Found");

    return 0;
}', '{"debug_hint": "The middle-index calculation is incorrect. Division has higher precedence than addition: use (low + high) / 2.", "problem": "Search for a target in a sorted array using binary search."}'::jsonb, 'Medium', 10.0, 300, 1, 'Active', '2026-09-14 16:37:35.663601', '2026-09-14 16:37:35.663601') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (376, 25, 77, 'debugging', 'D27: Recursive Factorial', 'Problem Statement:
