INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (382, 25, 77, 'debugging', 'D33: Traverse a Linked List', 'Problem Statement:
Print all nodes in a linked list.

