INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (385, 25, 77, 'debugging', 'D36: Reverse Linked List', 'Problem Statement:
Reverse a singly linked list.

Debug Hint:
The current node is lost before its pointer is changed. Use a next temporary pointer to retain the unreversed chain.', '#include <stdio.h>

struct Node {
    int data;
    struct Node *next;
};

struct Node* reverse(struct Node *head) {
    struct Node *prev = NULL;
    struct Node *current = head;

    while (current != NULL) {
        current = current->next;
        current->next = prev;
        prev = current;
    }

    return prev;
}', '{"debug_hint": "The current node is lost before its pointer is changed. Use a next temporary pointer to retain the unreversed chain.", "problem": "Reverse a singly linked list."}'::jsonb, 'Medium', 10.0, 300, 1, 'Active', '2026-09-14 16:37:35.695115', '2026-09-14 16:37:35.695115') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (386, 25, 77, 'debugging', 'D37: Search Linked List', 'Problem Statement:
Search for a value in a linked list.

Debug Hint:
Identify the comparison error. Assignment (=) overwrites the node data and always evaluates truthy.', '#include <stdio.h>

struct Node {
    int data;
    struct Node *next;
};

int search(struct Node *head, int key) {
    while (head != NULL) {
        if (head->data = key)
            return 1;

        head = head->next;
    }

    return 0;
}', '{"debug_hint": "Identify the comparison error. Assignment (=) overwrites the node data and always evaluates truthy.", "problem": "Search for a value in a linked list."}'::jsonb, 'Medium', 10.0, 300, 1, 'Active', '2026-09-14 16:37:35.695115', '2026-09-14 16:37:35.695115') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (387, 25, 77, 'debugging', 'D38: Insert at End', 'Problem Statement:
Insert a new node at the end of a linked list.

Debug Hint:
The new node is not actually attached to the list. Assign temp->next = newNode rather than overwriting temp.', '#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node *next;
};

struct Node* insertEnd(struct Node *head, int value) {
    struct Node *newNode = malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->next = NULL;

    struct Node *temp = head;

    while (temp->next != NULL)
        temp = temp->next;

    temp = newNode;

    return head;
}', '{"debug_hint": "The new node is not actually attached to the list. Assign temp->next = newNode rather than overwriting temp.", "problem": "Insert a new node at the end of a linked list."}'::jsonb, 'Medium', 10.0, 300, 1, 'Active', '2026-09-14 16:37:35.701012', '2026-09-14 16:37:35.701012') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (388, 25, 77, 'debugging', 'D39: Find Middle Node', 'Problem Statement:
Find the middle node using slow and fast pointers.

Debug Hint:
The fast pointer does not move at the required speed. Advance fast by two steps: fast = fast->next->next.', '#include <stdio.h>

struct Node {
    int data;
    struct Node *next;
};

struct Node* findMiddle(struct Node *head) {
    struct Node *slow = head;
    struct Node *fast = head;

    while (fast != NULL) {
        slow = slow->next;
        fast = fast->next;
    }

    return slow;
}', '{"debug_hint": "The fast pointer does not move at the required speed. Advance fast by two steps: fast = fast->next->next.", "problem": "Find the middle node using slow and fast pointers."}'::jsonb, 'Medium', 10.0, 300, 1, 'Active', '2026-09-14 16:37:35.701012', '2026-09-14 16:37:35.701012') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (389, 25, 77, 'debugging', 'D40: Detect Cycle', 'Problem Statement:
Detect whether a linked list contains a cycle.

Debug Hint:
The algorithm is close to correct. Floyd''s cycle detector requires fast to advance by two nodes each iteration.', '#include <stdio.h>

struct Node {
    int data;
    struct Node *next;
};

int hasCycle(struct Node *head) {
    struct Node *slow = head;
    struct Node *fast = head;

    while (fast != NULL && fast->next != NULL) {
        slow = slow->next;
        fast = fast->next;

        if (slow == fast)
            return 1;
    }

    return 0;
}', '{"debug_hint": "The algorithm is close to correct. Floyd''s cycle detector requires fast to advance by two nodes each iteration.", "problem": "Detect whether a linked list contains a cycle."}'::jsonb, 'Medium', 10.0, 300, 1, 'Active', '2026-09-14 16:37:35.701012', '2026-09-14 16:37:35.701012') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (390, 25, 77, 'debugging', 'D41: Stack Push', 'Problem Statement:
Implement push() for an array-based stack.

Debug Hint:
Identify both the overflow condition and indexing problem. Overflow occurs at top == SIZE - 1, and pre-increment stack[++top] is needed.', '#include <stdio.h>

#define SIZE 5

int stack[SIZE];
int top = -1;

void push(int value) {
    if (top == SIZE)
        printf("Stack Overflow");
    else
        stack[top++] = value;
}', '{"debug_hint": "Identify both the overflow condition and indexing problem. Overflow occurs at top == SIZE - 1, and pre-increment stack[++top] is needed.", "problem": "Implement push() for an array-based stack."}'::jsonb, 'Medium', 10.0, 300, 1, 'Active', '2026-09-14 16:37:35.711329', '2026-09-14 16:37:35.711329') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (391, 25, 77, 'debugging', 'D42: Stack Pop', 'Problem Statement:
Remove and return the top element.

Debug Hint:
Check stack indexing and decrement semantics to ensure the current valid top element is accessed before decrementing.', '#include <stdio.h>

#define SIZE 5

int stack[SIZE];
int top = -1;

int pop() {
    if (top == -1)
        return -1;

    return stack[top--];
}', '{"debug_hint": "Check stack indexing and decrement semantics to ensure the current valid top element is accessed before decrementing.", "problem": "Remove and return the top element."}'::jsonb, 'Medium', 10.0, 300, 1, 'Active', '2026-09-14 16:37:35.711329', '2026-09-14 16:37:35.711329') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (392, 25, 77, 'debugging', 'D43: Queue Enqueue', 'Problem Statement:
