INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (393, 25, 77, 'debugging', 'D44: Queue Dequeue', 'Problem Statement:
Remove an element from a queue.

Debug Hint:
Analyze whether this implementation correctly handles queue state after repeated operations. Linear queues without index resets become permanently exhausted.', '#include <stdio.h>

#define SIZE 5

int queue[SIZE];
int front = 0;
int rear = 0;

