INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (405, 25, 77, 'debugging', 'D56: Queue Using Linked List', 'Problem Statement:
Implement enqueue for a linked-list queue.

Debug Hint:
The queue uses both front and rear. Update rear to point to the new last node (*rear = newNode).', '#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node *next;
};

void enqueue(struct Node **rear, int value) {
    struct Node *newNode = malloc(sizeof(struct Node));

    newNode->data = value;
    newNode->next = NULL;

    if (*rear == NULL) {
        *rear = newNode;
        return;
    }

    (*rear)->next = newNode;
}', '{"debug_hint": "The queue uses both front and rear. Update rear to point to the new last node (*rear = newNode).", "problem": "Implement enqueue for a linked-list queue."}'::jsonb, 'Hard', 10.0, 300, 1, 'Active', '2026-09-14 16:37:35.753586', '2026-09-14 16:37:35.753586') ON CONFLICT DO NOTHING;
INSERT INTO "assessment_questions" ("id", "round_id", "competency_id", "question_type", "title", "candidate_content", "candidate_code_template", "options_json", "difficulty", "marks", "time_limit_seconds", "version", "status", "created_at", "updated_at") VALUES (406, 25, 77, 'debugging', 'D57: Stack Using Linked List', 'Problem Statement:
Push an element onto a linked-list stack.

Debug Hint:
The program fails when the stack is empty (*top == NULL) and links the wrong direction. Assign newNode->next = *top; *top = newNode.', '#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node *next;
};

void push(struct Node **top, int value) {
    struct Node *newNode = malloc(sizeof(struct Node));

    newNode->data = value;
