INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (9, 9, 'SandboxTestRunner', 'import sys
def binary_search(arr, target):
    l, r = 0, len(arr) - 1
    while l <= r:
        mid = (l + r) // 2
        if arr[mid] == target: return mid
        elif arr[mid] < target: l = mid + 1
        else: r = mid - 1
    return -1

def solve():
    lines = sys.stdin.read().splitlines()
    if not lines: return
    arr = list(map(int, lines[0].split()))
    target = int(lines[1].strip())
    print(binary_search(arr, target))
if __name__ == ''__main__'':
    solve()
', 'import sys
def binary_search(arr, target):
    l, r = 0, len(arr) - 1
    while l <= r:
        mid = (l + r) // 2
        if arr[mid] == target: return mid
        elif arr[mid] < target: l = mid + 1
        else: r = mid - 1
    return -1

def solve():
    lines = sys.stdin.read().splitlines()
    if not lines: return
    arr = list(map(int, lines[0].split()))
    target = int(lines[1].strip())
    print(binary_search(arr, target))
if __name__ == ''__main__'':
    solve()
