INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (203, 203, 'CodeSandbox', NULL, '#include <stdio.h>
#include <stdlib.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) return 0;
    
    int *arr = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }
    
    int min = arr[0];
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] < min) min = arr[i];
        if (arr[i] > max) max = arr[i];
    }
    
    printf("Min: %d, Max: %d", min, max);
    free(arr);
    return 0;
}
