INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (209, 209, 'ExactMatch', '2', 'The three-step XOR swap algorithm exploits the properties `a ^ a = 0` and `a ^ 0 = a` to exchange the values of x and y in-place without auxiliary memory.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (210, 210, 'ExactMatch', '2', 'The outer loop runs n times. The inner while loop doubles j each step until j >= n, executing log2(n) times. The total operations are n * log2(n) = O(n log n).', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (211, 211, 'ExactMatch', '2', 'Alpha''s rate is 6000/3 = 2000 jobs/hr. Beta''s rate is 6000/2 = 3000 jobs/hr. Combined rate is 5000 jobs/hr. Time required = 6000 / 5000 = 1.2 hours = 72 minutes.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (212, 212, 'ExactMatch', '1', 'Concurrent start: max(duration(A), duration(B), duration(C)) = max(3, 5, 4) = 5 min. Task D (2 min) runs after B and C finish. Total minimum duration = 5 + 2 = 7 minutes.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (213, 213, 'ExactMatch', '3', 'Call tree for f(4): f(4) calls f(3) and f(2). f(3) calls f(2) and f(1). f(2) calls f(1) and f(0). Right subtree f(2) calls f(1) and f(0). Total calls = 1 + 2 + 4 + 2 = 9.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (214, 214, 'ExactMatch', '1', 'Each element is pushed to inbox once, popped from inbox once, pushed to outbox once, and popped from outbox once across its entire lifecycle (4 operations). Over 2N operations, total cost is 4N, yielding an amortized cost of O(1) per operation.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (215, 215, 'ExactMatch', '4', 'Probability of cluster failure = all 3 nodes fail simultaneously = 0.10^3 = 0.001. Probability cluster is online = 1 - 0.001 = 0.999 (99.9% availability).', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (216, 216, 'ExactMatch', '1', '!(A || B) == (!A && !B). Here A = is_admin and B = !has_token. Therefore, !(is_admin || !has_token) == !is_admin && !(!has_token) == !is_admin && has_token.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (217, 217, 'ExactMatch', '2', 'Inserted at index 8. Parent is floor(8/2) = index 4 (value 12). Since 4 < 12, swap 4 and 12 (4 is now at index 4). Next parent is floor(4/2) = index 2 (value 8). Since 4 < 8, swap 4 and 8 (4 is now at index 2). Next parent is floor(2/2) = index 1 (value 3). Since 4 > 3, bubble-up terminates. Key 4 is at Index 2.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (218, 218, 'ExactMatch', '2', 'SJF Execution Order: P2 (0-2ms), P3 (2-6ms), P1 (6-12ms). Turnaround Times (Completion - Arrival): P2 = 2ms, P3 = 6ms, P1 = 12ms. Average TAT = (2 + 6 + 12) / 3 = 20 / 3 = 6.67 ms.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (219, 219, 'ExactMatch', '2', 'With a /27 prefix, host bits = 32 - 27 = 5 bits. Total IP addresses = 2^5 = 32. Subtract 2 addresses (1 for Network ID 192.168.10.64 and 1 for Broadcast ID 192.168.10.95). Usable host IPs = 32 - 2 = 30.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (220, 220, 'ExactMatch', '3', '1.8 GB = 1,800 MB = 1,800 * 8 = 14,400 Megabits (Mb). At a transmission rate of 100 Mbps, duration = 14,400 / 100 = 144.0 seconds.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (221, 221, 'ExactMatch', '1', 'On a sorted array, placing one pointer at index 0 (left) and one at N-1 (right) and adjusting based on sum < K or sum > K scans the array in at most N steps with O(1) space.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (222, 222, 'ExactMatch', '2', 'From Premise 2, a subset of memory leak issues are high-severity. From Premise 1, all high-severity bugs block releases. Therefore, that specific subset of memory leaks blocks production releases.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (223, 223, 'ExactMatch', '1', 'Linear probing suffers from primary clustering: when multiple collisions occur in nearby slots, long contiguous runs of occupied slots develop, steadily degrading lookup and insertion times towards O(n).', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (224, 224, 'ExactMatch', '2', 'EMAT = Hit_Ratio * L1_Time + (1 - Hit_Ratio) * (L1_Time + Memory_Time) = 0.90 * 2ns + 0.10 * (2ns + 50ns) = 1.8ns + 0.10 * 52ns = 1.8ns + 5.2ns = 6.8 ns.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (225, 225, 'ExactMatch', '1', '11 in binary is 1011 (bit 0 = 1 -> ''A'', bit 1 = 1 -> ''B'', bit 2 = 0 -> omit ''C'', bit 3 = 1 -> ''D''). The corresponding subset is {''A'', ''B'', ''D''}.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (226, 226, 'ExactMatch', '3', 'Trace: (1) PF [1]; (2) PF [1,2]; (3) PF [1,2,3]; (2) Hit [1,3,2]; (4) PF replace 1 -> [3,2,4]; (1) PF replace 3 -> [2,4,1]; (3) PF replace 2 -> [4,1,3]. Total Page Faults = 6.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (227, 227, 'ExactMatch', '3', 'BDP = Bandwidth * RTT = 10,000,000,000 bits/sec * 0.080 sec = 800,000,000 bits. Converting to Bytes = 800,000,000 / 8 = 100,000,000 Bytes = 100 Megabytes (MB).', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (228, 228, 'ExactMatch', '1', 'For (is_owner || is_admin) && !is_suspended to evaluate to True: (False || True) && !False = True && True = True.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (229, 229, 'ExactMatch', '2', 'For N nodes, minimum height h = floor(log2(N)). Since 2^9 = 512 and 2^10 = 1024, floor(log2(1000)) = 9.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (230, 230, 'ExactMatch', '3', 'Original bits per char = 8 bits. Compressed bits per char = 3.2 bits. Space saved per char = 8 - 3.2 = 4.8 bits. Space savings percentage = (4.8 / 8.0) * 100% = 60%.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:08:34.388025', '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (231, 231, 'ExactMatch', '1', 'B+ Tree leaf nodes are linked sequentially in a doubly-linked list, allowing fast range queries and ordered scans. Hash indices only support exact equality lookups (=, IN) and cannot accelerate range filters.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (232, 232, 'ExactMatch', '1', 'WAL guarantees that log records describing data mutations are flushed to disk sequentially before the corresponding modified table pages are written (fsynced). Upon unexpected crash, the engine replays the WAL (REDO/UNDO) to restore consistency.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (233, 233, 'ExactMatch', '2', 'In READ COMMITTED, each query in a transaction reads the latest committed snapshot. If another transaction commits an update between two SELECTs, the same row yields different values (Non-Repeatable Read). REPEATABLE READ holds a snapshot created at transaction start.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (234, 234, 'ExactMatch', '1', 'Connection leak occurs when application threads acquire database connections from the pool but fail to close/return them (e.g. unhandled exceptions bypass conn.close()). The pool becomes exhausted while the database server itself remains idle.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (235, 235, 'ExactMatch', '1', 'Horizontal partitioning splits a table into multiple sub-tables within the same database instance. Sharding is a shared-nothing architecture that distributes partitioned chunks across independent physical database servers.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (236, 236, 'ExactMatch', '1', 'A Mutex has the concept of thread ownership (only the thread that locked the mutex is permitted to unlock it). Semaphores are signaling mechanisms without ownership (any thread can signal/post to increment the semaphore count).', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (237, 237, 'ExactMatch', '1', 'CAS instructions (e.g. cmpxchg on x86) compare the contents of a memory location to an expected value and, if matching, modify it to a new value as an atomic CPU hardware operation. If another thread intervened, the CAS fails and retries without context switching.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (238, 238, 'ExactMatch', '1', 'Context switching requires saving Thread A''s state (registers, stack pointer, PC) into its PCB/TCB and loading Thread B''s state. In addition, indirect overhead occurs due to CPU cache misses and TLB churn for the new execution context.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (239, 239, 'ExactMatch', '1', 'On a TLB miss, the MMU/hardware page table walker traverses the multi-level page tables in physical RAM (CR3 register on x86) to find the Page Table Entry (PTE). If the page is present in RAM, the TLB is loaded; if not present, a Page Fault exception is raised to the OS.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (240, 240, 'ExactMatch', '1', 'Deadlock is a circular wait state where every thread in the set is blocked waiting for a resource held by another. Starvation occurs when runnable threads are perpetually denied access to resources (e.g. greedy high-priority threads always preempting low-priority threads).', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (241, 241, 'ExactMatch', '1', 'TLS 1.3 combines key exchange (Diffie-Hellman parameters) directly into the ClientHello message, completing the cryptographic handshake in 1-RTT (and supporting 0-RTT early data on session resumption), saving 1 full round trip over TLS 1.2''s 2-RTTs.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (242, 242, 'ExactMatch', '1', 'The standard TCP 3-way handshake begins with the client sending a SYN packet with an initial sequence number (ISN). The server responds with SYN-ACK (acknowledging client ISN and providing server ISN). The client replies with ACK, completing connection setup.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (243, 243, 'ExactMatch', '1', 'A CORS preflight OPTIONS request is triggered whenever a cross-origin request is ''non-simple''—such as using HTTP methods other than GET/HEAD/POST, using Content-Type other than text/plain, form-urlencoded, or multipart/form-data (e.g. application/json), or including custom headers (e.g. Authorization).', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (244, 244, 'ExactMatch', '1', 'A recursive resolver handles the full lookup on behalf of the client. It queries root nameservers (for .com), TLD nameservers (for example.com), and authoritative nameservers (for api.example.com) iteratively, caches the answer based on TTL, and returns the result to the client.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (245, 245, 'ExactMatch', '1', 'HTTP/2 multiplexes multiple streams over a single TCP connection; however, if a single TCP packet is dropped, all streams stall (TCP Head-of-Line blocking). HTTP/3 uses QUIC over UDP, ensuring packet loss in one stream does not block unrelated concurrent streams.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (246, 246, 'ExactMatch', '1', 'LSP states that objects of a superclass should be replaceable with objects of its subclasses without breaking program correctness. If client code expecting a Rectangle sets width=5 and height=10 (expecting area=50), passing a Square will violate this invariant (yielding area=25 or 100).', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
