INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (248, 248, 'ExactMatch', '1', 'The Observer pattern establishes a one-to-many dependency between objects so that when one object changes state, all its dependents are notified automatically. The Subject only depends on the Observer interface, achieving clean architectural decoupling.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
