INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (257, 257, 'ExactMatch', '1', 'In Cache-Aside (Lazy-Loading), the application manages caching explicitly: it requests data from cache first; if absent (cache miss), it fetches data from database, writes data into cache for subsequent queries, and returns it to caller.', '[]'::jsonb, '[]'::jsonb, '{"award_full": 2.0, "penalty_wrong": 0.0}'::jsonb, '2026-09-06 03:19:07.924513', '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (258, 258, 'SandboxTestRunner', 'import sys
from collections import defaultdict

def has_cycle(num_nodes, edges):
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
    
    # 0 = unvisited, 1 = visiting (in current DFS stack), 2 = fully visited
    state = [0] * num_nodes
    
    def dfs(node):
        if state[node] == 1:
            return True # Cycle detected
        if state[node] == 2:
            return False
        
        state[node] = 1
        for neighbor in adj[node]:
            if dfs(neighbor):
                return True
        state[node] = 2
        return False

    for i in range(num_nodes):
        if state[i] == 0:
            if dfs(i):
                return True
    return False

def main():
    lines = sys.stdin.read().strip().splitlines()
    if not lines:
        return
    n, m = map(int, lines[0].split())
    edges = []
    for line in lines[1:m+1]:
        u, v = map(int, line.split())
        edges.append((u, v))
    print("true" if has_cycle(n, edges) else "false")

if __name__ == ''__main__'':
    main()
