INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (259, 259, 'SandboxTestRunner', 'import sys
from collections import deque

def max_sliding_window(nums, k):
    if not nums or k <= 0:
        return []
    dq = deque()
    res = []
    
    for i in range(len(nums)):
        # Correctly evict elements outside the current window [i - k + 1, i]
        if dq and dq[0] <= i - k:
            dq.popleft()
            
        while dq and nums[dq[-1]] < nums[i]:
            dq.pop()
            
        dq.append(i)
        
        # First valid window completes at index k - 1
        if i >= k - 1:
            res.append(nums[dq[0]])
            
    return res

def main():
    lines = sys.stdin.read().strip().splitlines()
    if not lines:
        return
    k = int(lines[0].strip())
    nums = list(map(int, lines[1].split()))
    result = max_sliding_window(nums, k)
    print(" ".join(map(str, result)))

if __name__ == ''__main__'':
    main()
