long long reverseInteger(int n) {
    long long rev = 0;
    int sign = (n < 0) ? -1 : 1;
    long long num = (n < 0) ? -(long long)n : n;
    
    while (num > 0) {
        rev = rev * 10 + (num % 10);
        num /= 10;
    }
    return rev * sign;
}

int main() {
    int n;
    if (scanf("%d", &n) == 1) {
        printf("%lld\n", reverseInteger(n));
    }
    return 0;
}
