void printFibonacci(int n) {
    long long a = 0, b = 1;
    for (int i = 0; i < n; i++) {
        if (i == 0) {
            printf("%lld", a);
        } else if (i == 1) {
            printf(" %lld", b);
        } else {
            long long c = a + b;
            printf(" %lld", c);
            a = b;
            b = c;
        }
    }
    printf("\n");
}

int main() {
    int n;
    if (scanf("%d", &n) == 1 && n > 0) {
        printFibonacci(n);
    }
    return 0;
}
