bool isPalindrome(const char *str) {
    int left = 0;
    int right = strlen(str) - 1;
    while (left < right) {
        if (str[left] != str[right]) return false;
        left++;
        right--;
    }
    return true;
}

int main() {
    char str[1000];
    if (scanf("%s", str) == 1) {
        if (isPalindrome(str)) printf("Palindrome\n");
        else printf("Not Palindrome\n");
    }
    return 0;
}
