#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* insertHead(Node* head, int val) {
    Node* n = (Node*)malloc(sizeof(Node));
    n->data = val;
    n->next = head;
    return n;
}

Node* insertTail(Node* head, int val) {
    Node* n = (Node*)malloc(sizeof(Node));
    n->data = val;
    n->next = NULL;
    if (!head) return n;
    Node* curr = head;
    while (curr->next) curr = curr->next;
    curr->next = n;
    return head;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    Node* head = NULL;
    for (int i = 0; i < n; i++) {
        int v; scanf("%d", &v);
        head = insertTail(head, v);
    }
    int x, y;
    if (scanf("%d %d", &x, &y) == 2) {
        head = insertHead(head, x);
        head = insertTail(head, y);
    }
    Node* curr = head;
    while (curr) {
        printf("%d -> ", curr->data);
        curr = curr->next;
    }
    printf("NULL\n");
    return 0;
}
