#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* deleteNode(Node* head, int val) {
    if (!head) return NULL;
    if (head->data == val) {
        Node* next = head->next;
        free(head);
        return next;
    }
    Node* curr = head;
    while (curr->next && curr->next->data != val) curr = curr->next;
    if (curr->next) {
        Node* temp = curr->next;
        curr->next = curr->next->next;
        free(temp);
    }
    return head;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    Node* head = NULL, *tail = NULL;
    for (int i = 0; i < n; i++) {
        int v; scanf("%d", &v);
        Node* node = (Node*)malloc(sizeof(Node));
        node->data = v; node->next = NULL;
        if (!head) head = tail = node;
        else { tail->next = node; tail = node; }
    }
    int target;
    scanf("%d", &target);
    head = deleteNode(head, target);
    Node* curr = head;
    while (curr) {
        printf("%d -> ", curr->data);
        curr = curr->next;
    }
    printf("NULL\n");
    return 0;
}
