    Node *fast = head, *slow = head;
    for (int i = 0; i < k; i++) {
        if (!fast) return -1;
        fast = fast->next;
    }
    while (fast) {
        slow = slow->next;
        fast = fast->next;
    }
    return slow ? slow->data : -1;
}

