INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (336, 336, 'AIEvaluation', NULL, '#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* reverseList(Node* head) {
    Node *prev = NULL, *curr = head;
    while (curr) {
        Node* nxt = curr->next;
        curr->next = prev;
        prev = curr;
        curr = nxt;
    }
    return prev;
}

bool isPalindrome(Node* head) {
    if (!head || !head->next) return true;
    Node *slow = head, *fast = head;
    while (fast->next && fast->next->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    Node* second = reverseList(slow->next);
    Node* first = head;
    while (second) {
        if (first->data != second->data) return false;
        first = first->next;
        second = second->next;
    }
    return true;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    Node *head = NULL, *tail = NULL;
    for (int i = 0; i < n; i++) {
        int v; scanf("%d", &v);
        Node* node = (Node*)malloc(sizeof(Node));
        node->data = v; node->next = NULL;
        if (!head) head = tail = node; else { tail->next = node; tail = node; }
    }
    if (isPalindrome(head)) printf("Palindrome\n");
    else printf("Not Palindrome\n");
    return 0;
}
