INSERT INTO "question_evaluation_configs" ("id", "question_id", "evaluation_type", "correct_answer", "reference_solution", "public_test_cases_json", "hidden_test_cases_json", "scoring_rules_json", "created_at", "updated_at") VALUES (349, 349, 'AIEvaluation', NULL, '#include <stdio.h>
#include <stdlib.h>

typedef struct DNode {
    int key, val;
    struct DNode *prev, *next;
} DNode;

int cap, size = 0;
DNode *head = NULL, *tail = NULL;
DNode* map[10001] = {NULL};

void moveToHead(DNode* n) {
    if (n == head) return;
    if (n->prev) n->prev->next = n->next;
    if (n->next) n->next->prev = n->prev;
    if (n == tail) tail = n->prev;
    n->next = head;
    n->prev = NULL;
    if (head) head->prev = n;
    head = n;
    if (!tail) tail = head;
}

void put(int k, int v) {
    if (map[k]) {
        map[k]->val = v;
        moveToHead(map[k]);
        return;
    }
    if (size == cap) {
        map[tail->key] = NULL;
        DNode* rem = tail;
        tail = tail->prev;
        if (tail) tail->next = NULL;
        else head = NULL;
        free(rem);
        size--;
    }
    DNode* n = (DNode*)malloc(sizeof(DNode));
    n->key = k; n->val = v; n->prev = NULL; n->next = head;
    if (head) head->prev = n;
    head = n;
    if (!tail) tail = head;
    map[k] = n;
    size++;
}

int get(int k) {
    if (!map[k]) return -1;
    moveToHead(map[k]);
    return map[k]->val;
}

int main() {
    int q;
    if (scanf("%d %d", &cap, &q) != 2) return 0;
    int first = 1;
    while (q--) {
        int t; scanf("%d", &t);
        if (t == 1) {
            int k, v; scanf("%d %d", &k, &v);
            put(k, v);
        } else if (t == 2) {
            int k; scanf("%d", &k);
            if (!first) printf(" ");
            printf("%d", get(k));
            first = 0;
        }
    }
    printf("\n");
    return 0;
}
