INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (4, 4, 1, '{"title": "Two Sum Target Indices", "content": "### Problem Statement\nGiven an array of integers `nums` and an integer `target`, return the 0-based indices of the two numbers such that they add up to `target`.\n\nYou may assume that each input will have exactly one solution, and you may not use the same element twice.\n\n### Input Format\n- Line 1: Space-separated integers representing `nums`\n- Line 2: Single integer representing `target`\n\n### Output Format\n- Space-separated indices in ascending order (e.g. `0 1`)\n\n### Constraints\n- $2 \\le \text{nums.length} \\le 10^5$\n- $-10^9 \\le \text{nums}[i] \\le 10^9$\n- Time Limit: 2.0 seconds\n"}'::jsonb, '2026-08-20 13:59:34.129651') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (5, 5, 1, '{"title": "Valid Anagram Checker", "content": "### Problem Statement\nGiven two strings `s` and `t`, return `true` if `t` is an anagram of `s`, and `false` otherwise.\nAn anagram is a word or phrase formed by rearranging the letters of a different word or phrase, using all the original letters exactly once.\n\n### Input Format\n- Line 1: String `s`\n- Line 2: String `t`\n\n### Output Format\n- Print `true` or `false` (lowercase).\n"}'::jsonb, '2026-08-20 13:59:34.139498') ON CONFLICT DO NOTHING;
