INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (35, 35, 1, '{"title": "R1-Q26: Post-Sales Support Typing Benchmark", "content": "Thank you for contacting customer support today. I understand that your recent shipment has not arrived as scheduled, and I sincerely apologize for the inconvenience this delay has caused. I am currently reviewing your order details, tracking information, and warehouse logs to locate your package. Please rest assured that our priority is ensuring you receive your items safely and promptly. If the package cannot be located within twenty-four hours, we will be glad to arrange an expedited replacement or process a full refund to your original payment method."}'::jsonb, '2026-08-20 13:59:34.441981') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (36, 36, 1, '{"title": "R2-Case01: Scenario 1: Delayed International Delivery (US to Canada)", "content": "Customer: David Miller (Toronto, Canada)\nOrder: #US-8492 ($189.00 - Express 2-Day Shipping)\nStatus: Shipped 5 days ago, stuck in customs clearance.\nCustomer Message: ''I paid $35 extra for Express 2-day delivery because this was a birthday gift for my daughter yesterday. It has been 5 days and nobody is updating me. This is unacceptable!''\n\nWhat is the best immediate response?"}'::jsonb, '2026-08-20 13:59:34.460360') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (37, 37, 1, '{"title": "R2-Case02: Scenario 2: Duplicate Credit Card Charge", "content": "Customer: Sarah Jenkins (Chicago, USA)\nAccount: Verified ($450.00 Order)\nCustomer Message: ''My online bank statement shows two pending charges of $450.00 from your store today. You charged me $900 for a single order! Fix this immediately or I am filing a bank dispute!''\n\nWhat is the most accurate and reassuring resolution?"}'::jsonb, '2026-08-20 13:59:34.466806') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (38, 38, 1, '{"title": "R2-Case03: Scenario 3: Damaged Goods Received", "content": "Customer: Michael Chang (Seattle, USA)\nOrder: #US-9912 (Ceramic Cookware Set - $240.00)\nCustomer Message: ''The box arrived crushed and two of the ceramic pots are completely shattered. I need this for a dinner party this Friday.''\n\nWhat is the correct protocol?"}'::jsonb, '2026-08-20 13:59:34.469868') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (39, 39, 1, '{"title": "R2-Case04: Scenario 4: Out of Policy Refund Demand with Review Threat", "content": "Customer: Robert Taylor (Miami, USA)\nOrder: #US-7011 (Leather Jacket - Purchased 65 days ago, Return Policy is 30 days)\nCustomer Message: ''I wore this twice and don''t like the fit. Give me a full refund to my card now, or I will post 1-star reviews on Trustpilot, Reddit, and Twitter with screenshots of your awful service!''\n\nHow should you handle this situation professionally?"}'::jsonb, '2026-08-20 13:59:34.479677') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (40, 40, 1, '{"title": "R2-Case05: Scenario 5: Supervisor Escalation Request", "content": "Customer: Amanda White (Boston, USA)\nCustomer Message: ''I have been transferred three times already and nobody knows what they are doing. Transfer me to your supervisor right now, I refuse to talk to front-line agents!''\n\nWhat is the best de-escalation response before initiating supervisor transfer?"}'::jsonb, '2026-08-20 13:59:34.479677') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (41, 41, 1, '{"title": "R2-Case06: Scenario 6: Incorrect Item Received (Wrong Color/Model)", "content": "Customer: James Wilson (Vancouver, Canada)\nOrder: #CA-3301 (Ordered: Matte Black Headphones / Received: Neon Green)\nCustomer Message: ''I opened the box and received neon green headphones instead of matte black. How does your warehouse mess up something so simple?''\n\nWhat is the appropriate customer resolution?"}'::jsonb, '2026-08-20 13:59:34.489802') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (42, 42, 1, '{"title": "R2-Case07: Scenario 7: Defective Product under Warranty", "content": "Customer: Lisa Brown (Austin, USA)\nOrder: #US-6102 (Electric Espresso Machine - Purchased 5 months ago, 1-Year Warranty)\nCustomer Message: ''The pressure pump stopped working this morning and water is leaking from the base. I need a replacement machine.''\n\nWhat is the correct protocol?"}'::jsonb, '2026-08-20 13:59:34.492406') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (43, 43, 1, '{"title": "R2-Case08: Scenario 8: Cancellation Request on Shipped Order", "content": "Customer: Kevin Harris (Dallas, USA)\nOrder: #US-8820 ($320.00 Gaming Chair)\nStatus: Shipped via UPS 2 hours ago (Tracking generated)\nCustomer Message: ''I changed my mind 10 minutes ago. Cancel this order immediately and refund my card before it ships!''\n\nHow should you handle an order that has already been dispatched?"}'::jsonb, '2026-08-20 13:59:34.499764') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (44, 44, 1, '{"title": "R2-Case09: Scenario 9: Unrecognized Account Login / Security Alert", "content": "Customer: Rachel Adams (New York, USA)\nCustomer Message: ''I got an email saying someone logged into my account from Russia and placed an order for $800 gift cards! Cancel that order and lock my account!''\n\nWhat is the immediate security protocol?"}'::jsonb, '2026-08-20 13:59:34.509871') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (45, 45, 1, '{"title": "R2-Case10: Scenario 10: Aggressive Customer Using Profanity", "content": "Customer: John Doe (Philadelphia, USA)\nCustomer Message: ''Your f***ing software crashed and ruined my work presentation. You guys are complete idiots and thieves!''\n\nHow should an international chat agent handle abusive language while de-escalating?"}'::jsonb, '2026-08-20 13:59:34.509871') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (46, 46, 1, '{"title": "R2-Case11: Scenario 11: International Customer with Language Barrier", "content": "Customer: Jean-Pierre (Montreal, Canada)\nCustomer Message: ''Bonjour, package no arrive. tracking say delivered but no package in my porte. please aidez moi.''\n\nHow do you respond with clear, simple, and supportive language?"}'::jsonb, '2026-08-20 13:59:34.519740') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (47, 47, 1, '{"title": "R2-Case12: Scenario 12: High-Value Customer VIP Retention", "content": "Customer: Victoria Sterling (San Francisco, USA)\nCustomer Status: Platinum Tier (50+ orders, $8,000 annual spend)\nCustomer Message: ''I have been a loyal customer for 4 years, but my anniversary promo code is saying invalid at checkout. If your system won''t honor my loyalty reward, I will take my business elsewhere.''\n\nWhat is the empowered resolution?"}'::jsonb, '2026-08-20 13:59:34.529628') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (48, 48, 1, '{"title": "R3-SOP01: SOP Case 1: Return Window Eligibility (Electronics)", "content": "SOP Reference: KB-RET-01 (Return Windows)\nPolicy: Consumer electronics are eligible for return within 30 days of delivery. Returns requested between 31-45 days are eligible for Store Credit only. Returns after 45 days are strictly ineligible.\n\nCase Details:\nCustomer purchased a DSLR camera delivered 38 days ago. Item is in original packaging.\n\nWhat is the compliant resolution and required documentation?"}'::jsonb, '2026-08-20 13:59:34.542774') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (49, 49, 1, '{"title": "R3-SOP02: SOP Case 2: Lost in Transit (Package Investigation Window)", "content": "SOP Reference: KB-LOG-04 (Lost in Transit Claims)\nPolicy: If carrier tracking shows no movement for 5 consecutive business days, agent is authorized to declare package Lost-in-Transit (LIT) and trigger immediate replacement or refund. If under 5 days, customer must be advised to allow 48 hours for carrier updates.\n\nCase Details:\nCustomer tracking has had zero scan updates for 7 consecutive days.\n\nWhat is the compliant SOP action?"}'::jsonb, '2026-08-20 13:59:34.552868') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (50, 50, 1, '{"title": "R3-SOP03: SOP Case 3: Identity Verification before Disclosing Account Data", "content": "SOP Reference: KB-SEC-02 (Customer Authentication Protocol)\nPolicy: Before sharing order history, updating shipping addresses, or discussing financial details, agent MUST verify 2 account credentials: 1) Full Name on account, and 2) Either Order Number or Billing Zip Code. Never ask for Passwords or CVV.\n\nCase Details:\nA chat user asks to change the shipping address on Order #8849. User provides only first name ''John''.\n\nWhat is the required SOP verification?"}'::jsonb, '2026-08-20 13:59:34.560464') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (88, 88, 1, '{"title": "Q3.4: Pandas Missing Data Imputation Strategies", "content": "A DataFrame `df` has missing numeric values in column `''score''`. Which Pandas code fills missing values with the column mean inplace?"}'::jsonb, '2026-08-20 13:59:34.919543') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (51, 51, 1, '{"title": "R3-SOP04: SOP Case 4: High-Value Refund Approval Matrix ($500+)", "content": "SOP Reference: KB-REF-03 (Refund Authorization Levels)\nPolicy: Tier-1 Chat Agents can authorize refunds up to $250.00 independently. Refunds between $250.01 - $500.00 require Senior Agent approval. Refunds above $500.00 require Tier-2 Supervisor approval and photo proof of return receipt.\n\nCase Details:\nCustomer requests refund of $680.00 for returned laptop.\n\nWhat is the mandatory escalation protocol?"}'::jsonb, '2026-08-20 13:59:34.566208') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (52, 52, 1, '{"title": "R3-SOP05: SOP Case 5: Warranty Defect vs Accidental Damage", "content": "SOP Reference: KB-WAR-01 (Warranty Scope)\nPolicy: Manufacturer warranty covers internal hardware malfunctions, component failures, and factory defects. It excludes cosmetic damage, water immersion, cracked screens from drops, and unauthorized modifications.\n\nCase Details:\nCustomer states: ''My tablet slipped out of my hand on the driveway and the screen is cracked.''\n\nWhat is the correct policy determination?"}'::jsonb, '2026-08-20 13:59:34.576045') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (53, 53, 1, '{"title": "R3-SOP06: SOP Case 6: Price Match Policy Within 14 Days", "content": "SOP Reference: KB-BIL-02 (Price Protection)\nPolicy: Customers are eligible for a price match refund if the identical product is discounted on our store within 14 days of purchase. Excludes clearance items and third-party marketplace sellers.\n\nCase Details:\nCustomer purchased jacket for $120.00 8 days ago. Today our official store price is $90.00.\n\nWhat is the action and refund calculation?"}'::jsonb, '2026-08-20 13:59:34.583699') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (54, 54, 1, '{"title": "R3-SOP07: SOP Case 7: Fraud Alert - Stolen Card Claim", "content": "SOP Reference: KB-SEC-05 (Fraud Protocol)\nPolicy: If a contact claims their credit card was used fraudulently on our site without authorization, agent MUST: 1) Immediately cancel unshipped orders, 2) Freeze account, 3) Escalate to Trust & Safety team. Never argue or disclose fraudster''s shipping address to the caller.\n\nCase Details:\nCaller states: ''Someone made a $400 charge on my Visa card at your store.''\n\nWhat is the compliant protocol?"}'::jsonb, '2026-08-20 13:59:34.589593') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (55, 55, 1, '{"title": "R3-SOP08: SOP Case 8: Hazardous Material / Battery Return Policy", "content": "SOP Reference: KB-RET-04 (Hazardous Materials)\nPolicy: Lithium-ion batteries that are swollen, punctured, or leaking CANNOT be shipped via standard postal returns due to federal air transport safety regulations. Customer must dispose safely locally; agent issues direct replacement/refund upon photo confirmation.\n\nCase Details:\nCustomer reports laptop battery is swollen and bulging out of the case.\n\nWhat is the compliant safety action?"}'::jsonb, '2026-08-20 13:59:34.592688') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (56, 56, 1, '{"title": "R3-SOP09: SOP Case 9: Restocking Fee Exemptions", "content": "SOP Reference: KB-RET-05 (Restocking Fees)\nPolicy: Standard discretionary returns incur a 15% restocking fee. Restocking fees are 100% WAIVED if: 1) Item is defective, 2) Wrong item sent by warehouse, or 3) Customer is Platinum VIP member.\n\nCase Details:\nPlatinum VIP customer returns an unopened monitor because they changed their mind.\n\nIs a restocking fee charged?"}'::jsonb, '2026-08-20 13:59:34.601466') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (57, 57, 1, '{"title": "R3-SOP10: SOP Case 10: Address Correction After Dispatch", "content": "SOP Reference: KB-LOG-02 (In-Transit Address Modifications)\nPolicy: Address modifications cannot be made directly in warehouse system once carrier has received shipment. Agent must submit carrier package redirect request ($10 fee charged by carrier, waived if error was warehouse fault).\n\nCase Details:\nCustomer entered wrong street number during checkout and package is on delivery truck.\n\nWhat is the SOP action?"}'::jsonb, '2026-08-20 13:59:34.611848') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (58, 58, 1, '{"title": "R3-SOP11: SOP Case 11: International Duty & Customs Taxes", "content": "SOP Reference: KB-INT-01 (Customs & Import Duties)\nPolicy: For DDP (Delivered Duty Paid) shipping, our store pays all customs taxes upfront. If local carrier mistakenly demands payment from customer upon delivery, agent verifies receipt and reimburses customer immediately.\n\nCase Details:\nCanadian customer with DDP shipping was charged $28 CAD import tax by DHL courier.\n\nWhat is the correct resolution?"}'::jsonb, '2026-08-20 13:59:34.611848') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (59, 59, 1, '{"title": "R3-SOP12: SOP Case 12: Partial Order Fulfillment Notification", "content": "SOP Reference: KB-ORD-03 (Split Shipments)\nPolicy: When multi-item orders ship from different regional warehouses, each shipment has an independent tracking number. Agent must look up all fulfillment child-IDs before declaring items missing.\n\nCase Details:\nCustomer ordered a keyboard and mouse. Received only keyboard and claims mouse is missing.\n\nWhat investigation step is required?"}'::jsonb, '2026-08-20 13:59:34.624937') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (60, 60, 1, '{"title": "R3-SOP13: SOP Case 13: Chargeback Dispute Notification", "content": "SOP Reference: KB-BIL-06 (Active Bank Disputes)\nPolicy: When a customer files a formal chargeback with their bank, the account enters legal dispute status. Agents CANNOT process manual refunds or exchanges in chat while dispute is active, as bank holds the funds. Must route to Dispute Management.\n\nCase Details:\nCustomer states: ''I filed a chargeback with Chase Bank yesterday, but give me my money now.''\n\nWhat is the required SOP handling?"}'::jsonb, '2026-08-20 13:59:34.629481') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (61, 61, 1, '{"title": "R3-SOP14: SOP Case 14: Subscription Cancellation and Prorated Refunds", "content": "SOP Reference: KB-SUB-02 (SaaS/Software Subscription Policy)\nPolicy: Annual software subscriptions cancelled within first 14 days receive 100% refund. Cancellations between 15-90 days receive prorated refund for unused months. Cancellations after 90 days cancel future auto-renewals only with no refund.\n\nCase Details:\nCustomer cancels annual subscription on day 45 of 365.\n\nWhat is the correct refund entitlement?"}'::jsonb, '2026-08-20 13:59:34.632768') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (62, 62, 1, '{"title": "R3-SOP15: SOP Case 15: Escalation Matrix - Priority 1 System Outage", "content": "SOP Reference: KB-ESC-01 (Severity Classification)\nPolicy: Severity 1 (Critical) is reserved for system-wide outages affecting checkout, multiple user data corruption, or payment gateway crash. Must alert On-Call Engineering within 5 minutes with incident ticket.\n\nCase Details:\nMultiple customers simultaneously report credit card checkout throwing ''502 Gateway Error''.\n\nWhat is the correct escalation tier and SLA?"}'::jsonb, '2026-08-20 13:59:34.644909') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (83, 83, 1, '{"title": "Filter Employees Above Threshold in Pandas", "content": "Write or select the correct Python Pandas snippet `filter_high_earners(df, threshold)` that accepts a Pandas DataFrame `df` with columns `[''name'', ''salary'']` and returns a list of employee names earning strictly greater than `threshold`."}'::jsonb, '2026-08-20 13:59:34.879725') ON CONFLICT DO NOTHING;
