INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (63, 63, 1, '{"title": "R4-SIM: Production Multi-Chat Support Console", "content": "[{\"session_id\": \"CHAT-A\", \"customer_name\": \"Jessica Miller\", \"market\": \"USA (Chicago, IL)\", \"order_id\": \"#US-94821\", \"order_amount\": \"$289.00\", \"initial_state\": \"ACTIVE\", \"priority\": \"HIGH\", \"issue_category\": \"DELIVERY\", \"sla_first_response_sec\": 60, \"sla_resolution_min\": 12, \"timeline\": [{\"time_sec\": 0, \"sender\": \"customer\", \"message\": \"Hi, my package was supposed to be delivered yesterday for an anniversary gift. Tracking says ''Delayed in Transit''. Can someone please tell me where it is?\"}, {\"time_sec\": 45, \"trigger\": \"if_no_response\", \"message\": \"Hello? Is anyone there? I really need an update.\"}, {\"time_sec\": 120, \"sender\": \"customer\", \"message\": \"I checked with my neighbors and nobody has seen the FedEx truck. Can you check if it''s lost?\"}, {\"time_sec\": 240, \"sender\": \"customer\", \"message\": \"If this can''t arrive by tomorrow, I want to cancel and get a replacement sent to my office address.\"}], \"correct_resolution\": {\"ticket_category\": \"Delivery\", \"priority\": \"High\", \"resolution_code\": \"Replacement Initiated / Lost in Transit\", \"required_kb_search\": \"Lost in Transit\", \"required_internal_note\": \"Package delayed >48h with FedEx. Verified address. Issued replacement with priority overnight.\"}}, {\"session_id\": \"CHAT-B\", \"customer_name\": \"Alexander Hayes\", \"market\": \"Canada (Vancouver, BC)\", \"order_id\": \"#CA-40291\", \"order_amount\": \"$145.50\", \"initial_state\": \"WAITING\", \"priority\": \"URGENT\", \"issue_category\": \"BILLING\", \"sla_first_response_sec\": 45, \"sla_resolution_min\": 10, \"timeline\": [{\"time_sec\": 30, \"sender\": \"customer\", \"message\": \"I was promised a refund of $145.50 last Tuesday by your agent Mark. My credit card statement arrived today and there is NO refund. Why are you holding my money?\"}, {\"time_sec\": 90, \"sender\": \"customer\", \"message\": \"I have the chat transcript from Mark saying it would take 3 business days. It has been 6 business days!\"}, {\"time_sec\": 180, \"sender\": \"customer\", \"message\": \"Give me the ARN refund reference number so I can give it to my bank.\"}], \"correct_resolution\": {\"ticket_category\": \"Billing / Refund\", \"priority\": \"Critical\", \"resolution_code\": \"Refund Verified / Acquirer Reference Provided\", \"required_kb_search\": \"Refund Pending\", \"required_internal_note\": \"Checked merchant gateway. Refund was processed on Friday. Provided ARN #749281920 to customer. Reassured 3-5 bank processing days.\"}}, {\"session_id\": \"CHAT-C\", \"customer_name\": \"Daniel Kim\", \"market\": \"USA (Austin, TX)\", \"order_id\": \"#US-77182\", \"order_amount\": \"$89.99\", \"initial_state\": \"WAITING\", \"priority\": \"NORMAL\", \"issue_category\": \"WARRANTY\", \"sla_first_response_sec\": 90, \"sla_resolution_min\": 15, \"timeline\": [{\"time_sec\": 60, \"sender\": \"customer\", \"message\": \"Hey there! My wireless earbuds keep disconnecting from Bluetooth every 5 minutes. Bought them 2 months ago.\"}, {\"time_sec\": 180, \"sender\": \"customer\", \"message\": \"I already tried forgetting device and reconnecting. Still drops connection.\"}, {\"time_sec\": 300, \"sender\": \"customer\", \"message\": \"I have the original box and receipt from Best Buy online store.\"}], \"correct_resolution\": {\"ticket_category\": \"Warranty / Hardware\", \"priority\": \"Normal\", \"resolution_code\": \"Warranty Replacement Approved\", \"required_kb_search\": \"Warranty Eligibility\", \"required_internal_note\": \"Bluetooth disconnection unresolved by hardware reset. Unit within 1-year warranty. Generated prepaid RMA label and warranty replacement.\"}}]"}'::jsonb, '2026-08-20 13:59:34.669811') ON CONFLICT DO NOTHING;
