INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (102, 209, 1, '{"id": 209, "round_id": 1, "title": "XOR Swap & Identity Theorem", "candidate_content": "Given two integers `x = 45` and `y = 20`, the three operations `x = x ^ y; y = x ^ y; x = x ^ y;` are executed sequentially. What are the final values of `x` and `y`?", "options_json": [{"id": 1, "text": "x = 45, y = 20"}, {"id": 2, "text": "x = 20, y = 45"}, {"id": 3, "text": "x = 65, y = 25"}, {"id": 4, "text": "x = 0, y = 0"}], "marks": 2.0, "difficulty": "Easy", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 3}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (103, 210, 1, '{"id": 210, "round_id": 1, "title": "Time Complexity of Nested Dependent Loops", "candidate_content": "Consider the following code snippet:\n```python\nfor i in range(1, n + 1):\n    j = 1\n    while j < n:\n        j = j * 2\n```\nWhat is the asymptotic worst-case time complexity of this algorithm in Big-O notation?", "options_json": [{"id": 1, "text": "O(n)"}, {"id": 2, "text": "O(n log n)"}, {"id": 3, "text": "O(n^2)"}, {"id": 4, "text": "O(log n)"}], "marks": 2.0, "difficulty": "Medium", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 4}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (104, 211, 1, '{"id": 211, "round_id": 1, "title": "Microservice Throughput & Work-Rate", "candidate_content": "Server Alpha processes a queue of 6,000 asynchronous jobs in 3 hours. Server Beta processes the same queue of 6,000 jobs in 2 hours. If both servers process the queue concurrently without lock contention, how many minutes will they take to process 6,000 jobs?", "options_json": [{"id": 1, "text": "60 minutes"}, {"id": 2, "text": "72 minutes"}, {"id": 3, "text": "80 minutes"}, {"id": 4, "text": "90 minutes"}], "marks": 2.0, "difficulty": "Medium", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 2}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (105, 212, 1, '{"id": 212, "round_id": 1, "title": "Critical Path & Task Dependency Graph", "candidate_content": "A CI/CD deployment pipeline consists of 4 tasks: A (Linting, 3 min), B (Unit Tests, 5 min), C (Security Scan, 4 min), and D (Deployment, 2 min). Task D strictly requires both B and C to complete. Tasks A, B, and C can run concurrently from start (time 0). What is the minimum duration from start to finish?", "options_json": [{"id": 1, "text": "7 minutes"}, {"id": 2, "text": "9 minutes"}, {"id": 3, "text": "11 minutes"}, {"id": 4, "text": "14 minutes"}], "marks": 2.0, "difficulty": "Easy", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 1}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (106, 213, 1, '{"id": 213, "round_id": 1, "title": "Recursive Call Stack Frame Evaluation", "candidate_content": "Consider the recurrence function `def f(n): return 1 if n <= 1 else f(n - 1) + f(n - 2)`. When evaluating `f(4)` without memoization, what is the total number of function calls (including the initial call) executed?", "options_json": [{"id": 1, "text": "7"}, {"id": 2, "text": "8"}, {"id": 3, "text": "9"}, {"id": 4, "text": "15"}], "marks": 2.0, "difficulty": "Medium", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 3}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (107, 214, 1, '{"id": 214, "round_id": 1, "title": "Queue using Two Stacks Amortized Cost", "candidate_content": "A Queue data structure is implemented using two standard LIFO stacks (`inbox` and `outbox`). For a sequence of `N` `enqueue` operations followed by `N` `dequeue` operations on an initially empty queue, what is the amortized time complexity per individual operation?", "options_json": [{"id": 1, "text": "O(1)"}, {"id": 2, "text": "O(N)"}, {"id": 3, "text": "O(log N)"}, {"id": 4, "text": "O(N log N)"}], "marks": 2.0, "difficulty": "Medium", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 4}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
