INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (109, 216, 1, '{"id": 216, "round_id": 1, "title": "Boolean Circuit Equivalence & Logic Optimization", "candidate_content": "Which of the following Boolean expressions is logically equivalent to `!(is_admin || !has_token)` according to De Morgan''s laws?", "options_json": [{"id": 1, "text": "!is_admin && has_token"}, {"id": 2, "text": "!is_admin || has_token"}, {"id": 3, "text": "is_admin && !has_token"}, {"id": 4, "text": "!is_admin && !has_token"}], "marks": 2.0, "difficulty": "Easy", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 1}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (110, 217, 1, '{"id": 217, "round_id": 1, "title": "Min-Heap Insertion & Parent Node Calculation", "candidate_content": "In a 1-indexed binary min-heap array `[3, 8, 5, 12, 14, 9, 7]`, a new key `4` is inserted at the end of the array (index 8). After executing the standard bubble-up (heapify-up) procedure, at which index will the key `4` reside?", "options_json": [{"id": 1, "text": "Index 1"}, {"id": 2, "text": "Index 2"}, {"id": 3, "text": "Index 4"}, {"id": 4, "text": "Index 8"}], "marks": 2.0, "difficulty": "Medium", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 4}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (111, 218, 1, '{"id": 218, "round_id": 1, "title": "CPU Scheduling Average Turnaround Time (SJF)", "candidate_content": "Three processes arrive at time 0 with burst times: P1 = 6ms, P2 = 2ms, P3 = 4ms. Using non-preemptive Shortest Job First (SJF) scheduling, what is the average Turnaround Time (TAT) of the processes?", "options_json": [{"id": 1, "text": "5.33 ms"}, {"id": 2, "text": "6.67 ms"}, {"id": 3, "text": "8.00 ms"}, {"id": 4, "text": "9.33 ms"}], "marks": 2.0, "difficulty": "Medium", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 9}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (112, 219, 1, '{"id": 219, "round_id": 1, "title": "CIDR IPv4 Subnet Usable Host Capacity", "candidate_content": "A network engineer assigns an IPv4 subnet of `192.168.10.64/27` to a web server cluster. How many usable host IP addresses are available within this subnet for allocation to server network interfaces?", "options_json": [{"id": 1, "text": "28"}, {"id": 2, "text": "30"}, {"id": 3, "text": "32"}, {"id": 4, "text": "62"}], "marks": 2.0, "difficulty": "Easy", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 10}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (113, 220, 1, '{"id": 220, "round_id": 1, "title": "Database Replication Lag & Bandwidth Calculation", "candidate_content": "A database write-ahead log (WAL) of size 1.8 Gigabytes (GB) needs to be replicated over a dedicated 100 Megabits per second (Mbps) network link. Assuming 100% link utilization and no protocol overhead (1 GB = 1,000 MB; 1 Byte = 8 bits), how many seconds will the replication take?", "options_json": [{"id": 1, "text": "14.4 seconds"}, {"id": 2, "text": "18.0 seconds"}, {"id": 3, "text": "144.0 seconds"}, {"id": 4, "text": "180.0 seconds"}], "marks": 2.0, "difficulty": "Medium", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 2}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (114, 221, 1, '{"id": 221, "round_id": 1, "title": "Two-Pointer Traversal Optimization", "candidate_content": "To find whether any two elements in a sorted array of `N` numbers sum to target `K`, which algorithmic pattern achieves $O(N)$ time complexity with $O(1)$ auxiliary space?", "options_json": [{"id": 1, "text": "Two pointers initialized at start and end of array moving inward"}, {"id": 2, "text": "Nested binary search over all elements"}, {"id": 3, "text": "Building an auxiliary hash set"}, {"id": 4, "text": "Prefix sum scanning"}], "marks": 2.0, "difficulty": "Easy", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 3}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (115, 222, 1, '{"id": 222, "round_id": 1, "title": "Deductive Syllogism in Software Testing", "candidate_content": "Given the following premises:\n1. All high-severity bugs block production releases.\n2. Some memory leak issues are high-severity bugs.\nWhich of the following conclusions logically follows with certainty?", "options_json": [{"id": 1, "text": "All memory leak issues block production releases."}, {"id": 2, "text": "Some memory leak issues block production releases."}, {"id": 3, "text": "No low-severity bugs block production releases."}, {"id": 4, "text": "All production releases contain memory leaks."}], "marks": 2.0, "difficulty": "Easy", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 1}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (116, 223, 1, '{"id": 223, "round_id": 1, "title": "Hash Table Primary Clustering in Linear Probing", "candidate_content": "What is the primary drawback of using Linear Probing `(h(k, i) = (h''(k) + i) % m)` compared to Quadratic Probing or Double Hashing for collision resolution in an open-addressed hash table?", "options_json": [{"id": 1, "text": "Primary clustering where occupied slots form long contiguous chains"}, {"id": 2, "text": "Inability to store negative integer keys"}, {"id": 3, "text": "Excessive dynamic memory allocation overhead"}, {"id": 4, "text": "Requirement of quadratic hash functions"}], "marks": 2.0, "difficulty": "Medium", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 4}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (117, 224, 1, '{"id": 224, "round_id": 1, "title": "Cache Hit Ratio & Effective Memory Access Time (EMAT)", "candidate_content": "A processor has an L1 cache access time of 2 ns and main memory access time of 50 ns. If the L1 cache hit ratio is `90%` (0.90), what is the Effective Memory Access Time (EMAT)?", "options_json": [{"id": 1, "text": "4.8 ns"}, {"id": 2, "text": "6.8 ns"}, {"id": 3, "text": "7.0 ns"}, {"id": 4, "text": "9.2 ns"}], "marks": 2.0, "difficulty": "Medium", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 2}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (118, 225, 1, '{"id": 225, "round_id": 1, "title": "Bitmask Generation of Power Set Subsets", "candidate_content": "For a set `S = {''A'', ''B'', ''C'', ''D''}` with 4 elements, bitmasks from `0` to `15` (`0b0000` to `0b1111`) are used to represent all subsets. Which subset is represented by the integer bitmask `11` (binary `1011` where LSB index 0 corresponds to ''A'')?", "options_json": [{"id": 1, "text": "{''A'', ''B'', ''D''}"}, {"id": 2, "text": "{''A'', ''C'', ''D''}"}, {"id": 3, "text": "{''B'', ''C'', ''D''}"}, {"id": 4, "text": "{''A'', ''B'', ''C''}"}], "marks": 2.0, "difficulty": "Medium", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 3}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (119, 226, 1, '{"id": 226, "round_id": 1, "title": "LRU Page Replacement Fault Count", "candidate_content": "Consider a system with 3 initially empty physical page frames. The sequence of page references is: `[1, 2, 3, 2, 4, 1, 3]`. Using the Least Recently Used (LRU) page replacement algorithm, how many total page faults occur?", "options_json": [{"id": 1, "text": "4"}, {"id": 2, "text": "5"}, {"id": 3, "text": "6"}, {"id": 4, "text": "7"}], "marks": 2.0, "difficulty": "Hard", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 9}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (120, 227, 1, '{"id": 227, "round_id": 1, "title": "TCP Window Size & Bandwidth-Delay Product (BDP)", "candidate_content": "A high-speed cross-continental fiber link has a capacity of 10 Gbps and a round-trip time (RTT) of 80 milliseconds. What is the Bandwidth-Delay Product (BDP) required for a single TCP connection to fully saturate the pipe?", "options_json": [{"id": 1, "text": "10 Megabytes"}, {"id": 2, "text": "80 Megabytes"}, {"id": 3, "text": "100 Megabytes"}, {"id": 4, "text": "800 Megabytes"}], "marks": 2.0, "difficulty": "Hard", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 10}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (121, 228, 1, '{"id": 228, "round_id": 1, "title": "Truth Table Verification for Resource Authorization", "candidate_content": "An API gateway evaluates access with the rule: `Allow = (is_owner || is_admin) && !is_suspended`. Under which of the following combinations is access GRANTED?", "options_json": [{"id": 1, "text": "is_owner = False, is_admin = True, is_suspended = False"}, {"id": 2, "text": "is_owner = True, is_admin = False, is_suspended = True"}, {"id": 3, "text": "is_owner = False, is_admin = False, is_suspended = False"}, {"id": 4, "text": "is_owner = True, is_admin = True, is_suspended = True"}], "marks": 2.0, "difficulty": "Easy", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 1}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (122, 229, 1, '{"id": 229, "round_id": 1, "title": "Balanced Binary Search Tree Minimum Height", "candidate_content": "What is the minimum possible height of a balanced Binary Search Tree containing `N = 1000` distinct nodes (defining height of a single-node tree as 0)?", "options_json": [{"id": 1, "text": "8"}, {"id": 2, "text": "9"}, {"id": 3, "text": "10"}, {"id": 4, "text": "11"}], "marks": 2.0, "difficulty": "Medium", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 4}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (123, 230, 1, '{"id": 230, "round_id": 1, "title": "Data Compression Ratio & Space Savings", "candidate_content": "An uncompressed text file contains 10,000 characters encoded in standard 8-bit ASCII (80,000 bits total). After applying Huffman variable-length prefix coding, the average character length is reduced to 3.2 bits. What percentage of space savings is achieved?", "options_json": [{"id": 1, "text": "40%"}, {"id": 2, "text": "50%"}, {"id": 3, "text": "60%"}, {"id": 4, "text": "65%"}], "marks": 2.0, "difficulty": "Medium", "time_limit_seconds": 90, "question_type": "mcq", "competency_id": 2}'::jsonb, '2026-09-06 03:08:34.388025') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (124, 231, 1, '{"id": 231, "round_id": 3, "title": "B+ Tree Indexing vs Hash Index Characteristics", "candidate_content": "Why are B+ Tree indices preferred over Hash indices as the primary default index structure in relational database storage engines (such as InnoDB)?", "options_json": [{"id": 1, "text": "B+ Trees support efficient range scans (BETWEEN, <, >) and ordered traversals"}, {"id": 2, "text": "B+ Trees offer O(1) exact point lookups compared to O(N) for Hash indices"}, {"id": 3, "text": "Hash indices require contiguous physical disk blocks"}, {"id": 4, "text": "B+ Trees eliminate disk I/O entirely"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 7}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (125, 232, 1, '{"id": 232, "round_id": 3, "title": "Write-Ahead Logging (WAL) & Durability", "candidate_content": "In relational DBMS transaction engines, how does the Write-Ahead Logging (WAL) protocol guarantee ACID Durability without immediately flushing dirty table pages to disk on commit?", "options_json": [{"id": 1, "text": "Changes are sequentially appended to an immutable append-only log on disk before commit acknowledges"}, {"id": 2, "text": "Dirty pages are compressed and stored directly into CPU registers"}, {"id": 3, "text": "Transactions bypass cache and write directly to non-volatile RAM"}, {"id": 4, "text": "Table pages are locked permanently until database restart"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 7}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (126, 233, 1, '{"id": 233, "round_id": 3, "title": "Database Isolation Levels: Read Committed vs Repeatable Read", "candidate_content": "Under the SQL standard `READ COMMITTED` isolation level, which concurrency anomaly can still occur that is strictly prevented under `REPEATABLE READ`?", "options_json": [{"id": 1, "text": "Dirty Read"}, {"id": 2, "text": "Non-Repeatable (Fuzzy) Read"}, {"id": 3, "text": "Dirty Write"}, {"id": 4, "text": "Lost Update during row lock"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 7}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (127, 234, 1, '{"id": 234, "round_id": 3, "title": "Database Connection Pool Starvation Root Cause", "candidate_content": "An API service under peak load experiences `PoolTimeoutError: Connection not available`. System metrics show database CPU is at 8% and memory is stable. What is the most likely software architecture defect?", "options_json": [{"id": 1, "text": "Database connections are opened in HTTP handlers but not released in a finally/context manager block during errors"}, {"id": 2, "text": "The database storage disk is running out of inodes"}, {"id": 3, "text": "The query cache has exceeded 100% capacity"}, {"id": 4, "text": "PostgreSQL is executing automatic VACUUM on unindexed tables"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 7}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (128, 235, 1, '{"id": 235, "round_id": 3, "title": "Database Sharding vs Horizontal Partitioning", "candidate_content": "What is the key architectural difference between database Horizontal Partitioning and Database Sharding?", "options_json": [{"id": 1, "text": "Sharding distributes partitions across multiple distinct physical database server instances, whereas horizontal partitioning typically resides on a single instance"}, {"id": 2, "text": "Partitioning splits tables column-wise, whereas sharding splits tables row-wise"}, {"id": 3, "text": "Sharding is only possible in NoSQL databases"}, {"id": 4, "text": "Horizontal partitioning requires distributed 2-Phase Commit"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 7}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (129, 236, 1, '{"id": 236, "round_id": 3, "title": "Mutex vs Counting Semaphore Synchronization", "candidate_content": "What is the primary operational distinction between a Binary Mutex and a Counting Semaphore initialized to count 1?", "options_json": [{"id": 1, "text": "A Mutex enforces ownership: only the specific thread that acquired/locked the Mutex can unlock it"}, {"id": 2, "text": "A Counting Semaphore can only be used between separate processes, not threads"}, {"id": 3, "text": "A Mutex allows up to 2 concurrent threads"}, {"id": 4, "text": "A Semaphore disables CPU interrupts upon lock"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 9}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (130, 237, 1, '{"id": 237, "round_id": 3, "title": "Compare-And-Swap (CAS) & Lock-Free Atomic Primitives", "candidate_content": "How do lock-free data structures (such as `AtomicInteger` in Java or `std::atomic` in C++) achieve thread-safe updates without using OS mutex locks?", "options_json": [{"id": 1, "text": "Using hardware-supported atomic Compare-And-Swap (CAS) CPU instructions in an optimistic retry loop"}, {"id": 2, "text": "By pausing the OS thread scheduler during the update"}, {"id": 3, "text": "By duplicating memory addresses per CPU core"}, {"id": 4, "text": "By converting concurrent reads into serial disk writes"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 9}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (131, 238, 1, '{"id": 238, "round_id": 3, "title": "Thread Context Switching Overhead Components", "candidate_content": "When an OS pre-empts Thread A and switches execution to Thread B, which of the following is a direct source of performance overhead?", "options_json": [{"id": 1, "text": "Saving/restoring CPU registers, program counter, and CPU cache/TLB invalidation"}, {"id": 2, "text": "Recompiling the thread binary code into bytecode"}, {"id": 3, "text": "Re-allocating the thread heap memory space"}, {"id": 4, "text": "Zeroing out physical RAM blocks"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 9}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (132, 239, 1, '{"id": 239, "round_id": 3, "title": "Translation Lookaside Buffer (TLB) Miss Resolution", "candidate_content": "In a modern CPU with Virtual Memory, what happens immediately when a Translation Lookaside Buffer (TLB) miss occurs during a memory read?", "options_json": [{"id": 1, "text": "The hardware Page Table Walker traverses multi-level page tables in RAM to resolve the virtual-to-physical address mapping"}, {"id": 2, "text": "The OS generates a Fatal Page Fault and terminates the process"}, {"id": 3, "text": "The CPU swaps the active process to secondary storage swap space"}, {"id": 4, "text": "The memory controller restarts the CPU core"}], "marks": 2.0, "difficulty": "Hard", "question_type": "mcq", "competency_id": 9}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (133, 240, 1, '{"id": 240, "round_id": 3, "title": "Thread Starvation vs Deadlock Distinction", "candidate_content": "What is the key technical difference between Thread Starvation and Deadlock in concurrent systems?", "options_json": [{"id": 1, "text": "In starvation, some threads continue making progress while others wait indefinitely; in deadlock, no involved thread can make progress"}, {"id": 2, "text": "Starvation only occurs on single-core CPUs; deadlock only occurs on multi-core CPUs"}, {"id": 3, "text": "Deadlock can be resolved by increasing thread priority; starvation cannot"}, {"id": 4, "text": "Starvation is an OS hardware fault; deadlock is a network protocol error"}], "marks": 2.0, "difficulty": "Easy", "question_type": "mcq", "competency_id": 9}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (134, 241, 1, '{"id": 241, "round_id": 3, "title": "TLS 1.3 Handshake Round Trips vs TLS 1.2", "candidate_content": "How many round-trip times (RTTs) are required to complete a full initial cryptographic handshake in TLS 1.3 compared to TLS 1.2?", "options_json": [{"id": 1, "text": "TLS 1.3 requires 1-RTT (or 0-RTT on resumption); TLS 1.2 requires 2-RTTs"}, {"id": 2, "text": "TLS 1.3 requires 3-RTTs; TLS 1.2 requires 1-RTT"}, {"id": 3, "text": "Both protocols require exactly 2-RTTs"}, {"id": 4, "text": "TLS 1.3 eliminates the underlying TCP handshake"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 10}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (135, 242, 1, '{"id": 242, "round_id": 3, "title": "TCP 3-Way Handshake Connection Establishment", "candidate_content": "What is the exact sequence of TCP packet flags exchanged between client and server to establish a reliable stream connection?", "options_json": [{"id": 1, "text": "Client sends SYN -> Server responds SYN-ACK -> Client sends ACK"}, {"id": 2, "text": "Client sends ACK -> Server responds SYN -> Client sends ACK"}, {"id": 3, "text": "Client sends SYN -> Server responds ACK -> Client sends FIN"}, {"id": 4, "text": "Client sends PING -> Server responds PONG -> Client sends DATA"}], "marks": 2.0, "difficulty": "Easy", "question_type": "mcq", "competency_id": 10}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (136, 243, 1, '{"id": 243, "round_id": 3, "title": "CORS Preflight OPTIONS Request Trigger Conditions", "candidate_content": "Under the Cross-Origin Resource Sharing (CORS) standard, which of the following triggers a browser to send an automatic preflight `OPTIONS` request before the actual HTTP request?", "options_json": [{"id": 1, "text": "A PUT or DELETE request, or a request with custom headers like `Authorization: Bearer <token>`"}, {"id": 2, "text": "Any standard GET request without custom headers"}, {"id": 3, "text": "A POST request with `Content-Type: application/x-www-form-urlencoded`"}, {"id": 4, "text": "An image loaded via standard `<img src=''...''>` HTML tag"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 11}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (137, 244, 1, '{"id": 244, "round_id": 3, "title": "DNS Recursive vs Iterative Query Resolution", "candidate_content": "When a client machine queries a local Recursive DNS Resolver for `api.example.com`, what role does the recursive resolver perform on behalf of the client?", "options_json": [{"id": 1, "text": "It queries the Root DNS server, TLD (.com) server, and Authoritative DNS server iteratively until the final IP is obtained, then caches and returns it to the client"}, {"id": 2, "text": "It immediately forwards the request to the client browser to resolve directly"}, {"id": 3, "text": "It performs an SSL/TLS decryption on the domain name"}, {"id": 4, "text": "It redirects the client HTTP socket to port 53"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 10}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (138, 245, 1, '{"id": 245, "round_id": 3, "title": "HTTP/2 vs HTTP/3 Protocol Transport Architecture", "candidate_content": "What is the primary underlying transport protocol innovation of HTTP/3 that completely eliminates TCP Head-of-Line (HOL) blocking at the transport layer?", "options_json": [{"id": 1, "text": "QUIC protocol built on top of UDP with stream-level packet loss recovery"}, {"id": 2, "text": "Multiple parallel TCP sockets opened per domain"}, {"id": 3, "text": "SCTP protocol over raw Ethernet frames"}, {"id": 4, "text": "WebSocket compression frames"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 10}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (139, 246, 1, '{"id": 246, "round_id": 3, "title": "Liskov Substitution Principle (LSP) Violation Scenario", "candidate_content": "Which of the following object-oriented designs is a classic violation of the Liskov Substitution Principle (LSP)?", "options_json": [{"id": 1, "text": "A `Square` subclass inherits from `Rectangle`, overriding `setWidth()` to simultaneously alter `height` and breaking caller assumptions of independent dimensions"}, {"id": 2, "text": "A `Car` class implements a `Vehicle` interface and provides a `drive()` method"}, {"id": 3, "text": "A `UserRepository` class implements a `Repository` interface using Dependency Injection"}, {"id": 4, "text": "A `Circle` class encapsulates a private `radius` field with public getters"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 6}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (140, 247, 1, '{"id": 247, "round_id": 3, "title": "Factory Method vs Abstract Factory Design Pattern", "candidate_content": "When should an architect select the **Abstract Factory** design pattern over a simple **Factory Method**?", "options_json": [{"id": 1, "text": "When a system needs to create families of related or dependent product objects (e.g. MacButton + MacCheckbox vs WinButton + WinCheckbox) without specifying concrete classes"}, {"id": 2, "text": "When only a single object needs to be instantiated globally across the entire application lifetime"}, {"id": 3, "text": "When adding dynamic behavior to an existing object at runtime without subclassing"}, {"id": 4, "text": "When converting the interface of a legacy class into an interface expected by clients"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 6}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (141, 248, 1, '{"id": 248, "round_id": 3, "title": "Observer Pattern & Event-Driven Decoupling", "candidate_content": "What is the primary architectural advantage of using the **Observer Pattern** (Publish-Subscribe) for inter-component communication in GUI or event-driven applications?", "options_json": [{"id": 1, "text": "Loose coupling: Subject maintains a list of dependents without knowing their concrete implementations, notifying them via a common interface"}, {"id": 2, "text": "Elimination of dynamic memory allocations during event dispatch"}, {"id": 3, "text": "Guaranteeing strictly synchronous sequential execution across CPU threads"}, {"id": 4, "text": "Automatic persistence of events to a SQL database"}], "marks": 2.0, "difficulty": "Easy", "question_type": "mcq", "competency_id": 6}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (142, 249, 1, '{"id": 249, "round_id": 3, "title": "Dependency Injection & Inversion of Control (IoC)", "candidate_content": "Why is Dependency Injection (DI) considered a best practice in enterprise software engineering?", "options_json": [{"id": 1, "text": "It decouples class implementation from object construction, allowing dependencies to be swapped for mock implementations during unit testing"}, {"id": 2, "text": "It compiles application code into native assembly binaries automatically"}, {"id": 3, "text": "It replaces relational database queries with memory pointers"}, {"id": 4, "text": "It forces all class methods to execute in parallel"}], "marks": 2.0, "difficulty": "Easy", "question_type": "mcq", "competency_id": 6}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (143, 250, 1, '{"id": 250, "round_id": 3, "title": "Microservices Circuit Breaker Pattern State Transitions", "candidate_content": "In a distributed microservice architecture, how does the **Circuit Breaker** pattern prevent cascading service failures when a downstream dependency is failing?", "options_json": [{"id": 1, "text": "Transitions from CLOSED to OPEN after error threshold is breached, immediately failing fast without calling downstream, then enters HALF-OPEN to probe recovery"}, {"id": 2, "text": "Spawns 10x more worker threads to retry failed calls continuously"}, {"id": 3, "text": "Caches all failed requests directly on client browsers forever"}, {"id": 4, "text": "Reroutes all database queries to unencrypted HTTP endpoints"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 15}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (144, 251, 1, '{"id": 251, "round_id": 3, "title": "JSON Web Token (JWT) Security: Signature vs Encryption", "candidate_content": "A developer stores a raw plaintext database password inside a standard HMAC-SHA256 signed JSON Web Token (JWT) payload. Why is this a critical security vulnerability?", "options_json": [{"id": 1, "text": "A standard JWT signature only provides cryptographic integrity and authenticity; the payload is only Base64URL-encoded and can be read by anyone"}, {"id": 2, "text": "HMAC-SHA256 automatically reverses plaintext into public key pairs"}, {"id": 3, "text": "JWT tokens cannot be transmitted over HTTPS"}, {"id": 4, "text": "The signature expires after 5 seconds"}], "marks": 2.0, "difficulty": "Easy", "question_type": "mcq", "competency_id": 11}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (145, 252, 1, '{"id": 252, "round_id": 3, "title": "SQL Injection Prevention Mechanism", "candidate_content": "Why does using **Parameterized Queries (Prepared Statements)** completely eliminate SQL Injection vulnerabilities?", "options_json": [{"id": 1, "text": "The database driver compiles the SQL statement structure beforehand and treats user input strictly as literal data parameters, never executable SQL code"}, {"id": 2, "text": "It strips all quotation marks and apostrophes from user inputs"}, {"id": 3, "text": "It converts all SQL statements to NoSQL documents"}, {"id": 4, "text": "It runs queries inside a dedicated web application firewall (WAF)"}], "marks": 2.0, "difficulty": "Easy", "question_type": "mcq", "competency_id": 7}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (146, 253, 1, '{"id": 253, "round_id": 3, "title": "Cross-Site Request Forgery (CSRF) & SameSite Cookie Attribute", "candidate_content": "How does setting `SameSite=Strict` on authentication session cookies defend web applications against Cross-Site Request Forgery (CSRF) attacks?", "options_json": [{"id": 1, "text": "The browser will refuse to send the cookie on any cross-site request originating from a third-party domain"}, {"id": 2, "text": "It encrypts the cookie using the client''s SSL private certificate"}, {"id": 3, "text": "It prevents JavaScript from accessing the cookie via document.cookie"}, {"id": 4, "text": "It limits the cookie expiration to the active tab session"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 11}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (147, 254, 1, '{"id": 254, "round_id": 3, "title": "Rate Limiting: Token Bucket vs Leaky Bucket Algorithms", "candidate_content": "What is the key behavioral difference between the **Token Bucket** and **Leaky Bucket** rate-limiting algorithms when handling bursts of incoming traffic?", "options_json": [{"id": 1, "text": "Token Bucket allows bursts of requests up to bucket capacity while maintaining a constant fill rate; Leaky Bucket outputs requests at a strictly smooth, constant rate"}, {"id": 2, "text": "Leaky Bucket allows infinite bursts; Token Bucket drops all burst traffic"}, {"id": 3, "text": "Token Bucket can only be used on TCP level; Leaky Bucket works on HTTP level"}, {"id": 4, "text": "Leaky Bucket requires distributed Redis memory; Token Bucket requires local CPU registers"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 11}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (148, 255, 1, '{"id": 255, "round_id": 3, "title": "Idempotent HTTP Methods in RESTful API Architecture", "candidate_content": "According to RFC 9110 (HTTP Semantics), which of the following HTTP methods are strictly defined as **Idempotent**?", "options_json": [{"id": 1, "text": "GET, PUT, DELETE, HEAD, and OPTIONS"}, {"id": 2, "text": "POST, PATCH, and CONNECT"}, {"id": 3, "text": "Only GET and POST"}, {"id": 4, "text": "POST and PUT only"}], "marks": 2.0, "difficulty": "Easy", "question_type": "mcq", "competency_id": 11}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (149, 256, 1, '{"id": 256, "round_id": 3, "title": "Git Fast-Forward Merge vs 3-Way Merge Commit", "candidate_content": "When executing `git merge feature-branch` into `main`, under what exact condition will Git perform a **Fast-Forward (FF)** merge instead of creating a 3-way merge commit?", "options_json": [{"id": 1, "text": "When the HEAD of `main` is an ancestor of `feature-branch` and no new commits have occurred on `main` since branching"}, {"id": 2, "text": "When both branches have exactly the same number of commits"}, {"id": 3, "text": "When all commits on feature-branch are signed with GPG keys"}, {"id": 4, "text": "When merge conflicts are resolved automatically by Git"}], "marks": 2.0, "difficulty": "Easy", "question_type": "mcq", "competency_id": 12}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (150, 257, 1, '{"id": 257, "round_id": 3, "title": "Cache-Aside (Lazy-Loading) vs Write-Through Caching Pattern", "candidate_content": "In high-throughput microservice caching architectures, what is the defining characteristic of the **Cache-Aside** pattern?", "options_json": [{"id": 1, "text": "The application code first checks cache; on cache miss, it reads from database, updates the cache, and returns data to client"}, {"id": 2, "text": "The database writes to the cache synchronously upon every table INSERT/UPDATE"}, {"id": 3, "text": "Cache entries are persisted to disk and never expire"}, {"id": 4, "text": "The cache intercepts network sockets directly at the OS kernel level"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 15}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (151, 258, 1, '{"id": 258, "round_id": 4, "title": "Fix Infinite Recursion in Graph Cycle Detection (DFS)", "candidate_content": "The following Python function is designed to detect if a directed graph has a cycle using Depth-First Search (DFS). However, it contains a bug where it causes a `RecursionError: maximum recursion depth exceeded` on cyclical graphs because node state tracking is missing. Fix the function so that it correctly returns `True` if a cycle exists and `False` otherwise.", "candidate_code_template": "import sys\nfrom collections import defaultdict\n\ndef has_cycle(num_nodes, edges):\n    adj = defaultdict(list)\n    for u, v in edges:\n        adj[u].append(v)\n    \n    # BUG: Node state tracking is incomplete\n    def dfs(node):\n        for neighbor in adj[node]:\n            if dfs(neighbor):\n                return True\n        return False\n\n    for i in range(num_nodes):\n        if dfs(i):\n            return True\n    return False\n\ndef main():\n    lines = sys.stdin.read().strip().splitlines()\n    if not lines:\n        return\n    n, m = map(int, lines[0].split())\n    edges = []\n    for line in lines[1:m+1]:\n        u, v = map(int, line.split())\n        edges.append((u, v))\n    print(\"true\" if has_cycle(n, edges) else \"false\")\n\nif __name__ == ''__main__'':\n    main()\n", "marks": 5.0, "difficulty": "Hard", "question_type": "debugging", "competency_id": 13}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (152, 259, 1, '{"id": 259, "round_id": 4, "title": "Fix Off-by-One in Sliding Window Maximum Monotonic Deque", "candidate_content": "The following function computes the maximum value in each sliding window of size `K` across an array of numbers using a monotonic deque. It contains an off-by-one index bug when evicting out-of-window elements and populating the output. Fix the function so that it prints space-separated maximum values for all valid windows.", "candidate_code_template": "import sys\nfrom collections import deque\n\ndef max_sliding_window(nums, k):\n    if not nums or k <= 0:\n        return []\n    dq = deque()\n    res = []\n    \n    for i in range(len(nums)):\n        # BUG: Incorrect out-of-bounds eviction condition\n        if dq and dq[0] < i - k:\n            dq.popleft()\n            \n        while dq and nums[dq[-1]] < nums[i]:\n            dq.pop()\n            \n        dq.append(i)\n        \n        # BUG: Incorrect starting index for recording window max\n        if i >= k:\n            res.append(nums[dq[0]])\n            \n    return res\n\ndef main():\n    lines = sys.stdin.read().strip().splitlines()\n    if not lines:\n        return\n    k = int(lines[0].strip())\n    nums = list(map(int, lines[1].split()))\n    result = max_sliding_window(nums, k)\n    print(\" \".join(map(str, result)))\n\nif __name__ == ''__main__'':\n    main()\n", "marks": 5.0, "difficulty": "Medium", "question_type": "debugging", "competency_id": 13}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (153, 260, 1, '{"id": 260, "round_id": 4, "title": "Fix Data Corruption in LRU Cache Double-Linked List Eviction", "candidate_content": "The following implementation of an LRU (Least Recently Used) Cache uses a hash map and a doubly linked list with dummy head and tail. It contains a pointer reassignment bug in `_remove` and `_add` methods that causes key lookup errors or orphaned nodes after reaching max capacity. Fix the pointer manipulation bugs.", "candidate_code_template": "import sys\n\nclass Node:\n    def __init__(self, key=0, value=0):\n        self.key = key\n        self.value = value\n        self.prev = None\n        self.next = None\n\nclass LRUCache:\n    def __init__(self, capacity: int):\n        self.capacity = capacity\n        self.cache = {}\n        self.head = Node()\n        self.tail = Node()\n        self.head.next = self.tail\n        self.tail.prev = self.head\n\n    def _remove(self, node: Node):\n        # BUG: Incorrect pointer reassignment\n        node.prev = node.next\n        node.next = node.prev\n\n    def _add(self, node: Node):\n        # Insert right after head\n        node.prev = self.head\n        node.next = self.head.next\n        self.head.next = node\n        # BUG: missing node.next.prev link\n\n    def get(self, key: int) -> int:\n        if key in self.cache:\n            node = self.cache[key]\n            self._remove(node)\n            self._add(node)\n            return node.value\n        return -1\n\n    def put(self, key: int, value: int) -> None:\n        if key in self.cache:\n            self._remove(self.cache[key])\n        node = Node(key, value)\n        self.cache[key] = node\n        self._add(node)\n        if len(self.cache) > self.capacity:\n            lru = self.tail.prev\n            self._remove(lru)\n            del self.cache[lru.key]\n\ndef main():\n    lines = sys.stdin.read().strip().splitlines()\n    if not lines:\n        return\n    cap = int(lines[0].strip())\n    lru = LRUCache(cap)\n    out = []\n    for line in lines[1:]:\n        parts = line.split()\n        if parts[0] == ''PUT'':\n            lru.put(int(parts[1]), int(parts[2]))\n        elif parts[0] == ''GET'':\n            out.append(str(lru.get(int(parts[1]))))\n    print(\" \".join(out))\n\nif __name__ == ''__main__'':\n    main()\n", "marks": 5.0, "difficulty": "Hard", "question_type": "debugging", "competency_id": 13}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (154, 261, 1, '{"id": 261, "round_id": 9, "title": "Customer Retention Cohort & Churn Rate Analysis", "candidate_content": "An enterprise SaaS business acquires a January cohort of 1,000 customers. At Month 1, 800 customers remain active. At Month 2, 720 customers remain active. At Month 3, 648 customers remain active. What is the constant compound monthly churn rate of this cohort from Month 1 to Month 3?", "options_json": [{"id": 1, "text": "8.0%"}, {"id": 2, "text": "10.0%"}, {"id": 3, "text": "12.5%"}, {"id": 4, "text": "15.0%"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 31}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (155, 262, 1, '{"id": 262, "round_id": 10, "title": "Year-over-Year (YoY) Quarterly Growth Rate via LAG() Window Function", "candidate_content": "Given a table `quarterly_sales (year INT, quarter INT, revenue NUMERIC)`, write a standard SQL query to calculate each quarter''s Year-over-Year (YoY) percentage revenue growth compared to the exact same quarter of the previous year. Columns returned should be: `year`, `quarter`, `revenue`, and `yoy_growth_pct`.", "marks": 4.0, "difficulty": "Medium", "question_type": "sql", "competency_id": 33}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (156, 263, 1, '{"id": 263, "round_id": 10, "title": "Identify Consecutive Active Login Streaks via Gaps-and-Islands CTE", "candidate_content": "Given a table `user_logins (user_id INT, login_date DATE)`, write a SQL query to identify users who logged in for at least 3 consecutive calendar days. Output unique `user_id` values.", "marks": 4.0, "difficulty": "Hard", "question_type": "sql", "competency_id": 33}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (157, 264, 1, '{"id": 264, "round_id": 10, "title": "Dynamic Two-Way Matrix Lookup in Excel", "candidate_content": "In an Excel financial model with products listed in rows (A2:A100) and months listed in columns (B1:M1), which formula dynamically retrieves the exact sales value for product in cell P2 and month in cell Q2 without hardcoding ranges?", "marks": 2.0, "difficulty": "Easy", "question_type": "mcq", "competency_id": 35}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (158, 265, 1, '{"id": 265, "round_id": 12, "title": "Tableau Level of Detail (LOD) FIXED vs INCLUDE Expressions", "candidate_content": "In Tableau Desktop, what is the primary behavioral difference between `{FIXED [Region] : SUM([Sales])}` and `{INCLUDE [Region] : SUM([Sales])}`?", "options_json": [{"id": 1, "text": "`FIXED` computes the aggregate strictly at the Region dimension level regardless of the view''s granularity, whereas `INCLUDE` adds Region to whatever dimensions are already present in the view"}, {"id": 2, "text": "`FIXED` cannot be used in calculated fields; `INCLUDE` can only be used on measures"}, {"id": 3, "text": "`FIXED` is calculated after Dimension filters; `INCLUDE` is calculated before Context filters"}, {"id": 4, "text": "`INCLUDE` filters out all NULL regions automatically"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 37}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (159, 266, 1, '{"id": 266, "round_id": 12, "title": "Visual Perception & Chart Selection for Net Sentiment Scores", "candidate_content": "A Business Intelligence analyst needs to display customer satisfaction survey responses across 10 service categories containing both positive (+40% to +100%) and negative (-40% to -10%) net promoter ratings. Which chart type provides the highest cognitive clarity for visual comparison across the zero baseline?", "options_json": [{"id": 1, "text": "Diverging Horizontal Bar Chart anchored at the zero axis"}, {"id": 2, "text": "Pie chart with 10 colored slices"}, {"id": 3, "text": "Stacked Area chart"}, {"id": 4, "text": "Radar chart with filled polygons"}], "marks": 2.0, "difficulty": "Easy", "question_type": "mcq", "competency_id": 50}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (160, 267, 1, '{"id": 267, "round_id": 12, "title": "Tableau Order of Operations: Context Filters vs Dimension Filters", "candidate_content": "In Tableau''s Order of Operations, why would an analyst promote a normal Dimension Filter (e.g. `Year = 2026`) to a **Context Filter** (gray pill)?", "options_json": [{"id": 1, "text": "To force the filter to execute BEFORE Top-N filters and FIXED Level of Detail (LOD) calculations"}, {"id": 2, "text": "To hide the filter control from dashboard viewers"}, {"id": 3, "text": "To convert the field from discrete to continuous"}, {"id": 4, "text": "To bypass user security filters"}], "marks": 2.0, "difficulty": "Medium", "question_type": "mcq", "competency_id": 49}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (161, 268, 1, '{"id": 268, "round_id": 12, "title": "Tableau Performance Optimization: Extract Aggregation Strategy", "candidate_content": "A Tableau workbook connected to a 50-million row database table experiences slow rendering on an executive summary dashboard that only displays monthly regional sales. What is the most effective extract optimization technique?", "options_json": [{"id": 1, "text": "Aggregate data to visible dimensions (Month, Region) and hide all unused columns during extract creation"}, {"id": 2, "text": "Convert all numeric measures to string data types"}, {"id": 3, "text": "Switch from Hyper extract format to live CSV file link"}, {"id": 4, "text": "Add 20 floating text objects to cache rendering"}], "marks": 2.0, "difficulty": "Easy", "question_type": "mcq", "competency_id": 37}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (162, 269, 1, '{"id": 269, "round_id": 13, "title": "Handling Data Skew & Salting Join Keys in Large-Scale Analytics Pipelines", "candidate_content": "In your data analytics projects, suppose you encounter a severe data skew issue where 90% of order transactions belong to a single default `customer_id = 0` (Guest Checkout), causing distributed joins to bottle-neck on a single reducer/worker node. Explain how you would detect this skew and implement key salting or two-stage aggregation to resolve the bottleneck.", "marks": 5.0, "difficulty": "Hard", "question_type": "text_response", "competency_id": 41}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (163, 270, 1, '{"id": 270, "round_id": 13, "title": "Automated Data Drift Detection & Schema Evolution in Production ETL", "candidate_content": "Describe how you implemented or would design an automated data validation and drift detection layer in your analytics pipeline. Address: (1) Handling schema drift (new unexpected columns or changed data types from source APIs), (2) Detecting statistical distribution drift (e.g. sudden drop in non-null rates or mean transaction value), and (3) Automated alerting and quarantine dead-letter queues.", "marks": 5.0, "difficulty": "Hard", "question_type": "text_response", "competency_id": 40}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (164, 271, 1, '{"id": 271, "round_id": 8, "title": "Simulation Scenario 2: Cross-Border Customs Hold & Urgent Shipment Delivery Escalation", "candidate_content": "Customer Interaction Simulation: Candidate manages an urgent international post-sales chat from an enterprise client whose medical equipment shipment is stuck in German customs due to missing import tariff classification documentation. Customer is threatening contract cancellation.", "marks": 10.0, "difficulty": "Hard", "question_type": "multi_chat_simulation", "competency_id": 27}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version_num", "snapshot_json", "created_at") VALUES (165, 272, 1, '{"id": 272, "round_id": 8, "title": "Simulation Scenario 3: Damaged In-Transit High-Value Electronics Return & Express Replacement", "candidate_content": "Customer Interaction Simulation: A customer unboxes a high-end 4K editing monitor purchased for a project deadline, discovering the display panel is cracked and packaging is water-damaged. Customer demands immediate same-day courier replacement before returning the broken unit.", "marks": 10.0, "difficulty": "Hard", "question_type": "multi_chat_simulation", "competency_id": 21}'::jsonb, '2026-09-06 03:19:07.924513') ON CONFLICT DO NOTHING;

